window.__LIZZWORD_DEEP_SHARD && window.__LIZZWORD_DEEP_SHARD("0133", [{"word":"inscribe","ipa_uk":"/ɪnˈskraɪb/","ipa_us":"/ɪnˈskraɪb/","definition_zh":"在石、金属等硬面上刻写文字；在书上题写赠语；把姓名登记入册；使一个图形内接于另一个图形","definition_en":"to write or carve words on a hard surface; to write a dedication in a book; to enter a name in a register; to draw one geometric figure inside another","core_image":"石匠一手扶凿、一手握锤，把名字一笔一画刻进石板，字迹从此留在硬物表面","scene":"考古队员蹲在石壁前，用软刷扫去积尘。A local mason will inscribe the donors' names on the new gatepost.","sceneCN":"这里 inscribe 指「把文字刻写在硬质表面上」（第 1 个义项：在石面刻字）；句意为当地石匠将把捐助者的名字刻在新门柱上。","pos":[{"tag":"vt.","zh":"刻写；题写；登记；使内接"}],"collocations":[{"phrase":"inscribe a name","zh":"刻下名字"},{"phrase":"inscribe a book","zh":"在书上题赠"},{"phrase":"inscribe a date","zh":"刻上日期"},{"phrase":"inscribe a circle","zh":"作内切圆"},{"phrase":"be inscribed on a monument","zh":"被刻在纪念碑上"}],"forms":[{"label":"三单（he/she/it）","form":"inscribes"},{"label":"过去式","form":"inscribed"},{"label":"过去分词","form":"inscribed"},{"label":"现在分词","form":"inscribing"},{"label":"名词（铭文；题记）","form":"inscription"},{"label":"名词（刻写者）","form":"inscriber"}],"derivatives":[{"word":"inscription","pos":"n.","zh":"inscribe + -tion（名词后缀）→ 刻下的文字：铭文、题记"},{"word":"inscriptional","pos":"adj.","zh":"inscription + -al（形容词后缀）→ 铭文式的：与铭文有关的"},{"word":"inscriptive","pos":"adj.","zh":"inscribe + -ive（形容词后缀）→ 具有刻写性质的：题写性的"},{"word":"inscriber","pos":"n.","zh":"inscribe + -er（施事后缀）→ 刻写的人或工具"},{"word":"inscribed","pos":"adj.","zh":"inscribe + -ed（分词形容词后缀）→ 被刻写的；内接的"}],"senses":[{"no":"01","title":"Carve words on a hard surface","titleCN":"在硬面上刻写文字","definition":"to write or cut letters into stone, metal, wood or another hard material","definitionCN":"在石头、金属、木材等硬质材料上写出或刻出文字","example":"A local mason will inscribe the donors' names on the new gatepost.","exampleCN":"当地石匠将把捐助者的名字刻在新门柱上。","why":"in- means 'in or on' and scribere means 'to write'; letters placed onto a hard face are the core act.","whyCN":"in- 表示「进入、在上」，scribere 表示「写」；把字放到硬面上就是核心动作。"},{"no":"02","title":"Write a dedication in a book","titleCN":"在书上题写赠语","definition":"to write a short personal message, usually a dedication, on the title page of a book","definitionCN":"在书的扉页写下简短的私人赠语，通常是题献","example":"The author inscribed the first edition for her old mentor.","exampleCN":"作者在初版书上为她的老师题赠。","why":"the same act of writing on a surface narrows to the title page, where a gift message is placed.","whyCN":"仍是把字写在表面上，只是范围收窄到扉页，用来放赠语。"},{"no":"03","title":"Enter a name in a register","titleCN":"把姓名登记入册","definition":"to record a name officially on a list, roll or register","definitionCN":"把姓名正式记入名单、名册或登记簿","example":"Every new member inscribes a name in the society's roll.","exampleCN":"每位新成员都要在社团名册上登记姓名。","why":"a register is a surface written on for official memory, so inscribe took the administrative sense of enrolling.","whyCN":"名册是为官方记忆而写的表面，因此 inscribe 引申出「登记入册」的行政义。"},{"no":"04","title":"Draw one figure inside another","titleCN":"使图形内接","definition":"to draw a geometric figure inside another so that its vertices touch the outer boundary","definitionCN":"在一个几何图形内画出另一个图形，使其顶点触及外边界","example":"The students inscribed a hexagon in the circle.","exampleCN":"学生们在圆内作了一个内接六边形。","why":"geometry borrowed the verb because the inner figure is literally written inside the outer one, touching its edge.","whyCN":"几何学借用这个动词，因为内层图形确实是「写」在外层图形里面，并触及它的边。"},{"no":"05","title":"Fix something in the memory","titleCN":"把某事铭刻在记忆中","definition":"to fix an idea, lesson or feeling firmly in someone's mind","definitionCN":"把某个观念、教训或情感牢牢固定在某人心中","example":"The lesson was inscribed on his memory for decades.","exampleCN":"那一课在他记忆里铭刻了几十年。","why":"writing on stone is the image behind the mental sense: what is carved does not fade easily.","whyCN":"以石上刻字为喻：刻下的东西不容易磨灭。"},{"no":"06","title":"Stamp lettering on a coin or medal","titleCN":"在钱币或奖章上压印文字","definition":"to stamp or engrave lettering and a design on a coin, medal or seal","definitionCN":"在钱币、奖章或印章上压印或雕刻文字与图案","example":"The mint inscribed the date along the rim of the coin.","exampleCN":"造币厂把年份压印在硬币边缘。","why":"coins carry their legend on a hard metal face, exactly the surface the Latin verb was made for.","whyCN":"钱币把铭文放在坚硬的金属面上，正是这个拉丁动词最初针对的表面。"},{"no":"07","title":"Dedicate a monument with words","titleCN":"为纪念碑题写铭文","definition":"to add a formal engraved statement when a monument or public building is dedicated","definitionCN":"在为纪念碑或公共建筑揭幕时加上正式的刻写说明","example":"They inscribed the memorial with a line from the town's first charter.","exampleCN":"他们为纪念碑刻上了小镇最早宪章中的一句话。","why":"public dedication joins the writing act to collective memory, so the words are meant for every passer-by.","whyCN":"公共题献把书写行为与集体记忆连在一起，文字是写给每个路人看的。"},{"no":"08","title":"Mark an object with an identifying code","titleCN":"在物件上刻标识码","definition":"to mark an object with a serial number or code so that it can be identified","definitionCN":"在物件上刻下编号或代码，以便识别","example":"The lens was inscribed with a tiny serial number near the mount.","exampleCN":"镜片在卡口附近刻有一个很小的序列号。","why":"identifying marks are writing on a surface for later recognition, a practical branch of the same gesture.","whyCN":"识别标记也是把字写在表面上以便日后辨认，是同一动作的实用分支。"}],"etymology":{"intro":{"en":"Inscribe comes from Latin inscribere, 'to write on or write in', built on in- 'in, on' and scribere 'to write'. Scribere goes back to a root meaning 'to cut', which is why carving is the oldest sense.","cn":"inscribe 来自拉丁 inscribere「写在上面、写入」，由 in-「进入、在上」与 scribere「写」构成。scribere 更深的词根意为「刻、划」，所以最古老的义项是刻写。"},"items":[{"era":"LATIN SCRIBERE","en":"Scribere meant 'to write'. Its older root carried the idea of cutting or scratching, and that root is offered as a reconstruction rather than a recorded word.","cn":"scribere 意为「写」。它更早的词根带有「刻、划」的意思，该词根只以重构形式给出，并非有记录的原词。"},{"era":"LATIN INSCRIBERE","en":"In- 'in, on' plus scribere produced inscribere, 'to write on, write in, mark with letters'.","cn":"in-「进入、在上」加 scribere 构成 inscribere，意为「写在上面、写入、用文字标记」。"},{"era":"LATIN INSCRIPTIO","en":"The noun inscriptio, 'a writing upon, an inscription', was formed with the suffix -tio and passed into English as inscription.","cn":"名词 inscriptio 意为「写在上面的文字、铭文」，由后缀 -tio 构成，后来进入英语作 inscription。"},{"era":"ENGLISH 15TH CENTURY","en":"English took the verb through Old French. Early examples concern names and words cut into stone, metal or wood.","cn":"英语经古法语引入这个动词。早期例子都指刻进石头、金属或木材的名字与文字。"},{"era":"GEOMETRY 16TH CENTURY","en":"Translations of Euclid applied the verb to figures drawn inside other figures, and this technical sense has stayed.","cn":"欧几里得著作的译本把这个动词用于画在另一图形内部的图形，这一技术义沿用至今。"},{"era":"SOURCE UNCERTAIN","en":"Source uncertain (first date only): the earliest English use in the book-dedication sense is not precisely dated, although the sense itself is well recorded.","cn":"来源不确定（仅首见年代存疑）：书内题赠义最早的英语用例年代不够确切，但该义项本身记载清楚。"}]},"similar":{"note":{"en":"Group one holds verbs that share the Latin root scribere and are often confused; group two holds verbs of marking and enrolling with a different root.","cn":"第一组是同出拉丁词根 scribere、容易混淆的动词；第二组是词根不同、表示刻记或登记的近义词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"describe","ipa":"/dɪˈskraɪb/","tag":"write down in full","definition":"De- 'down' plus scribere: to write something down in words, hence to tell what it is like.","definitionCN":"de-「向下」加 scribere：把某物用文字写下来，因此指描述其样子。"},{"word":"prescribe","ipa":"/prɪˈskraɪb/","tag":"write beforehand","definition":"Prae- 'before' plus scribere: to write a rule or remedy in advance, hence to order or recommend.","definitionCN":"prae-「在前」加 scribere：事先写下规则或药方，因此指规定或开处方。"},{"word":"subscribe","ipa":"/səbˈskraɪb/","tag":"write underneath","definition":"Sub- 'under' plus scribere: to write one's name beneath a document, hence to agree or pay for a series.","definitionCN":"sub-「在下」加 scribere：在文件下方写下名字，因此指同意或订阅。"},{"word":"ascribe","ipa":"/əˈskraɪb/","tag":"write to a source","definition":"Ad- 'to' plus scribere: to write an origin or cause onto someone, hence to attribute.","definitionCN":"「朝向」前缀加拉丁词根 scribere：把来源或原因写到某人名下，因此指归因。"}]},{"heading":"NEAR MEANING","entries":[{"word":"engrave","ipa":"/ɪnˈɡreɪv/","tag":"cut into a hard surface","definition":"To cut a design or letters into metal or stone; it stresses the cutting tool rather than the act of writing.","definitionCN":"在金属或石头上刻出图案或文字；它强调刀具，而非书写动作。"},{"word":"etch","ipa":"/etʃ/","tag":"cut with acid or a needle","definition":"To mark a surface with a needle or acid, used especially for printing plates; inscribe is broader.","definitionCN":"用针或酸液在表面留下痕迹，尤用于印版；inscribe 的适用范围更广。"},{"word":"enroll","ipa":"/ɪnˈrəʊl/","tag":"enter a name on a list","definition":"To add a name to an official list, especially for a school or organization; it lacks the image of writing on a surface.","definitionCN":"把姓名加入正式名单，尤其是学校或组织；它没有「写在表面上」的形象。"},{"word":"dedicate","ipa":"/ˈdedɪkeɪt/","tag":"set apart for a purpose","definition":"To devote a book, building or work to someone; it names the purpose, while inscribe names the written words.","definitionCN":"把书、建筑或作品献给某人；它说的是用途，inscribe 说的是写下的文字。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real morphemes, real relatives and real fixed phrases.","cn":"正常联想：真实的构语成分、真实同族词与真实固定搭配。"},"normal":[{"en":"in- 'in, on' plus scribere 'write': to write onto a surface.","cn":"in-「进入、在上」+ scribere「写」：把字写到表面上。"},{"en":"The same root runs through describe, prescribe, subscribe and ascribe.","cn":"同一词根贯穿 describe、prescribe、subscribe 与 ascribe。"},{"en":"Inscription keeps the -script- stem visible inside the longer noun.","cn":"inscription 在较长的名词里保留了「写」这一词干。"},{"en":"The word likes hard surfaces: inscribe a name, a date, a ring, a monument.","cn":"这个词偏爱硬表面：刻名字、刻日期、刻戒指、刻纪念碑。"},{"en":"In geometry a polygon is inscribed when all its corners touch the circle.","cn":"几何中，多边形各角都触圆时即为内接。"}],"abstract":[{"en":"Writing letters into stone is like sealing a message inside a wall.","cn":"把字母刻进石头，就像把消息封进墙里。"},{"en":"A name cut into metal can outlive the hand that cut it.","cn":"刻进金属的名字，能比刻它的那只手活得更久。"},{"en":"A figure fitted inside another is a key turning inside its lock.","cn":"一个图形嵌进另一个图形，像钥匙在锁里转动。"}]},"examples":[{"en":"The jeweler inscribed the wedding date inside the ring.","cn":"珠宝匠把婚期刻在戒指内侧。"},{"en":"Please inscribe the book to my daughter.","cn":"请在书上题赠给我的女儿。"},{"en":"A regular pentagon can be inscribed in a circle.","cn":"正五边形可以内接于圆。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「in（进）+ scribe（写）」——把字写进石面里 → 刻写、题写","word":"inscribe"},"root":"拉丁 inscribere「写入、刻上」= in-（进入、在上）+ scribere「写」；scribere 更深词根意为「刻、划」，故本义偏「刻写」。英语 inscribe。","sensesIntro":{"en":"Eight senses follow one gesture: letters are pressed into a surface, and that surface may be stone, a book, a register, a coin, a memory or the inside of a circle.","cn":"八个义项沿同一个动作展开：把字压进表面，而这个表面可以是石头、书页、名册、钱币、记忆，或一个圆的内部。"},"semanticMap":{"core":{"en":"CORE IMAGE: a hand presses letters into a hard face, and the marks stay after the hand is gone.","cn":"核心意象：一只手把字母压进硬面，手离开后痕迹仍在。"},"chain":["WRITE ON STONE","CUT LETTERS","MARK A THING","SET INSIDE","FIX IN MEMORY","DEDICATE PUBLICLY"],"branches":[{"senses":"义项 01、义项 06","en":"MARKING A HARD FACE: naming a coin or a wall is the same act of putting letters onto a surface that will keep them.","cn":"在硬面留字：给钱币或墙壁题字，都是把字放到能留住它的表面上。"},{"senses":"义项 02、义项 08","en":"PERSONAL MARK: a gift message and an identifying code both tie private information to a made object.","cn":"私人标记：赠语与识别码都把私人信息绑在一件人造物上。"},{"senses":"义项 03","en":"LISTED NAME: enrolling writes a name into the official surface of a register.","cn":"名册上的名字：登记就是把姓名写进名册这个官方表面。"},{"senses":"义项 04","en":"GEOMETRIC FIT: the inner figure is written inside the outer one without crossing its edge.","cn":"几何嵌合：内层图形写在外层图形里，不越过它的边。"},{"senses":"义项 05、义项 07","en":"LASTING DEDICATION: memory and public memorials both make the written words stay.","cn":"持久的题献：记忆与公共纪念碑都让写下的字留下来。"}]},"affixes":{"intro":{"en":"Inscribe is a Latin verb whose prefix and root still build a large English family, so each part can be read on its own.","cn":"inscribe 是一个拉丁动词，其前缀与词根仍构成一大串英语词，因此每一部分都能单独读出。"},"latinIntro":{"en":"Latin scribere gives scribe, script, describe, prescribe, subscribe and ascribe; in- adds the direction 'in or on'.","cn":"拉丁 scribere 衍生 scribe、script、describe、prescribe、subscribe 与 ascribe；in- 增添「进入、在上」的方向。"},"items":[{"word":"in-","structure":"in- (Latin prefix, 'in, into, on')","meaning":"in; onto","meaningCN":"进入；在上","example":"The prefix fixes the direction of the writing.","exampleCN":"这个前缀确定书写落到的方向。"},{"word":"scribere","structure":"scribere, scripsi, scriptum (Latin verb, third conjugation)","meaning":"to write","meaningCN":"写","example":"The root names the act of setting letters down.","exampleCN":"这个词根命名「把字母写下」的动作。"},{"word":"inscribe","structure":"in- + scribere","meaning":"to write on","meaningCN":"写在上面；刻写","example":"The mason will inscribe the names.","exampleCN":"石匠将刻下这些名字。"},{"word":"inscription","structure":"inscribe + -tion (action or result)","meaning":"something written on a surface","meaningCN":"刻写下来的文字；铭文","example":"The inscription on the ring is barely legible.","exampleCN":"戒指上的铭文几乎看不清了。"},{"word":"inscriptive","structure":"inscription + -ive (tending to)","meaning":"serving as an inscription","meaningCN":"起铭文作用的","example":"The plaque carries an inscriptive line.","exampleCN":"牌匾上刻着一行题词。"},{"word":"describe","structure":"de- + scribere","meaning":"to write down in words","meaningCN":"用文字写下；描述","example":"She described the stone in detail.","exampleCN":"她详细描述了那块石头。"},{"word":"prescribe","structure":"prae- + scribere","meaning":"to write in advance","meaningCN":"事先写下；规定","example":"The law prescribes a fixed penalty.","exampleCN":"法律规定了固定罚则。"},{"word":"subscribe","structure":"sub- + scribere","meaning":"to write underneath","meaningCN":"写在下方；订阅","example":"He subscribed his name to the petition.","exampleCN":"他在请愿书下方签了名。"}],"latinEntries":[{"word":"scribere","structure":"scribere, scripsi, scriptum (verb, third conjugation)","meaning":"to write","meaningCN":"写"},{"word":"inscribere","structure":"inscribere, inscripsi, inscriptum (verb, third conjugation)","meaning":"to write on, inscribe","meaningCN":"写在上面；刻写"},{"word":"inscriptio","structure":"inscriptio, inscriptionis (f., third declension)","meaning":"a writing upon; an inscription","meaningCN":"写在上面的文字；铭文"},{"word":"scriptum","structure":"scriptum, scripti (n., second declension)","meaning":"something written; a writing","meaningCN":"写下的东西；文字"}],"derivatives":[{"word":"inscription","pos":"n.","zh":"inscribe + -tion（名词后缀）→ 刻下的文字：铭文、题记"},{"word":"inscriptive","pos":"adj.","zh":"inscribe + -ive（形容词后缀）→ 起铭文作用的"},{"word":"inscriber","pos":"n.","zh":"inscribe + -er（施事后缀）→ 刻写者或刻写工具"},{"word":"inscribed","pos":"adj.","zh":"inscribe + -ed（分词形容词后缀）→ 被刻写的；内接的"},{"word":"inscriptional","pos":"adj.","zh":"inscription + -al（形容词后缀）→ 铭文式的"}]}},{"word":"hieroglyph","ipa_uk":"/ˈhaɪərəɡlɪf/","ipa_us":"/ˈhaɪəroʊɡlɪf/","definition_zh":"古埃及象形文字中的单个字符；其他图画文字的字符；难辨认的字迹或符号；有象征意义的图形标记","definition_en":"a single picture character of ancient Egyptian writing; a character of another pictorial script; an illegible mark; a symbolic sign","core_image":"神庙石壁上密排着小鸟、眼睛与蛇的图形，每一个图形都是一个字","scene":"游客举着手电照向神庙内壁。A single hieroglyph above the doorway still carries the name of a forgotten queen.","sceneCN":"这里 hieroglyph 指「古埃及象形文字中的单个字符」（第 1 个义项：单个图形字符）；句意为门楣上方的一个象形字符仍带着一位被遗忘王后的名字。","pos":[{"tag":"n.","zh":"象形文字字符；难辨的符号；图形标记"}],"collocations":[{"phrase":"Egyptian hieroglyph","zh":"埃及象形文字字符"},{"phrase":"carved hieroglyph","zh":"刻出的象形字符"},{"phrase":"read a hieroglyph","zh":"辨认象形字符"},{"phrase":"a hieroglyph for water","zh":"表示水的象形字符"},{"phrase":"hieroglyphs on the wall","zh":"墙上的象形文字"}],"forms":[{"label":"单数","form":"hieroglyph"},{"label":"复数","form":"hieroglyphs"},{"label":"相关形容词","form":"hieroglyphic"},{"label":"集合名词（文字体系）","form":"hieroglyphics"},{"label":"相关名词（研究者）","form":"hieroglyphist"}],"derivatives":[{"word":"hieroglyphic","pos":"adj./n.","zh":"hieroglyph + -ic（形容词与名词后缀）→ 象形文字的；象形文字体系"},{"word":"hieroglyphics","pos":"n.","zh":"hieroglyphic + -s（集合名词后缀）→ 象形文字体系"},{"word":"hieroglyphical","pos":"adj.","zh":"hieroglyphic + -al（形容词后缀）→ 象形文字的（旧式变体）"},{"word":"hieroglyphically","pos":"adv.","zh":"hieroglyphical + -ly（副词后缀）→ 以象形文字方式"},{"word":"hieroglyphist","pos":"n.","zh":"hieroglyph + -ist（从事者后缀）→ 研究象形文字的人"}],"senses":[{"no":"01","title":"A single Egyptian picture character","titleCN":"古埃及单个象形字符","definition":"one character of the ancient Egyptian script, usually a picture standing for a word, a sound or an idea","definitionCN":"古埃及文字中的一个字符，通常是一幅图画，代表一个词、一个音或一个概念","example":"A single hieroglyph above the doorway still carries the name of a forgotten queen.","exampleCN":"门楣上方的一个象形字符仍带着一位被遗忘王后的名字。","why":"hieros means 'sacred' and glyphein means 'to carve'; one carved sacred sign is the unit the word names.","whyCN":"hieros 意为「神圣」，glyphein 意为「雕刻」；一个刻出的神圣符号就是这个词所指的单位。"},{"no":"02","title":"A character of another pictorial script","titleCN":"其他图画文字的字符","definition":"a sign of a similar picture-based writing system, such as Maya or Hittite writing","definitionCN":"其他以图画为基础的文字体系中的符号，如玛雅或赫梯文字","example":"The Maya carved a hieroglyph for the sun on the lintel.","exampleCN":"玛雅人在门楣上刻了一个表示太阳的象形字符。","why":"the Greek term was extended by scholars to picture scripts elsewhere, so the unit sense travels beyond Egypt.","whyCN":"学者把这个希腊术语推广到其他地方的图画文字，因此「单个字符」义超出了埃及。"},{"no":"03","title":"A sacred carved symbol","titleCN":"神圣的雕刻符号","definition":"a sacred sign cut into temple stone, often read as a blessing or a name of a god","definitionCN":"刻在神庙石面上的神圣符号，常被读作祝福或神名","example":"Priests read the hieroglyph above the gate as a blessing.","exampleCN":"祭司把门上方的雕刻符号读作祝福。","why":"the earliest Greek use concerns temple carvings, so the religious sense is older than the writing-system sense.","whyCN":"希腊语最早的用法指神庙雕刻，因此宗教义比「文字体系」义更早。"},{"no":"04","title":"An illegible scrawl","titleCN":"难以辨认的字迹","definition":"handwriting or a mark so unclear that it looks like a secret code","definitionCN":"字迹或记号模糊到看起来像密码","example":"His signature was a hieroglyph that no clerk could read.","exampleCN":"他的签名是一团没人能看懂的字迹。","why":"a picture sign that hides its meaning from the reader is the humorous bridge to bad handwriting.","whyCN":"一个对读者隐藏含义的图形符号，正是通向「潦草字迹」这一戏谑义的桥梁。"},{"no":"05","title":"Something hard to decipher","titleCN":"难以解读的事物","definition":"a message, diagram or set of signs that is very difficult to understand","definitionCN":"很难理解的讯息、图表或一组符号","example":"The wiring diagram was a hieroglyph to anyone without training.","exampleCN":"对没有受过训练的人来说，那张线路图就是天书。","why":"when a sign system is unreadable, the sign itself becomes a metaphor for any obscure message.","whyCN":"当一套符号系统无法读解时，符号本身就成了任何晦涩讯息的隐喻。"},{"no":"06","title":"A text written in such signs","titleCN":"用象形符号写成的文本","definition":"a short text or inscription composed of picture signs, especially one preserved on stone or papyrus","definitionCN":"由图画符号组成的短文或铭文，尤指留存于石头或纸草上的","example":"The papyrus carries a hieroglyph that names a forgotten official.","exampleCN":"那张纸草上有一段象形文字，提到一位被遗忘的官员。","why":"the unit sign can stand for the whole short text by metonymy, as a letter can name a message.","whyCN":"单个符号可以转喻整段短文，就像一封信可以代表一则消息。"},{"no":"07","title":"An emblem of an institution","titleCN":"机构徽记","definition":"a stylized picture sign adopted as the mark of a group, society or office","definitionCN":"被某个团体、社团或机构采用为标志的程式化图形符号","example":"The society adopted a hieroglyph of a scarab as its seal.","exampleCN":"该学会采用圣甲虫图形作为会印。","why":"an emblem works like a carved sign: it stands for something larger than its own shape.","whyCN":"徽记的作用如同雕刻符号：它代表比自身形状更大的东西。"},{"no":"08","title":"A coded sign known to insiders","titleCN":"内部人才懂的暗号","definition":"a pictorial mark whose meaning is shared only by a small group","definitionCN":"含义只在一小群人之间共享的图形标记","example":"Guests recognized the hieroglyph chalked on the door.","exampleCN":"客人们认出了粉笔写在门上的那个暗号。","why":"secret signs are picture writing for a closed circle, the social version of a sacred script.","whyCN":"暗号是小圈子里的图画文字，可说是神圣文字的社会版本。"}],"etymology":{"intro":{"en":"Hieroglyph comes from Greek hieroglyphikos, 'of sacred carving', built on hieros 'sacred' and glyphein 'to carve'. English first used the adjective, then made a noun from it for a single carved sign.","cn":"hieroglyph 来自希腊 hieroglyphikos「神圣雕刻的」，由 hieros「神圣」与 glyphein「雕刻」构成。英语先用形容词，再由它造出指单个雕刻符号的名词。"},"items":[{"era":"GREEK HIEROS","en":"Hieros meant 'sacred, holy', and it also underlies hieratic and hierarchy through different compounds.","cn":"hieros 意为「神圣的、圣的」，也通过不同复合形式构成 hieratic 与 hierarchy。"},{"era":"GREEK GLYPHEIN","en":"Glyphein meant 'to carve, to cut out', the physical act behind writing on stone.","cn":"glyphein 意为「雕刻、凿出」，是石上书写背后的实体动作。"},{"era":"GREEK HIEROGLYPHIKOS","en":"The compound described carvings on Egyptian temples that Greek visitors treated as sacred signs.","cn":"这个复合词描述埃及神庙上的雕刻，希腊访客把它们视为神圣符号。"},{"era":"ENGLISH 17TH CENTURY","en":"English borrowed the adjective first, then back-formed the noun hieroglyph for one such character.","cn":"英语先借入形容词，再逆构出名词 hieroglyph，指一个这样的字符。"},{"era":"FIGURATIVE 19TH CENTURY","en":"Writers applied the word to any unreadable mark or code, and that playful sense is now common.","cn":"作家把这个词用于任何读不懂的记号或密码，这一戏谑义如今很常见。"},{"era":"SOURCE UNCERTAIN","en":"Source uncertain (deeper root and first date): the pre-Greek origin of glyphein is not settled, and the noun's first English date is given differently in different sources.","cn":"来源不确定（更深词根与首见年代）：glyphein 在希腊语之前的来源没有定论，名词在英语中首见的年代各家说法不一。"}]},"similar":{"note":{"en":"Group one holds signs and scripts most often mistaken for hieroglyphs; group two holds general words for a meaningful mark.","cn":"第一组是最容易被误当作 hieroglyph 的符号与文字；第二组是泛指有意义标记的词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"glyph","ipa":"/ɡlɪf/","tag":"a single carved or written sign","definition":"The bare unit of a sign system, especially in typography; it names the shape, not the sacred Egyptian setting.","definitionCN":"符号系统的最小单位，尤用于字体学；它指形状，不含埃及神圣语境。"},{"word":"pictograph","ipa":"/ˈpɪktəɡrɑːf/","tag":"a picture standing for a word","definition":"A picture used as a word sign in any writing system; hieroglyph is the Egyptian and sacred variety.","definitionCN":"在任何文字体系中用作词符的图画；hieroglyph 是埃及的、带神圣色彩的那一类。"},{"word":"ideogram","ipa":"/ˈaɪdiəɡræm/","tag":"a sign for an idea","definition":"A sign standing for a whole idea rather than a sound; many hieroglyphs also work as sound signs.","definitionCN":"代表整个概念而非声音的符号；许多象形字符同时也作表音符号。"},{"word":"cuneiform","ipa":"/ˈkjuːnɪfɔːm/","tag":"wedge-shaped script","definition":"The wedge marks pressed into clay in Mesopotamia; it is a different script with a different tool.","definitionCN":"美索不达米亚压入泥板的楔形记号；它使用不同工具，是另一套文字。"}]},{"heading":"NEAR MEANING","entries":[{"word":"symbol","ipa":"/ˈsɪmbl/","tag":"anything that stands for something else","definition":"A general word for a mark, object or picture that represents another idea; it need not be carved or ancient.","definitionCN":"泛指代表另一概念的标记、物件或图画；不必是雕刻的或古代的。"},{"word":"sign","ipa":"/saɪn/","tag":"a mark with a meaning","definition":"The broadest word for a mark that carries meaning, from road signs to a carved emblem.","definitionCN":"指带含义的记号，范围最广，从路标到雕刻徽记都可用。"},{"word":"emblem","ipa":"/ˈembləm/","tag":"an identifying device","definition":"A picture adopted by a family, city or society as its mark; it stresses belonging, not writing.","definitionCN":"家族、城市或社团用作标志的图案；强调归属，而非书写。"},{"word":"cipher","ipa":"/ˈsaɪfə/","tag":"a secret code","definition":"A system of secret signs or a meaningless figure; it stresses concealment rather than carving.","definitionCN":"一套秘密符号或无意义的数字；强调隐藏，而非雕刻。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: the two Greek roots, the real script name and the real museum setting.","cn":"正常联想：两个真实希腊词根、真实的文字体系名称与真实的博物馆场景。"},"normal":[{"en":"hieros is 'sacred': a hieroglyph is first a sacred sign.","cn":"hieros 是「神圣」：hieroglyph 首先是神圣符号。"},{"en":"glyphein is 'to carve': the sign was cut, not painted.","cn":"glyphein 是「雕刻」：这种符号是刻出来的，不是画上去的。"},{"en":"The adjective hieroglyphic came into English before the noun hieroglyph.","cn":"形容词 hieroglyphic 比名词 hieroglyph 更早进入英语。"},{"en":"In typography a glyph is any single character shape, a plain technical descendant of the same root.","cn":"在字体学中，glyph 指任何单个字形的形状，是同一词根的朴素技术后代。"},{"en":"Egyptian kings wrote their names inside a cartouche, a loop that marked a royal name.","cn":"埃及国王把名字写在王名圈里，那是一个标出王名的环形框。"}],"abstract":[{"en":"A hieroglyph is a picture that agrees to keep a secret for three thousand years.","cn":"象形字符是一幅答应替人保守三千年秘密的图画。"},{"en":"It is a bird carved in stone that still says a sound.","cn":"它是一只刻在石头上的鸟，至今仍在发一个音。"},{"en":"Reading one is fitting a key into a lock whose shape is a small animal.","cn":"读懂一个象形字符，就像把钥匙插进一把形状是小动物的锁。"}]},"examples":[{"en":"Each hieroglyph on the temple wall stood for a sound as well as a picture.","cn":"神庙墙上的每个象形字符既是图画，也代表一个音。"},{"en":"The museum label explains every hieroglyph in the inscription.","cn":"博物馆标签解释了铭文中的每个象形字符。"},{"en":"His note was a hieroglyph of arrows and circles.","cn":"他的便条是一堆箭头和圆圈组成的怪符号。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「hiero（神圣）+ glyph（刻）」——刻在神庙上的神圣图形 → 象形文字","word":"hieroglyph"},"root":"希腊 hieros「神圣」+ glyphein「雕刻」→ hieroglyphikos「神圣雕刻的」；英语先有形容词，后逆构名词 hieroglyph，指单个象形字符。","sensesIntro":{"en":"Eight senses rotate around one unit: a carved sacred picture, read first as a sign, then as a script, then as any mark that hides its meaning.","cn":"八个义项围绕同一个单位转动：一幅刻出的神圣图画，先被读作符号，再被读作文字，最后被读作任何隐藏含义的标记。"},"semanticMap":{"core":{"en":"CORE IMAGE: a carved bird, eye or snake on temple stone, each shape holding one word.","cn":"核心意象：神庙石面上刻着的鸟、眼睛或蛇，每个形状都装着一个词。"},"chain":["SACRED CARVING","SINGLE SIGN","PICTURE SCRIPT","WHOLE TEXT","HARD TO READ","INSIDER MARK"],"branches":[{"senses":"义项 01、义项 03","en":"CARVED UNIT: the Egyptian character and the temple symbol are one cut mark seen as script and as sacred sign.","cn":"刻出的单位：埃及字符与神庙符号是同一个刻痕，一个看作文字，一个看作神圣符号。"},{"senses":"义项 02、义项 06","en":"SCRIPT AND TEXT: one sign extends to other picture scripts and then to a short text made of such signs.","cn":"字符与文本：单个符号先扩展到其他图画文字，再扩展到由这类符号组成的短文。"},{"senses":"义项 04、义项 05","en":"UNREADABLE: bad handwriting and an obscure diagram both turn the sign into a barrier.","cn":"读不懂：潦草字迹与晦涩图表都把符号变成一道障碍。"},{"senses":"义项 07","en":"GROUP MARK: an emblem makes the carved sign stand for an institution.","cn":"团体标记：徽记让雕刻符号代表一个机构。"},{"senses":"义项 08","en":"SECRET CODE: an insider mark is picture writing for a closed circle.","cn":"秘密暗号：内部标记是小圈子的图画文字。"}]},"affixes":{"intro":{"en":"Hieroglyph is a Greek compound, and its two roots also build several English words, so the family can be read part by part.","cn":"hieroglyph 是一个希腊复合词，两个词根还构成若干英语词，因此这个词族可以逐部分读出。"},"latinIntro":{"en":"Latin borrowed the Greek adjective as hieroglyphicus and the plural noun as hieroglyphica; English took both through learned use.","cn":"拉丁语借入希腊形容词作 hieroglyphicus，借入复数名词作 hieroglyphica；英语经学术使用引入两者。"},"items":[{"word":"hieros","structure":"hieros (Greek adjective)","meaning":"sacred, holy","meaningCN":"神圣的","example":"The first root marks the sign as sacred.","exampleCN":"第一个词根把符号标为神圣。"},{"word":"glyphein","structure":"glyphein (Greek verb)","meaning":"to carve, cut out","meaningCN":"雕刻；凿出","example":"The second root names the cutting act.","exampleCN":"第二个词根命名雕刻动作。"},{"word":"hieroglyph","structure":"hieros + glyphein","meaning":"a sacred carved sign","meaningCN":"神圣的雕刻符号","example":"One hieroglyph stood above the gate.","exampleCN":"门上刻着一个象形字符。"},{"word":"hieroglyphic","structure":"hieroglyph + -ic (relating to)","meaning":"of sacred carving","meaningCN":"神圣雕刻的；象形文字的","example":"The wall is covered with hieroglyphic writing.","exampleCN":"墙上布满象形文字。"},{"word":"hieroglyphics","structure":"hieroglyphic + -s (plural collective)","meaning":"the picture script as a whole","meaningCN":"象形文字体系","example":"He studied hieroglyphics for years.","exampleCN":"他研究象形文字多年。"},{"word":"glyph","structure":"glyphein + -e (English back-formation)","meaning":"one carved or typed sign","meaningCN":"单个字形或符号","example":"The font contains a rare glyph.","exampleCN":"这款字体含有一个罕见字形。"},{"word":"hieratic","structure":"hieros + -atikos (relating to priests)","meaning":"priestly; a cursive temple script","meaningCN":"祭司的；僧侣体文字","example":"Hieratic script was a cursive form of the sacred writing.","exampleCN":"僧侣体是神圣文字的草写形式。"},{"word":"hierarchy","structure":"hieros + arkhein 'to rule'","meaning":"rule by priests; a ranked order","meaningCN":"祭司统治；等级体系","example":"The archive follows a strict hierarchy.","exampleCN":"档案馆遵循严格的层级。"}],"latinEntries":[{"word":"hieroglyphicus","structure":"hieroglyphicus, -a, -um (Late Latin adjective, from Greek)","meaning":"of sacred carving","meaningCN":"神圣雕刻的"},{"word":"hieroglyphica","structure":"hieroglyphica (Late Latin neuter plural, from Greek)","meaning":"sacred carved signs","meaningCN":"神圣雕刻符号"}],"derivatives":[{"word":"hieroglyphic","pos":"adj./n.","zh":"hieroglyph + -ic（形容词后缀）→ 象形文字的；象形文字"},{"word":"hieroglyphics","pos":"n.","zh":"hieroglyphic + -s（集合名词后缀）→ 象形文字体系"},{"word":"hieroglyphical","pos":"adj.","zh":"hieroglyphic + -al（形容词后缀）→ 象形文字的（旧式变体）"},{"word":"hieroglyphically","pos":"adv.","zh":"hieroglyphical + -ly（副词后缀）→ 以象形文字方式"},{"word":"hieroglyphist","pos":"n.","zh":"hieroglyph + -ist（从业者后缀）→ 象形文字研究者"}]}},{"word":"hieroglyphic","ipa_uk":"/ˌhaɪərəˈɡlɪfɪk/","ipa_us":"/ˌhaɪəroʊˈɡlɪfɪk/","definition_zh":"与古埃及象形文字有关的；用图画符号写成的；难以辨认的；（复数名词）象形文字体系","definition_en":"relating to Egyptian picture writing; written in picture signs; difficult to decipher; as a plural noun, the picture script itself","core_image":"石柱上层层叠叠的鸟兽符号排成一列，像一套只有祭司才会读的图画语言","scene":"讲解员把投影打在神庙的浮雕上。The hieroglyphic band along the wall spells out the pharaoh's titles.","sceneCN":"这里 hieroglyphic 指「用象形文字写成的」（第 2 个义项：以图画符号书写）；句意为墙上那条象形文字带拼出了法老的头衔。","pos":[{"tag":"adj.","zh":"象形文字的；用图画符号写成的；难辨认的"},{"tag":"n.","zh":"（复数）象形文字体系；单个象形符号"}],"collocations":[{"phrase":"hieroglyphic writing","zh":"象形文字"},{"phrase":"hieroglyphic inscription","zh":"象形文字铭文"},{"phrase":"hieroglyphic symbols","zh":"象形符号"},{"phrase":"hieroglyphic text","zh":"象形文字文本"},{"phrase":"read hieroglyphics","zh":"读象形文字"}],"forms":[{"label":"原级","form":"hieroglyphic"},{"label":"比较级","form":"more hieroglyphic"},{"label":"最高级","form":"most hieroglyphic"},{"label":"集合名词（文字体系）","form":"hieroglyphics"},{"label":"副词","form":"hieroglyphically"},{"label":"名词（单个符号）","form":"hieroglyph"}],"derivatives":[{"word":"hieroglyph","pos":"n.","zh":"hieroglyphic 去掉 -ic（逆构名词）→ 单个象形字符"},{"word":"hieroglyphics","pos":"n.","zh":"hieroglyphic + -s（集合名词后缀）→ 象形文字体系"},{"word":"hieroglyphically","pos":"adv.","zh":"hieroglyphical + -ly（副词后缀）→ 以象形文字方式"},{"word":"hieroglyphical","pos":"adj.","zh":"hieroglyphic + -al（形容词后缀）→ 象形文字的（旧式变体）"},{"word":"hieroglyphist","pos":"n.","zh":"hieroglyph + -ist（从业者后缀）→ 象形文字研究者"}],"senses":[{"no":"01","title":"Relating to Egyptian picture writing","titleCN":"与埃及图画文字有关","definition":"connected with the ancient Egyptian script whose signs are pictures","definitionCN":"与以图画为符号的古埃及文字有关的","example":"The hieroglyphic texts on the tomb wall are still being translated.","exampleCN":"墓壁上的象形文字文本仍在翻译中。","why":"the adjective was coined from the Greek noun for sacred carving, so it first labels the Egyptian script.","whyCN":"这个形容词由表示「神圣雕刻」的希腊名词造出，因此最初标定埃及文字。"},{"no":"02","title":"Written in picture signs","titleCN":"用图画符号写成的","definition":"composed or printed in a script made of picture signs rather than ordinary letters","definitionCN":"用图画符号而非普通字母组成或印出的","example":"The hieroglyphic band along the wall spells out the pharaoh's titles.","exampleCN":"墙上那条象形文字带拼出了法老的头衔。","why":"once the adjective describes the medium, it can describe any text written in that medium.","whyCN":"形容词一旦描述书写媒介，就能描述任何用该媒介写成的文本。"},{"no":"03","title":"Difficult to decipher","titleCN":"难以辨认的","definition":"so obscure or complicated that it is hard to read or understand","definitionCN":"晦涩或复杂到难以阅读和理解","example":"The lease was drafted in hieroglyphic prose that no tenant could follow.","exampleCN":"这份租约用晦涩难懂的文句写成，没有租户能看明白。","why":"a script that most readers cannot read becomes a metaphor for any obscure style.","whyCN":"大多数人读不懂的文字，会成为任何晦涩文风的隐喻。"},{"no":"04","title":"Decorated with symbolic figures","titleCN":"饰有象征图形的","definition":"ornamented with carved or painted symbolic figures rather than with plain patterns","definitionCN":"以雕刻或绘制的象征图形而非素朴图案装饰的","example":"The frieze is hieroglyphic rather than purely ornamental.","exampleCN":"这条饰带带象征图形，而不只是纯装饰。","why":"the adjective can describe the look of a surface covered with sign-like figures, not only its text.","whyCN":"这个形容词也能描述布满符号状图形的表面外观，而不只描述文本。"},{"no":"05","title":"The script as a whole (plural noun)","titleCN":"象形文字体系（复数名词）","definition":"the picture writing of ancient Egypt considered as one system","definitionCN":"把古埃及图画文字视为一个整体体系","example":"Hieroglyphics remained unread until scholars studied the Rosetta Stone.","exampleCN":"在学者研究罗塞塔石碑之前，象形文字一直无人能读。","why":"English turns many adjectives into plural nouns with -s; here the plural names a whole body of writing.","whyCN":"英语常用 -s 把形容词转为复数名词；这里的复数指一整套文字。"},{"no":"06","title":"A single picture sign (noun)","titleCN":"单个图画符号（名词）","definition":"one picture sign used in such a script","definitionCN":"这类文字中使用的一个图画符号","example":"One hieroglyphic was carved into the lintel above the door.","exampleCN":"门上的过梁刻着一个象形符号。","why":"the same adjective is used as a noun for the unit it describes, a common English shift.","whyCN":"同一个形容词被用作名词来指它所描述的单位，这是英语常见的转类。"},{"no":"07","title":"Having a sacred or priestly tone","titleCN":"带有神圣或祭司色彩","definition":"carrying the solemn, priestly quality of a temple inscription","definitionCN":"带有神庙铭文那种庄严、祭司式的气质","example":"The old chant had a hieroglyphic gravity that silenced the room.","exampleCN":"那首古老的吟唱带着一种象形铭文般的庄严，让全场安静下来。","why":"because the root hieros means sacred, the adjective can lend a priestly tone to non-textual things.","whyCN":"由于词根 hieros 意为神圣，这个形容词能给非文本事物添上祭司式的语气。"},{"no":"08","title":"Deliberately cryptic in style","titleCN":"刻意写成隐晦的","definition":"expressed in a coded or deliberately obscure style","definitionCN":"以密码式或刻意晦涩的风格表达","example":"The memo was hieroglyphic to everyone outside the committee.","exampleCN":"对委员会以外的人而言，那份备忘录像天书一样。","why":"the unreadable-script sense extends to any writing that seems designed to exclude outsiders.","whyCN":"「读不懂的文字」这一义扩展到任何似乎故意排除外人的写法。"}],"etymology":{"intro":{"en":"Hieroglyphic is the adjective built on Greek hieroglyphikos, 'of sacred carving'. English borrowed the adjective before it made the shorter noun hieroglyph.","cn":"hieroglyphic 是建立在希腊 hieroglyphikos「神圣雕刻的」之上的形容词。英语先借入形容词，之后才造出更短的名词 hieroglyph。"},"items":[{"era":"GREEK HIEROS","en":"Hieros meant 'sacred'; the adjective marks the carvings as temple signs rather than ordinary writing.","cn":"hieros 意为「神圣」；这个形容词把雕刻标为神庙符号，而非普通文字。"},{"era":"GREEK GLYPHEIN","en":"Glyphein meant 'to carve', naming the tool and the cut behind every sign.","cn":"glyphein 意为「雕刻」，命名每个符号背后的工具与刻痕。"},{"era":"GREEK HIEROGLYPHIKOS","en":"The adjective hieroglyphikos described sacred carved signs and the writing made from them.","cn":"形容词 hieroglyphikos 描述神圣雕刻符号以及由它们构成的文字。"},{"era":"LATIN HIEROGLYPHICUS","en":"Late Latin kept the Greek adjective as hieroglyphicus, the form learned English borrowed.","cn":"晚期拉丁语把希腊形容词保留为 hieroglyphicus，学术英语借用的正是这个形式。"},{"era":"ENGLISH 17TH CENTURY","en":"English used hieroglyphic for Egyptian writing, and later for any picture-like or unreadable mark.","cn":"英语用 hieroglyphic 指埃及文字，后来也指任何图画式或难读的记号。"},{"era":"SOURCE UNCERTAIN","en":"Source uncertain (first date only): the adjective appears in English dictionaries with slightly different first dates, though its Greek and Latin chain is clear.","cn":"来源不确定（仅首见年代存疑）：各词典给出的英语首见年代略有差异，但其希腊与拉丁链条清楚。"}]},"similar":{"note":{"en":"Group one holds the noun and the rival scripts most often confused with it; group two holds adjectives for writing that is hard to read.","cn":"第一组是最常与该词混淆的名词与竞争性文字体系；第二组是形容文字难读的形容词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"hieroglyph","ipa":"/ˈhaɪərəɡlɪf/","tag":"the noun, one sign","definition":"The countable noun for a single sign; hieroglyphic is the adjective or the plural name of the system.","definitionCN":"指单个字符的可数名词；hieroglyphic 是形容词或指整个体系的复数名词。"},{"word":"glyph","ipa":"/ɡlɪf/","tag":"a bare sign shape","definition":"Any single character shape in a font or symbol set; it lacks the sacred Egyptian reference.","definitionCN":"字体或符号集中的任何单个字形；不含埃及神圣语境。"},{"word":"cuneiform","ipa":"/ˈkjuːnɪfɔːm/","tag":"wedge writing","definition":"The wedge-based script of Mesopotamia; it is a rival system, not a synonym.","definitionCN":"美索不达米亚的楔形文字；是另一套体系，并非同义词。"},{"word":"pictographic","ipa":"/ˌpɪktəˈɡræfɪk/","tag":"picture-based in general","definition":"Describing any script that uses pictures; hieroglyphic is the specific Egyptian and sacred case.","definitionCN":"描述任何使用图画的文字；hieroglyphic 是埃及的、带神圣色彩的具体一类。"}]},{"heading":"NEAR MEANING","entries":[{"word":"cryptic","ipa":"/ˈkrɪptɪk/","tag":"deliberately obscure","definition":"Written or said in a way that hides the meaning; it stresses intention, not the script.","definitionCN":"以隐藏含义的方式写出或说出；强调意图，而非文字体系。"},{"word":"illegible","ipa":"/ˌɪləˈdʒɪbl/","tag":"impossible to read","definition":"So badly formed that the letters cannot be read at all; hieroglyphic can still be decipherable.","definitionCN":"字形太差以致完全读不出；hieroglyphic 仍可能是可解读的。"},{"word":"symbolic","ipa":"/ˌsɪmˈbɒlɪk/","tag":"standing for something else","definition":"Using signs to represent ideas; it is broader and lacks the carving image.","definitionCN":"用符号代表概念；范围更广，且没有雕刻意象。"},{"word":"emblematic","ipa":"/ˌembləˈmætɪk/","tag":"serving as an emblem","definition":"Acting as a representative mark of a group or idea; it stresses belonging rather than writing.","definitionCN":"作为群体或观念的代表性标记；强调归属，而非书写。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: the two Greek roots, the real adjective chain and the real plural noun.","cn":"正常联想：两个真实希腊词根、真实的形容词链条与真实的复数名词。"},"normal":[{"en":"hieros 'sacred' plus glyphein 'carve' gives the adjective its two halves.","cn":"hieros「神圣」加 glyphein「雕刻」构成这个形容词的两半。"},{"en":"The adjective entered English before the shorter noun hieroglyph.","cn":"形容词比更短的名词 hieroglyph 更早进入英语。"},{"en":"Hieroglyphics with -s names the whole script, not several separate signs.","cn":"带 -s 的 hieroglyphics 指整套文字，而非几个分离的符号。"},{"en":"The Rosetta Stone is the real key that made hieroglyphics readable.","cn":"罗塞塔石碑是让象形文字变得可读的真实钥匙。"},{"en":"In ordinary speech hieroglyphic often means simply unreadable.","cn":"在日常口语中，hieroglyphic 常常只表示「读不懂」。"}],"abstract":[{"en":"A hieroglyphic wall is a sentence that refuses to be spoken.","cn":"象形文字的墙面，是一句拒绝被说出口的话。"},{"en":"It is writing that looks back at the reader.","cn":"它是会回望读者的文字。"},{"en":"Deciphering it feels like lifting a lid off a very old box.","cn":"解读它，像揭开一只很旧的箱子的盖子。"}]},"examples":[{"en":"The hieroglyphic inscription records a treaty between two cities.","cn":"这段象形文字铭文记录了两座城市之间的条约。"},{"en":"Her handwriting is almost hieroglyphic.","cn":"她的笔迹几乎像象形文字一样难认。"},{"en":"Hieroglyphics were used in Egypt for thousands of years.","cn":"象形文字在埃及使用了数千年。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「hiero（神圣）+ glyph（刻）+ ic」——刻在神庙上的神圣图形 → 象形文字的","word":"hieroglyphic"},"root":"希腊 hieros「神圣」+ glyphein「雕刻」→ hieroglyphikos；经晚期拉丁 hieroglyphicus 进入英语作 hieroglyphic，先为形容词，后衍生名词 hieroglyph。","sensesIntro":{"en":"Eight senses move from the Egyptian adjective to the written medium, then to the unreadable style and the plural name of the whole script.","cn":"八个义项从「埃及的形容词」走到书写媒介，再走到难读的文风与整套文字的复数名称。"},"semanticMap":{"core":{"en":"CORE IMAGE: a carved band of birds and eyes running along a temple wall, readable only to those who hold the key.","cn":"核心意象：神庙墙上一条由鸟与眼睛组成的雕刻带，只有掌握钥匙的人才能读。"},"chain":["OF EGYPT","IN PICTURE SIGNS","ONE SIGN","THE WHOLE SCRIPT","HARD TO READ","CRYPTIC TONE"],"branches":[{"senses":"义项 01、义项 04","en":"SACRED LOOK: the Egyptian reference and the symbolic frieze both describe a carved, sign-covered surface.","cn":"神圣外观：埃及指向与象征饰带都在描述布满符号的雕刻表面。"},{"senses":"义项 02、义项 06","en":"MEDIUM AND UNIT: writing in picture signs and one such sign are the same medium seen whole and seen singly.","cn":"媒介与单位：用图画符号书写与单个这样的符号，是同一媒介的整体与单点。"},{"senses":"义项 03、义项 08","en":"UNREADABLE STYLE: an obscure text and a deliberately coded memo both shut the reader out.","cn":"难读的文风：晦涩文本与刻意加密的备忘录都把读者挡在外面。"},{"senses":"义项 05","en":"WHOLE SYSTEM: the plural noun gathers every sign into one named script.","cn":"整套体系：复数名词把所有符号收进一个有名字的文字体系。"},{"senses":"义项 07","en":"PRIESTLY GRAVITY: the sacred root lends its tone even to a chant.","cn":"祭司式的庄严：神圣词根把语气借给了吟唱。"}]},"affixes":{"intro":{"en":"Hieroglyphic is a Greek adjective with a Latin carrier form, and its parts also build the shorter noun and several technical words.","cn":"hieroglyphic 是一个带拉丁中转形式的希腊形容词，它的各部分还构成更短的名词与若干技术词。"},"latinIntro":{"en":"Late Latin hieroglyphicus carried the Greek adjective, and the neuter plural hieroglyphica named sacred carved signs.","cn":"晚期拉丁 hieroglyphicus 承载希腊形容词，中性复数 hieroglyphica 指神圣雕刻符号。"},"items":[{"word":"hieros","structure":"hieros (Greek adjective)","meaning":"sacred, holy","meaningCN":"神圣的","example":"The root marks the writing as temple property.","exampleCN":"这个词根把文字标为神庙之物。"},{"word":"glyphein","structure":"glyphein (Greek verb)","meaning":"to carve","meaningCN":"雕刻","example":"The root names the cut that makes each sign.","exampleCN":"这个词根命名刻出每个符号的动作。"},{"word":"-ic","structure":"-ikos / -icus (adjectival suffix)","meaning":"relating to","meaningCN":"与……有关的","example":"The suffix turns the compound into a describing word.","exampleCN":"这个后缀把复合词变成描述词。"},{"word":"hieroglyph","structure":"hieros + glyphein (back-formed noun)","meaning":"one sacred carved sign","meaningCN":"单个神圣雕刻符号","example":"A hieroglyph stood above the gate.","exampleCN":"门上刻着一个象形字符。"},{"word":"hieroglyphic","structure":"hieroglyph + -ic","meaning":"of sacred carving","meaningCN":"神圣雕刻的；象形文字的","example":"The wall carries hieroglyphic writing.","exampleCN":"墙上有象形文字。"},{"word":"hieroglyphics","structure":"hieroglyphic + -s (plural collective)","meaning":"the script as a system","meaningCN":"象形文字体系","example":"Hieroglyphics survived on temple walls.","exampleCN":"象形文字保存在神庙墙上。"},{"word":"glyph","structure":"glyphein + English clipping","meaning":"one typed or carved sign","meaningCN":"单个字形","example":"The sign uses a rare glyph.","exampleCN":"这个标牌用了罕见字形。"},{"word":"hieratic","structure":"hieros + -atikos (of priests)","meaning":"priestly; cursive temple script","meaningCN":"祭司的；僧侣体","example":"Hieratic was the quick hand of the temple scribes.","exampleCN":"僧侣体是神庙书吏的快写体。"}],"latinEntries":[{"word":"hieroglyphicus","structure":"hieroglyphicus, -a, -um (Late Latin adjective, from Greek)","meaning":"of sacred carving","meaningCN":"神圣雕刻的"},{"word":"hieroglyphica","structure":"hieroglyphica (Late Latin neuter plural, from Greek)","meaning":"sacred carved signs","meaningCN":"神圣雕刻符号"}],"derivatives":[{"word":"hieroglyph","pos":"n.","zh":"hieroglyphic 去掉 -ic（逆构名词）→ 单个象形字符"},{"word":"hieroglyphics","pos":"n.","zh":"hieroglyphic + -s（集合名词后缀）→ 整套象形文字"},{"word":"hieroglyphical","pos":"adj.","zh":"hieroglyphic + -al（形容词后缀）→ 象形文字的（旧式）"},{"word":"hieroglyphically","pos":"adv.","zh":"hieroglyphical + -ly（副词后缀）→ 以象形文字方式"},{"word":"hieroglyphist","pos":"n.","zh":"hieroglyph + -ist（从业者后缀）→ 象形文字研究者"}]}},{"word":"manuscript","ipa_uk":"/ˈmænjuskrɪpt/","ipa_us":"/ˈmænjuskrɪpt/","definition_zh":"手抄本；手稿；作者交给出版社的稿件；手写的","definition_en":"a document written by hand, especially before printing; an author's text submitted for publication; handwritten","core_image":"书桌上摊着一叠手写纸页，墨迹深浅不一，边角还留着修改的铅笔线","scene":"修复师在无影灯下摊开一页泛黄的手稿。The manuscript was written in a single careful hand.","sceneCN":"这里 manuscript 指「手写的书稿或文稿」（第 1 个义项：印刷术之前的手写文本）；句意为这份手稿由同一个人一笔一画写成。","pos":[{"tag":"n.","zh":"手稿；手抄本；待出版的稿件"},{"tag":"adj.","zh":"手写的；手稿形式的"}],"collocations":[{"phrase":"original manuscript","zh":"原始手稿"},{"phrase":"medieval manuscript","zh":"中世纪手抄本"},{"phrase":"submit a manuscript","zh":"提交稿件"},{"phrase":"manuscript collection","zh":"手稿收藏"},{"phrase":"manuscript page","zh":"手稿页"}],"forms":[{"label":"单数","form":"manuscript"},{"label":"复数","form":"manuscripts"},{"label":"定语用法","form":"manuscript copy"},{"label":"缩写（单数）","form":"MS"},{"label":"缩写（复数）","form":"MSS"},{"label":"相关名词（抄写员）","form":"scribe"}],"derivatives":[{"word":"manuscriptal","pos":"adj.","zh":"manuscript + -al（形容词后缀）→ 手稿的（罕用）"},{"word":"manuscriptology","pos":"n.","zh":"manuscript + -ology（学科后缀）→ 手稿学"},{"word":"scribe","pos":"n.","zh":"拉丁 scribere「写」+ -e（施事后缀）→ 抄写员"},{"word":"script","pos":"n.","zh":"拉丁 scriptum「写下的东西」→ 手写体；文字"},{"word":"typescript","pos":"n.","zh":"type + script（复合构词）→ 打字稿"}],"senses":[{"no":"01","title":"A handwritten book or document","titleCN":"手写的书或文件","definition":"a book or document written by hand, especially one made before printing","definitionCN":"用手写成的书或文件，尤指印刷术之前制作的","example":"The manuscript was written in a single careful hand.","exampleCN":"这份手稿由同一个人一笔一画写成。","why":"manu means 'by hand' and scriptum means 'something written'; the whole word literally says written by hand.","whyCN":"manu 意为「用手」，scriptum 意为「写下的东西」；整词字面就是「用手写成的」。"},{"no":"02","title":"An author's text sent to a publisher","titleCN":"作者交给出版社的稿件","definition":"the text of a book or article that an author submits for editing and publication","definitionCN":"作者提交供编辑与出版的书或文章文本","example":"She sent the manuscript to three publishers before one accepted it.","exampleCN":"她把稿件投给三家出版社，才有一家接受。","why":"the publishing sense keeps the older meaning: even a typed submission is still called a manuscript.","whyCN":"出版义保留了旧义：即使是打字的投稿，仍被称为 manuscript。"},{"no":"03","title":"A handwritten copy of a work","titleCN":"某作品的手抄副本","definition":"a hand-copied version of a text, often the only surviving copy of an ancient work","definitionCN":"某文本的手抄版本，常是古代作品唯一留存的本子","example":"Only one manuscript of the poem survived the fire.","exampleCN":"这首诗只有一个手抄本从火灾中留存下来。","why":"before printing, copying by hand was the only way to duplicate a text, so the copy itself took the name.","whyCN":"印刷术之前，手抄是复制文本的唯一方式，因此副本本身获得了这个名称。"},{"no":"04","title":"An ancient or medieval codex","titleCN":"古代或中世纪抄本","definition":"a bound volume of handwritten leaves from ancient or medieval times","definitionCN":"古代或中世纪装订成册的手写书页","example":"The library keeps a thirteenth-century manuscript under glass.","exampleCN":"图书馆把一份十三世纪的抄本保存在玻璃柜里。","why":"the codex form is the physical shape most manuscripts took, so the word often names the object as a whole.","whyCN":"册页形式是多数手抄本采用的实体形态，因此这个词常指整个物件。"},{"no":"05","title":"An early draft or version","titleCN":"早期的草稿或版本","definition":"an early version of a work, showing corrections and changes","definitionCN":"作品的早期版本，带有修改与改动痕迹","example":"The manuscript shows two rejected endings in the author's own hand.","exampleCN":"手稿上留着作者亲笔写下的两个被否定的结局。","why":"a draft is literally a written text before it is final, which is the core meaning of the Latin phrase.","whyCN":"草稿字面上就是定稿之前写下的文本，正是这个拉丁短语的核心意思。"},{"no":"06","title":"Handwritten (attributive adjective)","titleCN":"手写的（定语形容词）","definition":"used before a noun to mean written by hand rather than printed","definitionCN":"放在名词前，表示用手写而非印刷的","example":"The margin carries manuscript corrections in red ink.","exampleCN":"页边有红墨水写下的手写更正。","why":"English often uses a noun attributively; here the noun describes the manner of writing.","whyCN":"英语常用名词作定语；这里这个名词描述书写方式。"},{"no":"07","title":"A collectible physical copy","titleCN":"可收藏的实体本子","definition":"the physical copy of a handwritten work valued by collectors and archives","definitionCN":"收藏家与档案馆看重的、手写作品的实体本子","example":"The manuscript sold at auction for more than a printed first edition.","exampleCN":"这份手稿在拍卖会上卖得比印刷初版还贵。","why":"when the text is already published, the handwritten object becomes valuable for its material history.","whyCN":"当文本已经出版，手写物件便因其物质历史而珍贵。"},{"no":"08","title":"A handwritten musical score","titleCN":"手写的乐谱","definition":"the composer's handwritten notation for a piece of music","definitionCN":"作曲家为某首乐曲手写的记谱","example":"The conductor studied the composer's manuscript before rehearsing.","exampleCN":"指挥在排练前研究了作曲家的手写总谱。","why":"music notation is writing too, so a handwritten score falls naturally under the same word.","whyCN":"乐谱也是书写，因此手写总谱自然归入同一个词。"}],"etymology":{"intro":{"en":"Manuscript is a Latin phrase turned into one English word: manu scriptum, 'written by hand'. The ablative manu supplies 'by hand' and scriptum supplies 'something written'.","cn":"manuscript 是一个变成单词的拉丁短语：manu scriptum「用手写成」。夺格 manu 提供「用手」，scriptum 提供「写下的东西」。"},"items":[{"era":"LATIN MANUS","en":"Manus meant 'hand' and also 'power or control'; the ablative manu means 'by hand, with the hand'.","cn":"manus 意为「手」，也指「权力、掌控」；夺格 manu 意为「用手、以手」。"},{"era":"LATIN SCRIPTUM","en":"Scriptum is the past participle of scribere 'to write', used as a noun for a written thing.","cn":"scriptum 是 scribere「写」的过去分词，作名词指写下的东西。"},{"era":"MEDIEVAL LATIN","en":"Medieval Latin manuscriptum named a document written by hand rather than by an official scribe's mechanical copy.","cn":"中世纪拉丁 manuscriptum 指手写的文件，以区别于官方书吏的机械复制。"},{"era":"ENGLISH 16TH CENTURY","en":"English borrowed the word in the sense of a handwritten book or document, before printing had spread widely.","cn":"英语在印刷术普及之前借入这个词，指手写的书或文件。"},{"era":"PUBLISHING ERA","en":"Printing gave the word a rival, but publishers kept manuscript for the author's submitted text, typed or handwritten.","cn":"印刷术带来了竞争词，但出版业仍用 manuscript 指作者提交的文本，无论打字还是手写。"}]},"similar":{"note":{"en":"Group one holds written products that are easily confused with a manuscript; group two holds general words for a text or copy.","cn":"第一组是容易与 manuscript 混淆的文字产物；第二组是泛指文本或副本的词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"typescript","ipa":"/ˈtaɪpskrɪpt/","tag":"typed, not handwritten","definition":"A text produced on a typewriter or keyboard; it is the modern opposite of a handwritten manuscript.","definitionCN":"用打字机或键盘产生的文本；它是手写稿的现代对立面。"},{"word":"transcript","ipa":"/ˈtrænskrɪpt/","tag":"a copied record","definition":"A written copy of speech or of another record; it stresses transfer, not handwriting.","definitionCN":"讲话或另一份记录的书面副本；强调转写，而非手写。"},{"word":"codex","ipa":"/ˈkəʊdeks/","tag":"a bound book","definition":"An ancient book of bound leaves; a manuscript may be a codex, but a codex may also be printed.","definitionCN":"古代装订成册的书；手抄本可能是册页本，但册页本也可能是印刷的。"},{"word":"script","ipa":"/skrɪpt/","tag":"writing or a text","definition":"The system of written signs or a written text, especially a play or film; it does not imply hand copying.","definitionCN":"书写符号系统或书面文本，尤指戏剧或电影脚本；不含手抄之意。"}]},{"heading":"NEAR MEANING","entries":[{"word":"document","ipa":"/ˈdɒkjumənt/","tag":"any recorded text","definition":"Any written or printed record, from a receipt to a treaty; manuscript adds the hand and the age.","definitionCN":"任何书写或印刷的记录，从收据到条约；manuscript 增添了手写与年代。"},{"word":"draft","ipa":"/drɑːft/","tag":"an early version","definition":"An early version of a text before final revision; a manuscript can be a draft, but need not be.","definitionCN":"定稿前的早期文本；手稿可能是草稿，但不必然。"},{"word":"copy","ipa":"/ˈkɒpi/","tag":"a reproduction","definition":"One reproduction of an original text; a manuscript copy is one made by hand.","definitionCN":"原文本的一份复制；手抄副本是用手复制的一份。"},{"word":"autograph","ipa":"/ˈɔːtəɡrɑːf/","tag":"the writer's own hand","definition":"A text written in the author's own hand; manuscript is broader and can be copied by a scribe.","definitionCN":"作者亲笔写成的文本；manuscript 范围更广，可由抄写员抄成。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: the two Latin pieces, the publishing term and the real library object.","cn":"正常联想：两个拉丁成分、出版术语与真实的图书馆物件。"},"normal":[{"en":"manu is 'by hand', the same hand in manual and manufacture.","cn":"manu 是「用手」，与 manual、manufacture 中的「手」同源。"},{"en":"scriptum is 'something written', the same stem as script and inscription.","cn":"scriptum 是「写下的东西」，与 script、inscription 同词干。"},{"en":"MS and MSS are the standard abbreviations in library catalogues.","cn":"MS 与 MSS 是图书馆目录里的标准缩写。"},{"en":"A manuscript can be handwritten or, in publishing, typed and still called a manuscript.","cn":"手稿可以是手写的；在出版业，打字的稿件仍称 manuscript。"},{"en":"Before printing, every extra copy of a book was a manuscript.","cn":"印刷术之前，书的每一份额外副本都是手抄本。"}],"abstract":[{"en":"A manuscript is a voice preserved in ink before anyone edited it.","cn":"手稿是在任何人编辑之前，用墨水保存下来的声音。"},{"en":"It is a page that still carries the weight of the hand that wrote it.","cn":"它是一页仍带着书写者手部重量的纸。"},{"en":"Reading one is standing close to a stranger's working desk.","cn":"读一份手稿，像站到一个陌生人的工作桌旁。"}]},"examples":[{"en":"The museum digitized every medieval manuscript in its collection.","cn":"博物馆把馆藏的每份中世纪手抄本都数字化了。"},{"en":"The editor returned the manuscript with notes in the margin.","cn":"编辑退回了稿件，页边写满批注。"},{"en":"No manuscript of the play survives in the author's hand.","cn":"这部剧没有留下作者亲笔的手稿。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「manu（手）+ script（写）」——用手写下的东西 → 手稿、手抄本","word":"manuscript"},"root":"拉丁 manu scriptum「用手写成」：manus「手」的夺格 manu + scriptum「写下的东西」；中世纪拉丁 manuscriptum 指手写文件。英语 manuscript。","sensesIntro":{"en":"Eight senses follow a page through time: a handwritten object, a submitted text, an old copy, a codex, a draft, an attributive label, a collectible and a score.","cn":"八个义项让一页纸穿越时间：手写物件、投稿文本、古老副本、册页本、草稿、定语标签、收藏品与乐谱。"},"semanticMap":{"core":{"en":"CORE IMAGE: a sheet covered in ink by one hand, carrying every correction the mind made.","cn":"核心意象：一张由一只手写满墨迹的纸，带着头脑做过的每一处修改。"},"chain":["BY HAND","WRITTEN OBJECT","AUTHOR'S TEXT","SURVIVING COPY","EARLY VERSION","COLLECTIBLE PAGE"],"branches":[{"senses":"义项 01、义项 03","en":"HAND AND COPY: a handwritten document and a hand-copied version are one act seen as original and as duplicate.","cn":"手写与副本：手写文件与手抄副本是同一动作的原件与复制面。"},{"senses":"义项 02、义项 05","en":"WORKING TEXT: the submitted manuscript and the early draft both sit before the final printed form.","cn":"工作文本：投稿稿件与早期草稿都位于最终印刷形态之前。"},{"senses":"义项 04","en":"BOUND OBJECT: the codex is the physical shape the handwritten leaves took.","cn":"装订物件：册页本是手写书页采取的实体形态。"},{"senses":"义项 06、义项 08","en":"MANNER AND SCORE: the attributive label and the musical score both name writing done by hand.","cn":"方式与乐谱：定语标签与乐谱都指用手完成的书写。"},{"senses":"义项 07","en":"MATERIAL VALUE: a collectible page is valued for its hand, not only its words.","cn":"物质价值：可收藏的纸页因手迹而珍贵，不只因文字。"}]},"affixes":{"intro":{"en":"Manuscript is a Latin phrase frozen into one word, and both of its halves still work separately in English.","cn":"manuscript 是一个冻结成单词的拉丁短语，它的两半在英语里仍各自工作。"},"latinIntro":{"en":"Latin manus gives manual and manufacture; Latin scriptum gives script, inscription and transcript.","cn":"拉丁 manus 衍生 manual 与 manufacture；拉丁 scriptum 衍生 script、inscription 与 transcript。"},"items":[{"word":"manus","structure":"manus, manus (f., fourth declension)","meaning":"hand","meaningCN":"手","example":"The root supplies the hand in manuscript.","exampleCN":"这个词根提供 manuscript 中的「手」。"},{"word":"scriptum","structure":"scriptum, scripti (n., second declension)","meaning":"something written","meaningCN":"写下的东西","example":"The second half names the written result.","exampleCN":"后半部分命名写下的成果。"},{"word":"manuscript","structure":"manu + scriptum","meaning":"written by hand","meaningCN":"用手写成的","example":"The manuscript lay open on the desk.","exampleCN":"手稿摊开在书桌上。"},{"word":"manual","structure":"manus + -alis (relating to)","meaning":"of the hand; a hand book","meaningCN":"手的；手册","example":"The manual explains the machine.","exampleCN":"手册说明了这台机器。"},{"word":"script","structure":"scriptum + English clipping","meaning":"writing; a written text","meaningCN":"文字；书面文本","example":"The script was hard to read.","exampleCN":"这份字迹很难读。"},{"word":"inscription","structure":"in- + scriptum + -tion","meaning":"writing on a surface","meaningCN":"刻写下来的文字","example":"The inscription names the founder.","exampleCN":"铭文写着创始人的名字。"},{"word":"transcript","structure":"trans- + scriptum","meaning":"a copy written across","meaningCN":"转写副本","example":"The transcript of the hearing runs to forty pages.","exampleCN":"听证记录长达四十页。"},{"word":"typescript","structure":"type + script","meaning":"a typed text","meaningCN":"打字稿","example":"The typescript was clean and final.","exampleCN":"这份打字稿干净且是定稿。"}],"latinEntries":[{"word":"manus","structure":"manus, manus (f., fourth declension)","meaning":"hand","meaningCN":"手"},{"word":"scriptum","structure":"scriptum, scripti (n., second declension)","meaning":"something written","meaningCN":"写下的东西"},{"word":"manuscriptum","structure":"manuscriptum, manuscripti (n., second declension, Medieval Latin)","meaning":"a document written by hand","meaningCN":"手写文件"}],"derivatives":[{"word":"manuscriptal","pos":"adj.","zh":"manuscript + -al（形容词后缀）→ 手稿的（罕用）"},{"word":"manuscriptology","pos":"n.","zh":"manuscript + -ology（学科后缀）→ 手稿学"},{"word":"scribe","pos":"n.","zh":"scribere（拉丁「写」）+ -e → 抄写员"},{"word":"script","pos":"n.","zh":"scriptum（拉丁「写下的东西」）→ 文字；手写体"},{"word":"typescript","pos":"n.","zh":"type + script（复合词）→ 打字稿"}]}},{"word":"parchment","ipa_uk":"/ˈpɑːtʃmənt/","ipa_us":"/ˈpɑːrtʃmənt/","definition_zh":"羊皮纸；写在羊皮纸上的文件；仿羊皮纸；羊皮纸色的","definition_en":"animal skin prepared for writing; a document written on it; a modern paper imitating it","core_image":"修复台上放着一张半透明的动物皮纸，边缘磨得发亮，纤维在灯下隐约可见","scene":"修复台上摊着一页边缘卷曲的旧文书。The oldest deed in the archive survives on a sheet of parchment.","sceneCN":"这里 parchment 指「经过处理的动物皮书写材料」（第 1 个义项：可书写的羊皮纸）；句意为档案馆里最古老的契约留存在一张羊皮纸上。","pos":[{"tag":"n.","zh":"羊皮纸；羊皮纸文件；仿羊皮纸"},{"tag":"adj.","zh":"羊皮纸的；羊皮纸色的"}],"collocations":[{"phrase":"sheet of parchment","zh":"一张羊皮纸"},{"phrase":"parchment scroll","zh":"羊皮纸卷轴"},{"phrase":"parchment document","zh":"羊皮纸文件"},{"phrase":"parchment paper","zh":"仿羊皮纸；烘焙纸"},{"phrase":"parchment binding","zh":"羊皮纸装订"}],"forms":[{"label":"单数","form":"parchment"},{"label":"复数","form":"parchments"},{"label":"定语用法","form":"parchment scroll"},{"label":"相关材料（小牛皮纸）","form":"vellum"},{"label":"相关名词（羊皮纸匠）","form":"parchmenter"}],"derivatives":[{"word":"parchmentize","pos":"v.","zh":"parchment + -ize（动词后缀）→ 使呈羊皮纸状"},{"word":"parchmentlike","pos":"adj.","zh":"parchment + -like（类似后缀）→ 像羊皮纸的"},{"word":"parchmenter","pos":"n.","zh":"parchment + -er（从业者后缀）→ 制作羊皮纸的人"},{"word":"vellum","pos":"n.","zh":"拉丁 vitulinum「小牛的」→ 小牛皮纸：更精细的皮纸"},{"word":"pergameneous","pos":"adj.","zh":"拉丁 pergamena + -eous（形容词后缀）→ 羊皮纸质的"}],"senses":[{"no":"01","title":"Animal skin prepared for writing","titleCN":"经过处理可供书写的动物皮","definition":"the skin of a sheep, goat or calf, cleaned and stretched to receive writing","definitionCN":"经清洗、拉伸、刮薄后可供书写的羊、山羊或小牛皮","example":"The oldest deed in the archive survives on a sheet of parchment.","exampleCN":"档案馆里最古老的契约留存在一张羊皮纸上。","why":"the word came from the Latin name for the material of Pergamon, so the substance itself is the first sense.","whyCN":"这个词来自帕加马材料之名的拉丁语，因此材料本身是第一义。"},{"no":"02","title":"A document written on parchment","titleCN":"写在羊皮纸上的文件","definition":"a document or legal instrument written on prepared animal skin","definitionCN":"写在处理过的动物皮上的文件或法律文书","example":"The land grant is a parchment with three wax seals.","exampleCN":"这份土地授予书是一张盖有三枚火漆印的羊皮纸文件。","why":"a material name commonly stands for the object made from it, as paper does for a sheet.","whyCN":"材料名常转指用它做成的东西，就像 paper 也指一张纸。"},{"no":"03","title":"An old scroll or document","titleCN":"古老的卷轴或文书","definition":"an old document, especially one rolled or folded and kept as an heirloom","definitionCN":"古老的文件，尤指卷起或折起、被当作传家宝保存的","example":"The family kept the parchment rolled in a tin box.","exampleCN":"这家人把那份羊皮纸文书卷起来放在铁盒里。","why":"because the material lasted, old records were often made of it, so age and material merged in the sense.","whyCN":"由于这种材料耐久，旧记录常用它制成，年代与材料在词义中合流。"},{"no":"04","title":"Modern paper imitating parchment","titleCN":"仿羊皮纸","definition":"stiff paper treated to look like animal skin, used for certificates, crafts or baking","definitionCN":"经处理使其像动物皮的光滑硬纸，用于证书、手工或烘焙","example":"The invitation was printed on cream parchment.","exampleCN":"邀请函印在米色仿羊皮纸上。","why":"industry copied the look of the old material and kept its name, a familiar pattern in paper names.","whyCN":"工业复制了旧材料的外观并沿用其名，这在纸张名称中是常见模式。"},{"no":"05","title":"A ceremonial diploma","titleCN":"礼仪性的文凭","definition":"a formal diploma or award printed on parchment-like paper","definitionCN":"印在仿羊皮纸上的正式文凭或奖状","example":"The university handed each graduate a parchment at the ceremony.","exampleCN":"大学在典礼上给每位毕业生发了一张羊皮纸质地的文凭。","why":"ceremonies value the look of age, so a modern certificate borrows the old material's dignity.","whyCN":"典礼看重年代感，因此现代证书借用了旧材料的庄重。"},{"no":"06","title":"A pale yellow papery texture","titleCN":"浅黄纸质的质感","definition":"a colour and surface like old animal skin, pale yellow and slightly translucent","definitionCN":"像旧动物皮一样的颜色与表面：浅黄、略带半透明","example":"The lampshade cast a parchment glow over the room.","exampleCN":"灯罩在房间里投下一层羊皮纸般的柔光。","why":"the material's colour became an adjective for any surface with that warm, papery look.","whyCN":"这种材料的颜色变成了形容词，用于任何带那种暖色纸感的事物。"},{"no":"07","title":"A drumhead material","titleCN":"鼓面材料","definition":"a skin or synthetic sheet stretched over a drum","definitionCN":"蒙在鼓上的皮膜或合成膜","example":"The drummer replaced the parchment before the recording.","exampleCN":"鼓手在录音前换了鼓面。","why":"animal skin stretched tight is also what makes a drum speak, a physical reuse of the same material.","whyCN":"绷紧的动物皮也正是让鼓发声的东西，是同一材料的实体再利用。"},{"no":"08","title":"Split sheepskin for bookbinding","titleCN":"装订用的劈层羊皮","definition":"a thin split of sheepskin used to cover books and bind documents","definitionCN":"覆书或装订文件用的薄层羊皮","example":"The binder chose parchment for the spine because it wears well.","exampleCN":"装订师选了羊皮纸做书脊，因为它耐磨。","why":"bookbinding kept the strongest form of the material, so the trade name survives in the craft.","whyCN":"书籍装订保留了这种材料最结实的形态，行业名称因此在手艺中留存。"}],"etymology":{"intro":{"en":"Parchment came into English through Old French parchemin from Latin pergamena charta, 'paper of Pergamon'. The city's name supplies the word, and the story of its invention is a report we inherit rather than a proven fact.","cn":"parchment 经古法语 parchemin 来自拉丁 pergamena charta「帕加马的纸」。这个词由城市名而来，而关于它如何被发明的说法是继承下来的记述，并非已证事实。"},"items":[{"era":"GREEK PERGAMENOS","en":"Pergamenos was the adjective for Pergamon, a city in Asia Minor famous for its library.","cn":"Pergamenos 是小亚细亚城市帕加马的形容词，该城以图书馆闻名。"},{"era":"LATIN PERGAMENA","en":"Latin pergamena charta meant 'Pergamene paper', the writing material associated with the city.","cn":"拉丁 pergamena charta 意为「帕加马的纸」，指与这座城市相关的书写材料。"},{"era":"OLD FRENCH PARCHEMIN","en":"Old French shortened the phrase into parchemin, the form English encountered.","cn":"古法语把短语缩成 parchemin，英语遇到的就是这个形式。"},{"era":"ENGLISH 13TH CENTURY","en":"English borrowed the word for the prepared skin and soon for documents written on it.","cn":"英语在十三世纪借入这个词，先指处理过的皮，很快也指写在其上的文件。"},{"era":"PERGAMON ORIGIN","en":"It is generally thought that Pergamon developed the material when Egypt restricted papyrus exports, but the story rests on an ancient report and is not independently proven.","cn":"一般认为，帕加马在埃及限制纸草出口时发展出这种材料；但此说依据的是一则古代记述，未经独立证实。"},{"era":"SOURCE UNCERTAIN","en":"Source uncertain (first date only): the earliest English use is dated differently across dictionaries, though the Old French and Latin chain is solid.","cn":"来源不确定（仅首见年代存疑）：各词典给出的英语首见年代不一，但古法语与拉丁链条可靠。"}]},"similar":{"note":{"en":"Group one holds materials and book forms easily confused with parchment; group two holds general words for old written records.","cn":"第一组是容易与 parchment 混淆的材料与书籍形态；第二组是泛指古老文字记录的词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"vellum","ipa":"/ˈveləm/","tag":"finer calfskin","definition":"A smoother, finer skin, usually calf, used for luxury books; parchment is the broader and coarser term.","definitionCN":"更光滑精细的皮，通常取自小牛，用于精装书；parchment 是更宽、更粗的一类。"},{"word":"palimpsest","ipa":"/ˈpælɪmpsest/","tag":"a reused sheet","definition":"A parchment or other sheet scraped clean and written on again; it is a use of parchment, not the material.","definitionCN":"被刮净后再次书写的羊皮纸或其他纸页；它是羊皮纸的用法，而非材料本身。"},{"word":"scroll","ipa":"/skrəʊl/","tag":"a rolled document","definition":"A document rolled for storage; it may be parchment, paper or other material.","definitionCN":"为保存而卷起的文件；材料可能是羊皮纸、纸或其他。"},{"word":"codex","ipa":"/ˈkəʊdeks/","tag":"a bound book","definition":"A book of bound leaves; parchment may be its pages, but the codex is the binding form.","definitionCN":"装订成册的书；羊皮纸可作书页，但册页本说的是装订形态。"}]},{"heading":"NEAR MEANING","entries":[{"word":"paper","ipa":"/ˈpeɪpə/","tag":"plant-fibre sheet","definition":"The modern writing sheet made from wood or rag fibre; parchment is animal skin or its imitation.","definitionCN":"用木浆或破布纤维制成的现代书写纸；parchment 是动物皮或其仿制品。"},{"word":"document","ipa":"/ˈdɒkjumənt/","tag":"any record","definition":"Any written record; parchment names the material or an old formal record.","definitionCN":"任何书面记录；parchment 指材料或古老正式文书。"},{"word":"deed","ipa":"/diːd/","tag":"a legal instrument","definition":"A formal legal document, often historically written on parchment; the legal act is the point.","definitionCN":"正式法律文书，历史上常写在羊皮纸上；重点在法律行为。"},{"word":"sheepskin","ipa":"/ˈʃiːpskrɪn/","tag":"the raw hide","definition":"The skin of a sheep as a material or as a diploma slang; parchment is the prepared writing surface.","definitionCN":"羊皮原料或文凭的口语说法；parchment 是加工后的书写表面。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: the city name, the Old French form and the real craft materials.","cn":"正常联想：城市名、古法语形式与真实的手工艺材料。"},"normal":[{"en":"Pergamon is the city hidden inside the word.","cn":"帕加马就是藏在词里的那座城市。"},{"en":"Old French parchemin is the direct parent of the English form.","cn":"古法语 parchemin 是英语形式的直接来源。"},{"en":"Parchment is skin; vellum is the finer calfskin version.","cn":"parchment 是皮纸；vellum 是更精细的小牛皮纸。"},{"en":"A palimpsest is a parchment scraped and used twice.","cn":"重写本是被刮净后二次使用的羊皮纸。"},{"en":"Modern parchment paper copies the look for baking and certificates.","cn":"现代仿羊皮纸为烘焙与证书复制了这种外观。"}],"abstract":[{"en":"Parchment is an animal's back turned into a page of law.","cn":"羊皮纸是把动物的背变成一页法律。"},{"en":"It is a surface that remembers the knife that thinned it.","cn":"它是一个记得那把削薄它的刀的表面。"},{"en":"Old deeds feel heavy because the material once carried a living body.","cn":"旧契约显得沉重，因为材料曾承载过一个活着的身体。"}]},"examples":[{"en":"The scribe copied the charter onto a fresh sheet of parchment.","cn":"抄写员把特许状抄到一张新的羊皮纸上。"},{"en":"Bake the cookies on parchment paper so they do not stick.","cn":"把饼干放在烘焙纸上烤，以免粘住。"},{"en":"The parchment was so old that the ink had faded to brown.","cn":"那羊皮纸太旧了，墨迹已褪成褐色。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「pergam（帕加马）+ ent」——帕加马城发明的书写皮纸 → 羊皮纸","word":"parchment"},"root":"拉丁 pergamena charta「帕加马的纸」→ 古法语 parchemin → 英语 parchment；城市名源自希腊 Pergamon。发明经过为古代记述，一般认为可信但未独立证实。","sensesIntro":{"en":"Eight senses follow one material: prepared skin, the document written on it, an old record, its modern imitation, a diploma, its colour, a drumhead and a binding.","cn":"八个义项沿一种材料展开：处理过的皮、写在其上的文件、古老记录、现代仿制品、文凭、颜色、鼓面与装订。"},"semanticMap":{"core":{"en":"CORE IMAGE: a thin, pale animal skin stretched tight, waiting for ink and outlasting the hand that wrote.","cn":"核心意象：一张绷紧的浅色薄兽皮，等着墨迹，也比写字的手活得更久。"},"chain":["PREPARED SKIN","WRITING SURFACE","OLD DOCUMENT","IMITATION PAPER","CEREMONIAL SHEET","WARM PALE TONE"],"branches":[{"senses":"义项 01、义项 07","en":"STRETCHED SKIN: a writing sheet and a drumhead are the same animal surface pulled tight for two purposes.","cn":"绷紧的皮：书写纸与鼓面是同一张兽皮为两种用途绷紧。"},{"senses":"义项 02、义项 03","en":"MATERIAL BECOMES RECORD: the document and the old scroll are the skin carrying memory.","cn":"材料成为记录：文件与古老卷轴都是承载记忆的皮。"},{"senses":"义项 04、义项 05","en":"MODERN COPY: imitation paper and a diploma borrow the old look for new ceremonies.","cn":"现代复制：仿制纸与文凭为新仪式借用旧外观。"},{"senses":"义项 06","en":"COLOUR MEMORY: the pale tone keeps the material visible in lampshades and rooms.","cn":"颜色记忆：浅黄色调让材料在灯罩与房间里继续可见。"},{"senses":"义项 08","en":"CRAFT USE: split sheepskin survives as a bookbinding material.","cn":"手艺用途：劈层羊皮作为装订材料留存。"}]},"affixes":{"intro":{"en":"Parchment is a place name turned material name, and its family includes both craft terms and ordinary paper words.","cn":"parchment 是由地名变成的材料名，其词族既含手工艺词，也含普通纸张词。"},"latinIntro":{"en":"Latin pergamena charta carries the Greek city adjective; English took the shortened French form, not the full Latin phrase.","cn":"拉丁 pergamena charta 承载希腊城市形容词；英语取的是缩短后的法语形式，而非完整拉丁短语。"},"items":[{"word":"Pergamon","structure":"Pergamon (Greek place name)","meaning":"the city of the library","meaningCN":"帕加马城","example":"The city name sits inside the material word.","exampleCN":"城市名藏在材料词里。"},{"word":"pergamena","structure":"pergamena (Latin adjective, from Greek)","meaning":"of Pergamon","meaningCN":"帕加马的","example":"The adjective renamed the writing skin.","exampleCN":"这个形容词重新命名了书写用皮。"},{"word":"charta","structure":"charta, chartae (f., first declension)","meaning":"paper, sheet","meaningCN":"纸；纸张","example":"The Latin phrase literally said Pergamene paper.","exampleCN":"这个拉丁短语字面就是「帕加马的纸」。"},{"word":"parchemin","structure":"parchemin (Old French noun)","meaning":"parchment","meaningCN":"羊皮纸","example":"French shortened the phrase for everyday use.","exampleCN":"法语把短语缩短以供日常使用。"},{"word":"parchment","structure":"parchemin + English adaptation","meaning":"writing skin","meaningCN":"书写用皮纸","example":"The deed was written on parchment.","exampleCN":"契约写在羊皮纸上。"},{"word":"vellum","structure":"vitulinum (Latin 'of a calf') + -um","meaning":"fine calfskin","meaningCN":"精细小牛皮纸","example":"Vellum is smoother than parchment.","exampleCN":"小牛皮纸比羊皮纸更光滑。"},{"word":"palimpsest","structure":"palin 'again' + psestos 'scraped' (Greek)","meaning":"a reused sheet","meaningCN":"重写本","example":"The palimpsest hides an older text beneath.","exampleCN":"重写本下面藏着更早的文本。"},{"word":"parchmentize","structure":"parchment + -ize","meaning":"to make parchment-like","meaningCN":"使呈羊皮纸状","example":"The process parchmentizes the surface.","exampleCN":"这道工序让表面呈羊皮纸状。"}],"latinEntries":[{"word":"pergamena","structure":"pergamena, -ae (f., first declension; adjective used as noun, from Greek)","meaning":"Pergamene writing skin","meaningCN":"帕加马书写皮纸"},{"word":"charta","structure":"charta, chartae (f., first declension)","meaning":"paper, sheet","meaningCN":"纸；纸张"}],"derivatives":[{"word":"parchmentize","pos":"v.","zh":"parchment + -ize（动词后缀）→ 使呈羊皮纸状"},{"word":"parchmentlike","pos":"adj.","zh":"parchment + -like（类似后缀）→ 像羊皮纸的"},{"word":"parchmenter","pos":"n.","zh":"parchment + -er（从业者后缀）→ 羊皮纸制作者"},{"word":"vellum","pos":"n.","zh":"拉丁 vitulinum「小牛的」→ 精细小牛皮纸"},{"word":"pergameneous","pos":"adj.","zh":"pergamena + -eous（形容词后缀）→ 羊皮纸质的"}]}},{"word":"papyrus","ipa_uk":"/pəˈpaɪrəs/","ipa_us":"/ˈpaɪpərəs/","definition_zh":"纸莎草（生长在尼罗河沼泽的高大莎草）；用其茎芯压成的书写材料；写在纸草上的古代文献","definition_en":"a tall sedge of Nile marshes; the writing material made from its pith; an ancient document written on it","core_image":"尼罗河边的浅水里立着一丛三角茎的高草，茎心被剖成薄片压平晾干","scene":"修复师把一片纤维交错的古老纸草铺在玻璃板上。The account of the harvest survives on a roll of papyrus.","sceneCN":"这里 papyrus 指「用纸莎草茎芯制成的书写材料」（第 2 个义项：纸草书写材料）；句意为一份收获账目留存在一卷纸草上。","pos":[{"tag":"n.","zh":"纸莎草；纸草书写材料；纸草文献"}],"collocations":[{"phrase":"sheet of papyrus","zh":"一张纸草"},{"phrase":"papyrus scroll","zh":"纸草卷轴"},{"phrase":"papyrus reed","zh":"纸莎草茎"},{"phrase":"ancient papyrus","zh":"古代纸草文献"},{"phrase":"papyrus archive","zh":"纸草档案"}],"forms":[{"label":"单数","form":"papyrus"},{"label":"复数（学术）","form":"papyri"},{"label":"复数（通俗）","form":"papyruses"},{"label":"相关形容词","form":"papyraceous"},{"label":"相关学科","form":"papyrology"},{"label":"研究者","form":"papyrologist"}],"derivatives":[{"word":"papyri","pos":"n.","zh":"papyrus 的拉丁式复数（-us → -i）→ 多卷纸草文献"},{"word":"papyraceous","pos":"adj.","zh":"papyrus + -aceous（性质后缀）→ 纸草质的；薄如纸的"},{"word":"papyrology","pos":"n.","zh":"papyrus + -logy（学科后缀）→ 纸草学"},{"word":"papyrologist","pos":"n.","zh":"papyrology + -ist（从业者后缀）→ 纸草学者"},{"word":"papyriform","pos":"adj.","zh":"papyrus + -form（形状后缀）→ 纸草形的"}],"senses":[{"no":"01","title":"The reed plant","titleCN":"纸莎草植株","definition":"a tall sedge with triangular stems that grows in shallow water, especially along the Nile","definitionCN":"一种茎呈三角形的髙大莎草，生长在浅水中，尤见于尼罗河沿岸","example":"Papyrus once grew thick along the riverbanks.","exampleCN":"纸莎草曾在河岸一带长得十分茂密。","why":"the plant name is the oldest sense; the material and the documents are named after the plant.","whyCN":"植物名是最早的义项；材料与文献都因这种植物得名。"},{"no":"02","title":"Writing material from the pith","titleCN":"用茎芯制成的书写材料","definition":"sheets made by slicing the pith into strips, pressing them crosswise and drying them","definitionCN":"把茎芯切成薄条、交叉压紧并晾干制成的纸页","example":"Scribes wrote on papyrus with a cut reed pen.","exampleCN":"书吏用削好的芦苇笔在纸草上书写。","why":"the plant's pith was the industrial raw material, so the material simply took the plant's name.","whyCN":"这种植物的茎芯就是工业原料，材料便直接沿用了植物名。"},{"no":"03","title":"A document written on papyrus","titleCN":"写在纸草上的文献","definition":"a scroll or sheet of papyrus bearing writing, especially an ancient record","definitionCN":"写有文字的纸草卷或纸页，尤指古代记录","example":"The tax record is a papyrus from the temple archive.","exampleCN":"这份税务记录是神庙档案中的一件纸草文献。","why":"material names routinely stand for the objects made from them, a metonymy seen with paper and parchment.","whyCN":"材料名常转指其制成品，paper 与 parchment 都有这种转喻。"},{"no":"04","title":"Ancient texts studied as a group","titleCN":"作为一组研究对象的古代纸草文献","definition":"ancient texts preserved on papyrus, especially those recovered from Egypt and studied by scholars","definitionCN":"保存在纸草上的古代文本，尤指从埃及出土、由学者研究的那批","example":"The papyri include private letters, contracts and school exercises.","exampleCN":"这批纸草文献包括私人信件、契约与学校练习。","why":"the Latin plural papyri marks the scholarly collection sense, where individual sheets become an archive.","whyCN":"拉丁式复数 papyri 标出学术集合义，单张纸页在此变成一批档案。"},{"no":"05","title":"The ancient writing medium","titleCN":"古代书写媒介","definition":"the dominant writing surface of Egypt and the Mediterranean before parchment","definitionCN":"在羊皮纸之前，埃及与地中海世界占主导的书写表面","example":"Papyrus gave way to parchment in late antiquity.","exampleCN":"在古代晚期，纸草逐渐让位于羊皮纸。","why":"the material names a whole period of writing because it shaped how records were kept.","whyCN":"这种材料塑造了记录方式，因此可以命名整个书写时代。"},{"no":"06","title":"The sedge family member","titleCN":"莎草科植物","definition":"a member of the sedge family, related to reed grasses rather than to trees","definitionCN":"莎草科的一员，与芦苇类草本相近，而非树木","example":"Botanists classify papyrus as a sedge, not a reed grass.","exampleCN":"植物学家把纸莎草归入莎草，而不是芦苇。","why":"the plant sense narrows in botany to a family classification, a technical specialization of sense one.","whyCN":"植物义在植物学中收窄为科属分类，是第一义的技术性细分。"},{"no":"07","title":"An emblem of fragile antiquity","titleCN":"脆弱古代记录的象征","definition":"a symbol used by museums and libraries for ancient and easily damaged records","definitionCN":"博物馆与图书馆用来象征古老且易损记录的符号","example":"The library uses a papyrus as the emblem on its rare-book room.","exampleCN":"图书馆用纸草图案作为善本室的标志。","why":"a material that survives only in dry conditions becomes a natural emblem for fragile memory.","whyCN":"只在干燥环境里幸存的材料，自然成为脆弱记忆的象征。"},{"no":"08","title":"A decorative plant motif","titleCN":"装饰性的纸草纹样","definition":"a stylized image of the papyrus plant used in painting, carving and architecture","definitionCN":"绘画、雕刻与建筑中程式化的纸莎草形象","example":"The column capital is carved with papyrus and lotus buds.","exampleCN":"柱头雕刻着纸草与莲花花蕾。","why":"Egyptian art used the plant as ornament, and the motif kept the name after the plant's everyday use faded.","whyCN":"埃及艺术用这种植物作装饰，日常用途消失后纹样仍保留其名。"}],"etymology":{"intro":{"en":"Papyrus is Latin for the Nile reed and its writing sheet, borrowed from Greek papyros. The deeper origin of papyros is not established; suggestions linking it to Egyptian are plausible but unproven.","cn":"papyrus 是拉丁语，指尼罗河芦苇及其书写纸，借自希腊 papyros。papyros 更深来源未确立；把它与埃及语联系起来的说法看似合理，但未获证明。"},"items":[{"era":"GREEK PAPYROS","en":"Papyros named the reed and, by extension, the sheet made from it.","cn":"papyros 指这种芦苇，也引申指用它制成的纸页。"},{"era":"LATIN PAPYRUS","en":"Latin kept the Greek noun and passed it to the learned languages of Europe.","cn":"拉丁语保留这个希腊名词，并把它传给欧洲的学术语言。"},{"era":"ENGLISH 16TH CENTURY","en":"English used papyrus first for the plant and the material, then for documents made from it.","cn":"英语先用 papyrus 指植物与材料，再指用其制成的文献。"},{"era":"SCHOLARLY PLURAL","en":"The Latin plural papyri became the standard term for collections of ancient papyrus texts.","cn":"拉丁复数 papyri 成为古代纸草文献收藏的标准称呼。"},{"era":"SOURCE UNCERTAIN","en":"Source uncertain (deeper origin): the link between papyros and an Egyptian word is often suggested but not demonstrated, so any Egyptian form offered for it is a hypothesis.","cn":"来源不确定（更深词源）：papyros 与某个埃及语词的联系常被提出，却未获证实，因此为其给出的埃及语形式都只是假说。"}]},"similar":{"note":{"en":"Group one holds the plant, material and documents that share the same name; group two holds other ancient writing surfaces.","cn":"第一组是同名而分属植物、材料与文献的词；第二组是其他古代书写表面。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"papyri","ipa":"/pəˈpaɪraɪ/","tag":"the scholarly plural","definition":"The Latin plural used for collections of ancient papyrus texts; the singular names one plant or sheet.","definitionCN":"用于古代纸草文献收藏的拉丁复数；单数指一株植物或一张纸。"},{"word":"papyrology","ipa":"/ˌpæpɪˈrɒlədʒi/","tag":"the discipline","definition":"The study of texts written on papyrus; it names the field, not the material.","definitionCN":"研究纸草文本的学科；它指领域，而非材料。"},{"word":"parchment","ipa":"/ˈpɑːtʃmənt/","tag":"the rival surface","definition":"Prepared animal skin that replaced papyrus in many places; it is a different material.","definitionCN":"在许多地方取代纸草的加工兽皮；是另一种材料。"},{"word":"paper","ipa":"/ˈpeɪpə/","tag":"the modern sheet","definition":"Plant-fibre sheets made by industry; papyrus was an early pressed-pith sheet, not paper in the modern sense.","definitionCN":"工业制造的植物纤维纸；纸草是早期压制的茎芯薄片，并非现代意义的纸。"}]},{"heading":"NEAR MEANING","entries":[{"word":"reed","ipa":"/riːd/","tag":"a tall waterside grass","definition":"A tall hollow grass of wet ground; papyrus is one specific sedge, not the general reed.","definitionCN":"湿地上的髙大空心草；纸莎草是特定的一种莎草，而非泛指芦苇。"},{"word":"scroll","ipa":"/skrəʊl/","tag":"a rolled text","definition":"A document rolled for storage; it may be papyrus, parchment or paper.","definitionCN":"卷起保存的文件；材料可为纸草、羊皮纸或纸。"},{"word":"sedge","ipa":"/sedʒ/","tag":"a grass-like plant","definition":"A grass-like plant of wet ground with triangular stems; papyrus is a member of this family.","definitionCN":"湿地中茎呈三角形的类草植物；纸莎草是该科成员。"},{"word":"manuscript","ipa":"/ˈmænjuskrɪpt/","tag":"any handwritten text","definition":"A text written by hand; a papyrus may be a manuscript, but the words answer different questions.","definitionCN":"手写的文本；纸草文献可能是手稿，但两词回答的问题不同。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: the Nile plant, the pressed pith and the real scholarly plural.","cn":"正常联想：尼罗河植物、压制的茎芯与真实的学术复数。"},"normal":[{"en":"Papyrus is a sedge, not a tree; its stem is triangular.","cn":"纸莎草是莎草，不是树；它的茎呈三角形。"},{"en":"The pith was cut into strips and pressed crosswise to make a sheet.","cn":"茎芯被切成条，交叉压紧制成纸页。"},{"en":"The Latin plural papyri is standard in scholarship.","cn":"拉丁复数 papyri 在学术界是标准形式。"},{"en":"Papyrus, parchment and paper name three different writing surfaces.","cn":"纸草、羊皮纸与纸是三种不同的书写表面。"},{"en":"Papyrology is the field that reads texts surviving on papyrus.","cn":"纸草学是解读纸草文本的学科。"}],"abstract":[{"en":"Papyrus is a river plant that became a library.","cn":"纸莎草是一种变成图书馆的河畔植物。"},{"en":"It is a sheet that lasts only where rain never falls.","cn":"它是一张只在无雨之处才能存活的纸。"},{"en":"A papyrus scroll is a conversation held across two thousand years.","cn":"纸草卷轴是一场跨越两千年的对话。"}]},"examples":[{"en":"The hieroglyphic text was written on a sheet of papyrus.","cn":"那段象形文字写在一张纸草上。"},{"en":"Papyrus grows wild in the marshes of the Nile delta.","cn":"纸莎草在尼罗河三角洲的沼泽中野生生长。"},{"en":"The papyri were stored in dry jars to protect them.","cn":"这些纸草文献被存放在干燥的罐子里加以保护。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「papyrus（纸草）」——尼罗河边的三角茎莎草，剖开压平就成了书写的纸","word":"papyrus"},"root":"拉丁 papyrus ← 希腊 papyros，指尼罗河芦苇及其书写纸；papyros 更深来源不确定，与埃及语的联系仅为假说。英语 papyrus。","sensesIntro":{"en":"Eight senses fan out from one plant: the reed, its pith sheet, a written document, a scholarly collection, a whole era of writing, a botanical member, an emblem and an ornament.","cn":"八个义项从一株植物展开：芦苇、茎芯纸、写成的文献、学术收藏、整个书写时代、植物分类、象征与纹样。"},"semanticMap":{"core":{"en":"CORE IMAGE: a triangular reed cut into strips, pressed flat and turned into a page that outlasts its writer.","cn":"核心意象：一根三角茎芦苇被切成条、压平，变成比书写者活得更久的一页。"},"chain":["RIVER REED","PITH SHEET","WRITTEN SCROLL","ANCIENT ARCHIVE","WRITING AGE","DECORATIVE MOTIF"],"branches":[{"senses":"义项 01、义项 06","en":"PLANT AND FAMILY: the Nile reed and the sedge classification are the living plant seen alone and in botany.","cn":"植物与科属：尼罗河芦苇与莎草分类，是活植物在单独与植物学两个层面的样子。"},{"senses":"义项 02、义项 05","en":"MATERIAL AND ERA: the pressed sheet and the age it dominated are one medium seen as object and as period.","cn":"材料与时代：压制纸页与它主导的时代，是同一媒介的物件面与时期面。"},{"senses":"义项 03、义项 04","en":"DOCUMENT AND COLLECTION: one written scroll grows into an archive of ancient texts.","cn":"文献与收藏：一卷写成的纸草扩展成一批古代文本档案。"},{"senses":"义项 07","en":"FRAGILE EMBLEM: the material becomes a sign for records that easily crumble.","cn":"脆弱象征：材料成为易碎记录的符号。"},{"senses":"义项 08","en":"ORNAMENT: the plant survives as a carved motif after its practical use ends.","cn":"装饰：实用用途结束后，这种植物以雕刻纹样继续存在。"}]},"affixes":{"intro":{"en":"Papyrus is a Greek plant name carried into English through Latin, and its family covers the material, the documents and the scholars who read them.","cn":"papyrus 是经拉丁语进入英语的希腊植物名，其词族覆盖材料、文献与解读它们的学者。"},"latinIntro":{"en":"Latin papyrus kept the Greek noun unchanged; the Latin plural papyri became the scholarly standard.","cn":"拉丁 papyrus 原样保留希腊名词；拉丁复数 papyri 成为学术标准。"},"items":[{"word":"papyros","structure":"papyros (Greek noun, masculine)","meaning":"the Nile reed","meaningCN":"尼罗河芦苇","example":"Greek named the plant before the sheet.","exampleCN":"希腊语先命名植物，后指纸页。"},{"word":"papyrus","structure":"papyrus, papyri (Latin noun, second declension)","meaning":"reed; writing sheet","meaningCN":"芦苇；书写纸","example":"Latin carried the word to Europe.","exampleCN":"拉丁语把这个词带到欧洲。"},{"word":"-us","structure":"-us (Latin noun ending)","meaning":"masculine noun marker","meaningCN":"阳性名词词尾","example":"The ending marks the Latin form.","exampleCN":"这个词尾标出拉丁形式。"},{"word":"-i","structure":"-i (Latin plural ending)","meaning":"plural marker","meaningCN":"复数词尾","example":"Papyri keeps the Latin plural.","exampleCN":"papyri 保留拉丁复数。"},{"word":"-aceous","structure":"-aceus (Latin adjectival suffix)","meaning":"of the nature of","meaningCN":"具有……性质的","example":"Papyraceous describes a papery texture.","exampleCN":"papyraceous 描述纸质质感。"},{"word":"papyrology","structure":"papyrus + -logia (study of)","meaning":"the study of papyrus texts","meaningCN":"纸草学","example":"Papyrology recovers lost literature.","exampleCN":"纸草学找回失落的文学。"},{"word":"papyrologist","structure":"papyrology + -ist","meaning":"one who studies papyri","meaningCN":"纸草学者","example":"The papyrologist repaired the scroll.","exampleCN":"这位纸草学者修复了卷轴。"},{"word":"papyriform","structure":"papyrus + -formis (shaped)","meaning":"shaped like papyrus","meaningCN":"纸草形的","example":"The capital uses a papyriform design.","exampleCN":"柱头采用纸草形设计。"}],"latinEntries":[{"word":"papyrus","structure":"papyrus, papyri (m., second declension)","meaning":"the papyrus reed; a sheet of it","meaningCN":"纸莎草；纸草纸"},{"word":"papyrum","structure":"papyrum, papyri (n., second declension, variant)","meaning":"a papyrus sheet","meaningCN":"一张纸草"}],"derivatives":[{"word":"papyri","pos":"n.","zh":"papyrus 的拉丁式复数 → 多卷纸草文献"},{"word":"papyraceous","pos":"adj.","zh":"papyrus + -aceous（性质后缀）→ 纸草质的"},{"word":"papyrology","pos":"n.","zh":"papyrus + -logy（学科后缀）→ 纸草学"},{"word":"papyrologist","pos":"n.","zh":"papyrology + -ist（从业者后缀）→ 纸草学者"},{"word":"papyriform","pos":"adj.","zh":"papyrus + -form（形状后缀）→ 纸草形的"}]}},{"word":"tablet","ipa_uk":"/ˈtæblət/","ipa_us":"/ˈtæblət/","definition_zh":"书写用的平板（泥板、石板、蜡板）；刻有文字的板状文物；药片；平板电脑；肥皂等的一块","definition_en":"a flat slab used for writing; an inscribed slab; a pill; a flat computing device; a bar of soap","core_image":"一块湿润的方形泥板放在木托上，边缘还留着按压时的指痕","scene":"考古队员把一块还沾着泥土的方形泥板放进托盘中。A small tablet beside the doorway records the delivery of grain.","sceneCN":"这里 tablet 指「可书写的平板」（第 1 个义项：书写用平板）；句意为门旁的一块小泥板记录了一次粮食交付。","pos":[{"tag":"n.","zh":"书写平板；板状文物；药片；平板电脑；块状物"}],"collocations":[{"phrase":"clay tablet","zh":"泥板"},{"phrase":"stone tablet","zh":"石板"},{"phrase":"wax tablet","zh":"蜡板"},{"phrase":"take a tablet","zh":"服用药片"},{"phrase":"digital tablet","zh":"平板电脑"},{"phrase":"tablet of soap","zh":"一块肥皂"}],"forms":[{"label":"单数","form":"tablet"},{"label":"复数","form":"tablets"},{"label":"相关名词（板）","form":"tabula"},{"label":"相关动词（制表）","form":"tabulate"},{"label":"相关名词（制表）","form":"tabulation"}],"derivatives":[{"word":"tabula","pos":"n.","zh":"拉丁 tabula「板、书写板」→ 平板；表格"},{"word":"tabular","pos":"adj.","zh":"tabula + -ar（形容词后缀）→ 表格式的；平板状的"},{"word":"tabulate","pos":"v.","zh":"tabula + -ate（动词后缀）→ 列成表格"},{"word":"tabulation","pos":"n.","zh":"tabulate + -ion（名词后缀）→ 制表；表格排列"},{"word":"tabloid","pos":"n.","zh":"tablet + -oid（类似后缀）→ 小报；片剂（旧义）"}],"senses":[{"no":"01","title":"A flat slab for writing","titleCN":"书写用平板","definition":"a flat piece of clay, stone, wood or wax used as a writing surface","definitionCN":"用作书写表面的黏土、石头、木头或蜡制平板","example":"A small tablet beside the doorway records the delivery of grain.","exampleCN":"门旁的一块小泥板记录了一次粮食交付。","why":"Latin tabula meant a board or writing tablet, so the flat surface for writing is the original sense.","whyCN":"拉丁 tabula 指板或书写板，因此「书写用平板」是最初的义项。"},{"no":"02","title":"An inscribed slab as an artifact","titleCN":"刻有文字的板状文物","definition":"a slab bearing an inscription, kept as an archaeological or historical object","definitionCN":"刻有铭文、作为考古或历史物件保存的板","example":"The museum displays a stone tablet listing the city's old laws.","exampleCN":"博物馆展出一块列有旧城法律的石板。","why":"once writing is on the slab, the object itself becomes the artifact and the word names the whole find.","whyCN":"文字一旦刻上板面，物件本身就成了文物，这个词便指整个出土物。"},{"no":"03","title":"A flat computing device","titleCN":"平板电脑","definition":"a portable computer with a touch screen and no attached keyboard","definitionCN":"带触摸屏、无固定键盘的便携电脑","example":"She reads the newspaper on a tablet every morning.","exampleCN":"她每天早上用平板电脑看报纸。","why":"the modern device copied the shape and name of the writing slab, a straightforward visual transfer.","whyCN":"现代设备沿用了书写板的外形与名称，是直接的视觉转移。"},{"no":"04","title":"A compressed medicine pill","titleCN":"药片","definition":"a small hard disc of compressed medicine taken by mouth","definitionCN":"口服的小而硬的压缩药片","example":"Take one tablet with water after breakfast.","exampleCN":"早饭后用水送服一片药。","why":"a pill is a small flat disc, the same shape that gave the word its name in pharmacy.","whyCN":"药片是小而扁的圆盘，药剂学正因为这个形状沿用了这个词。"},{"no":"05","title":"A bar of soap or chocolate","titleCN":"一块肥皂或巧克力","definition":"a flat rectangular block of a solid product, especially soap or chocolate","definitionCN":"固体产品的扁平长方块，尤指肥皂或巧克力","example":"She bought a tablet of lavender soap at the market.","exampleCN":"她在市场上买了一块薰衣草肥皂。","why":"the block shape is the link: any flat rectangular piece can be called a tablet in trade.","whyCN":"块状是联系点：商业中任何扁平长方块都可称 tablet。"},{"no":"06","title":"A pad of paper sheets","titleCN":"便笺本","definition":"a small pad of detachable sheets for writing notes","definitionCN":"可撕下纸页的小型便笺本","example":"He kept a tablet in his pocket for quick notes.","exampleCN":"他口袋里带着一本便笺本，用来快速记事。","why":"a pad is a stack of flat writing leaves, an everyday descendant of the writing slab.","whyCN":"便笺本是叠起的扁平书写纸页，是书写板的日常后代。"},{"no":"07","title":"A memorial plaque","titleCN":"纪念牌匾","definition":"a flat plate fixed to a wall to commemorate a person or event","definitionCN":"固定在墙上以纪念某人或某事的平板","example":"A bronze tablet marks the house where the poet was born.","exampleCN":"一块铜牌标出诗人出生的房子。","why":"the inscribed plaque is a writing slab made permanent and public.","whyCN":"刻字牌匾是把书写板做成永久而公开的形式。"},{"no":"08","title":"The stone tablets of the law","titleCN":"律法石版","definition":"one of the stone slabs on which sacred law was said to be written","definitionCN":"据传刻有神圣律法的石板之一","example":"The story tells of two stone tablets carried down the mountain.","exampleCN":"故事说有两块石版被带下山。","why":"sacred law written on stone is the most famous writing slab in Western memory, so the word carries that weight.","whyCN":"刻在石头上的神圣律法是西方记忆中最著名的书写板，这个词因此带有那层分量。"}],"etymology":{"intro":{"en":"Tablet comes from Latin tabula, 'board, plank, writing tablet'. The deeper origin of tabula is uncertain, with some suggestions pointing to an early Mediterranean source rather than a clear Latin root.","cn":"tablet 来自拉丁 tabula「板、木板、书写板」。tabula 的更早来源不确定，有些说法指向早期地中海来源，而非清楚的拉丁词根。"},"items":[{"era":"LATIN TABULA","en":"Tabula meant a board, a plank or a wax writing tablet, the flat surface at the heart of the word.","cn":"tabula 指板、木板或蜡制书写板，即这个词核心的扁平表面。"},{"era":"DIMINUTIVE TABELLA","en":"The diminutive tabella named a small tablet or a small painted panel.","cn":"指小形式 tabella 指小牌或小画板。"},{"era":"OLD FRENCH TABLETTE","en":"Old French carried a form of the word into English as tablet, first for a writing or painting surface.","cn":"古法语把这个词的一种形式带入英语作 tablet，最初指书写或绘画表面。"},{"era":"PHARMACY 19TH CENTURY","en":"The flat disc of compressed medicine took the name because of its shape.","cn":"压缩药片的扁圆形状使它获得了这个名称。"},{"era":"COMPUTING 21ST CENTURY","en":"The touch-screen device repeated the old visual metaphor of a hand-held writing slab.","cn":"触摸屏设备重复了手持书写板这一古老视觉隐喻。"},{"era":"SOURCE UNCERTAIN","en":"Source uncertain (deeper origin): the pre-Latin source of tabula is not established, and proposed links to other Mediterranean languages remain hypotheses.","cn":"来源不确定（更深词源）：tabula 的拉丁语之前来源未确立，与其他地中海语言的联系仍属假说。"}]},"similar":{"note":{"en":"Group one holds slab-like objects easily confused with a writing tablet; group two holds words for the flat written or printed thing.","cn":"第一组是容易与书写平板混淆的板状物；第二组是泛指扁平书写或印刷物的词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"tabula","ipa":"/ˈtæbjələ/","tag":"the Latin board","definition":"The Latin noun for a board or writing tablet, the source of the English word; it is not used for pills.","definitionCN":"指板或书写板的拉丁名词，是英语词的来源；不用于药片。"},{"word":"tableau","ipa":"/tæˈbləʊ/","tag":"a striking scene","definition":"A dramatic grouping of figures or a vivid description; it comes from the same French family but means a scene.","definitionCN":"戏剧性的人物组合或生动描写；同出法语词族，但指场景。"},{"word":"table","ipa":"/ˈteɪbl/","tag":"a furniture board","definition":"A piece of furniture with a flat top; it shares the board idea but not the writing-slab sense.","definitionCN":"有平顶的家具；共享「板」的概念，但不含书写板义。"},{"word":"plaque","ipa":"/plæk/","tag":"a commemorative plate","definition":"A flat plate fixed to a surface, often inscribed; it is a kind of tablet but not a writing surface.","definitionCN":"固定在表面上的平板，常刻字；属板状物，但不是书写表面。"}]},{"heading":"NEAR MEANING","entries":[{"word":"slab","ipa":"/slæb/","tag":"a thick flat piece","definition":"A thick flat piece of stone, concrete or food; tablet adds the purpose of writing or dosing.","definitionCN":"石头、混凝土或食物的厚平板；tablet 增添了书写或服用的用途。"},{"word":"pill","ipa":"/pɪl/","tag":"a small round dose","definition":"A small round or oval dose of medicine; a tablet is specifically flat and compressed.","definitionCN":"小而圆或椭圆的药丸；tablet 特指扁平压制的药片。"},{"word":"pad","ipa":"/pæd/","tag":"a stack of sheets","definition":"A stack of paper sheets glued together; a tablet can be such a pad.","definitionCN":"粘在一起的一叠纸页；tablet 可以是这种便笺本。"},{"word":"panel","ipa":"/ˈpænl/","tag":"a flat section","definition":"A flat rectangular section of a surface, door or wall; it lacks the writing purpose.","definitionCN":"表面、门或墙的扁平矩形部分；不含书写用途。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: the Latin board, the wax surface and the modern shapes that reused the name.","cn":"正常联想：拉丁「板」、蜡制表面，以及沿用此名的现代形状。"},"normal":[{"en":"Tabula is Latin for a board or writing tablet.","cn":"tabula 是拉丁语「板、书写板」。"},{"en":"A wax tablet could be warmed and smoothed for reuse.","cn":"蜡板可以加热抹平后重复使用。"},{"en":"A pill is a flat disc, which is why pharmacy calls it a tablet.","cn":"药片是扁圆盘，药剂学因此称之为 tablet。"},{"en":"A touch-screen device borrowed the shape and the name.","cn":"触摸屏设备借用了外形与名称。"},{"en":"Tabula also gives table, tabular and tabulate.","cn":"tabula 还衍生 table、tabular 与 tabulate。"}],"abstract":[{"en":"A tablet is a small flat piece of the world made ready to receive a mark.","cn":"书写板是一小片被整理平、准备接受痕迹的世界。"},{"en":"It is a surface that turns a hand into a record.","cn":"它是一块把手变成记录的表面。"},{"en":"A modern tablet is the same slab, now glowing.","cn":"现代平板电脑是同一块板，只是会发光。"}]},"examples":[{"en":"The scribe pressed the stylus into the soft clay tablet.","cn":"书吏把尖笔压进柔软的泥板。"},{"en":"Take one tablet twice a day after meals.","cn":"每天饭后服一片，一日两次。"},{"en":"The children drew on wax tablets in the schoolroom.","cn":"孩子们在教室里的蜡板上画画。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「tab（板）+ let（小）」——一小块平板 → 书写板、药片、平板电脑","word":"tablet"},"root":"拉丁 tabula「板、木板、书写板」→ 古法语 tablette → 英语 tablet；tabula 更深来源不确定。药片与平板电脑义都由「扁平块」形状引申。","sensesIntro":{"en":"Eight senses keep one flat shape: a writing slab, an inscribed artifact, a computer, a pill, a bar, a notepad, a plaque and a sacred stone.","cn":"八个义项守着同一个扁平形状：书写板、刻字文物、电脑、药片、块状物、便笺本、牌匾与圣石。"},"semanticMap":{"core":{"en":"CORE IMAGE: a small flat slab held in one hand, ready to take a mark and keep it.","cn":"核心意象：一块单手可握的小平板，准备接受一个痕迹并留住它。"},"chain":["FLAT SLAB","WRITING SURFACE","INSCRIBED OBJECT","SMALL DISC","BLOCK OF GOODS","GLOWING SCREEN"],"branches":[{"senses":"义项 01、义项 06","en":"WRITING FLATNESS: the slab and the paper pad are the same flat surface at different scales.","cn":"书写平面：石板与便笺本是同一扁平表面在不同尺度上。"},{"senses":"义项 02、义项 07","en":"INSCRIBED MEMORY: an artifact slab and a wall plaque both fix public words in place.","cn":"刻写的记忆：文物石板与墙上牌匾都把公共文字固定住。"},{"senses":"义项 03","en":"GLOWING SLAB: the computer repeats the hand-held flat surface with light instead of ink.","cn":"发光的板：电脑用光而非墨重复手持扁平表面。"},{"senses":"义项 04、义项 05","en":"SMALL FLAT THINGS: a pill and a bar of soap are everyday discs and blocks that inherited the shape word.","cn":"小扁物：药片与肥皂块是继承了形状词的日常圆盘与方块。"},{"senses":"义项 08","en":"SACRED STONE: the law tablet gives the flat slab its heaviest public meaning.","cn":"神圣石板：律法石版赋予平板最沉重的公共意义。"}]},"affixes":{"intro":{"en":"Tablet is a Latin board name that has spread from wax writing surfaces to pills, soap and screens.","cn":"tablet 是一个拉丁「板」名，从蜡制书写表面一路扩展到药片、肥皂与屏幕。"},"latinIntro":{"en":"Latin tabula and its diminutive tabella supply the word; the same stem gives table, tabular and tabulate.","cn":"拉丁 tabula 及其指小形式 tabella 提供这个词；同一词干衍生 table、tabular 与 tabulate。"},"items":[{"word":"tabula","structure":"tabula, tabulae (f., first declension)","meaning":"board, writing tablet","meaningCN":"板；书写板","example":"The Latin noun named the flat surface.","exampleCN":"这个拉丁名词命名扁平表面。"},{"word":"tabella","structure":"tabella, tabellae (f., first declension, diminutive)","meaning":"a small tablet or panel","meaningCN":"小牌；小画板","example":"The diminutive names a smaller surface.","exampleCN":"指小形式指更小的表面。"},{"word":"tablet","structure":"tablette (Old French) + English adaptation","meaning":"writing slab","meaningCN":"书写平板","example":"The word entered English as tablet.","exampleCN":"这个词以 tablet 进入英语。"},{"word":"table","structure":"tabula + Old French","meaning":"a flat-topped furniture piece","meaningCN":"平顶家具","example":"The same board idea became table.","exampleCN":"同一「板」概念变成 table。"},{"word":"tabular","structure":"tabula + -aris (relating to)","meaning":"arranged in a table","meaningCN":"表格式的","example":"The results appear in tabular form.","exampleCN":"结果以表格形式呈现。"},{"word":"tabulate","structure":"tabula + -are (verb ending)","meaning":"to set out in a table","meaningCN":"列成表格","example":"She tabulated the survey answers.","exampleCN":"她把调查答案列成表。"},{"word":"tabulation","structure":"tabulate + -io (action noun)","meaning":"the act of tabulating","meaningCN":"制表；表格排列","example":"The tabulation took two days.","exampleCN":"制表花了两天。"},{"word":"plaque","structure":"plaque (French, from Dutch placken 'to patch')","meaning":"a fixed commemorative plate","meaningCN":"固定纪念牌","example":"A plaque marks the birthplace.","exampleCN":"一块牌匾标出出生地。"}],"latinEntries":[{"word":"tabula","structure":"tabula, tabulae (f., first declension)","meaning":"board, writing tablet","meaningCN":"板；书写板"},{"word":"tabella","structure":"tabella, tabellae (f., first declension)","meaning":"a small tablet","meaningCN":"小牌；小书写板"},{"word":"tabularium","structure":"tabularium, tabularii (n., second declension)","meaning":"a place for records","meaningCN":"档案存放处"}],"derivatives":[{"word":"tabular","pos":"adj.","zh":"tabula + -ar（形容词后缀）→ 表格式的；平板状的"},{"word":"tabulate","pos":"v.","zh":"tabula + -ate（动词后缀）→ 列成表格"},{"word":"tabulation","pos":"n.","zh":"tabulate + -ion（名词后缀）→ 制表"},{"word":"tabloid","pos":"n.","zh":"tablet + -oid（类似后缀）→ 小报；片剂（旧义）"},{"word":"table","pos":"n.","zh":"tabula 经法语演变 → 桌子；表格"}]}},{"word":"clay tablet","ipa_uk":"/ˌkleɪ ˈtæblət/","ipa_us":"/ˌkleɪ ˈtæblət/","definition_zh":"泥板；刻有楔形文字的黏土板，尤指美索不达米亚的书写载体","definition_en":"a slab of clay used for writing, especially one bearing cuneiform script in ancient Mesopotamia","core_image":"一块还没烧硬的湿泥板放在木架上，表面密密压着楔形刻痕","scene":"考古队员用毛刷清掉泥板边缘的土。A clay tablet from the archive lists the workers' monthly rations.","sceneCN":"这里 clay tablet 指「刻有文字的黏土书写板」（第 1 个义项：黏土书写平板）；句意为档案中的一块泥板列出了工人每月口粮。","pos":[{"tag":"n.","zh":"泥板；楔形文字泥板；黏土书写板"}],"collocations":[{"phrase":"cuneiform clay tablet","zh":"楔形文字泥板"},{"phrase":"baked clay tablet","zh":"烧制泥板"},{"phrase":"clay tablet archive","zh":"泥板档案"},{"phrase":"clay tablet fragment","zh":"泥板残片"},{"phrase":"inscribe a clay tablet","zh":"在泥板上刻字"}],"forms":[{"label":"单数","form":"clay tablet"},{"label":"复数","form":"clay tablets"},{"label":"限定成分","form":"clay"},{"label":"核心名词","form":"tablet"},{"label":"相关文字","form":"cuneiform"},{"label":"相关材料","form":"terracotta"}],"derivatives":[{"word":"clay","pos":"n.","zh":"古英语 clǣg「黏土」→ 黏土；泥土"},{"word":"clayey","pos":"adj.","zh":"clay + -ey（形容词后缀）→ 黏土质的"},{"word":"tablet","pos":"n.","zh":"拉丁 tabula「板」→ 书写平板"},{"word":"cuneiform","pos":"adj./n.","zh":"拉丁 cuneus「楔子」+ -form → 楔形的；楔形文字"},{"word":"terracotta","pos":"n.","zh":"意大利 terra「土」+ cotta「烧过的」→ 陶土；赤陶"}],"senses":[{"no":"01","title":"A clay slab used for writing","titleCN":"用于书写的黏土板","definition":"a flat piece of moist clay shaped by hand and used as a writing surface","definitionCN":"用手塑成、用作书写表面的扁平湿黏土块","example":"A clay tablet from the archive lists the workers' monthly rations.","exampleCN":"档案中的一块泥板列出了工人每月口粮。","why":"clay names the material and tablet names the flat writing slab, so the phrase is a plain description.","whyCN":"clay 指材料，tablet 指扁平书写板，因此整个短语就是直白的描述。"},{"no":"02","title":"A cuneiform document","titleCN":"楔形文字文献","definition":"a tablet bearing wedge-shaped signs pressed into the clay with a stylus","definitionCN":"用尖笔把楔形符号压进黏土而成的板","example":"The cuneiform clay tablet records a sale of barley.","exampleCN":"这块楔形文字泥板记录了一笔大麦交易。","why":"the wedge script was the standard writing of Mesopotamia, so the object and its script became inseparable.","whyCN":"楔形文字是美索不达米亚的标准书写，物件与文字因此不可分。"},{"no":"03","title":"An administrative or legal record","titleCN":"行政或法律记录","definition":"a tablet used for accounts, contracts, inventories or court decisions","definitionCN":"用于账目、契约、清单或法庭裁决的泥板","example":"A clay tablet in the palace archive lists the tax owed by each district.","exampleCN":"王宫档案中的一块泥板列出了各区应缴的税。","why":"clay was cheap and plentiful, which made it the everyday medium of administration rather than of monuments.","whyCN":"黏土便宜且易得，因此成为日常行政媒介，而非纪念碑材料。"},{"no":"04","title":"An archival unit in a collection","titleCN":"收藏中的档案单位","definition":"one item in a museum or library collection of ancient clay records","definitionCN":"博物馆或图书馆所藏古代泥板记录中的一件","example":"The museum catalogue numbers each clay tablet by site and layer.","exampleCN":"博物馆按遗址与地层给每块泥板编号。","why":"once a tablet leaves the ground it becomes a catalogue item, so the phrase names one unit in a collection.","whyCN":"泥板离开土地后成为编目对象，因此这个短语指收藏中的一件单位。"},{"no":"05","title":"A school exercise tablet","titleCN":"学校练习用泥板","definition":"a small tablet used by students to practise signs, sums or copied texts","definitionCN":"学生用来练习符号、算术或抄写文本的小泥板","example":"A child's exercise clay tablet shows the same sign written twenty times.","exampleCN":"一块儿童练习泥板上，同一个符号写了二十遍。","why":"practice tablets were the cheapest use of the medium, and they preserve everyday learning better than formal records.","whyCN":"练习泥板是这种媒介最便宜的用途，比正式记录更能保存日常学习。"},{"no":"06","title":"Sun-dried or baked material","titleCN":"晒干或烧制的材料","definition":"the distinction between a tablet dried in the sun and one fired hard in a kiln","definitionCN":"在阳光下晒干的泥板与在窑中烧硬的泥板之间的区别","example":"A baked clay tablet survives water far better than a sun-dried one.","exampleCN":"烧制泥板比晒干泥板耐水得多。","why":"firing changes the material from soft earth to hard ceramic, so the phrase can name either state.","whyCN":"烧制把材料从软土变成硬陶，因此这个短语可指两种状态。"},{"no":"07","title":"A surface for seal impressions","titleCN":"用于盖印的泥板","definition":"a clay surface pressed with a cylinder seal to mark ownership or authority","definitionCN":"用滚印压出标记以表示所有权或权威的黏土表面","example":"The seal impression on the clay tablet names the merchant.","exampleCN":"泥板上的印章压痕标出了商人的名字。","why":"a cylinder seal rolled over soft clay leaves an ownership mark, turning the tablet into a signed object.","whyCN":"滚印压过软黏土会留下所有权标记，把泥板变成签过名的物件。"},{"no":"08","title":"A metaphor for an unchangeable record","titleCN":"不可更改记录的隐喻","definition":"a way of saying that something has been recorded so firmly that it cannot be altered","definitionCN":"一种说法，表示某事记录得如此牢固以致无法更改","example":"The ruling was written on a clay tablet as far as the villagers were concerned.","exampleCN":"在村民看来，这项裁决就像刻在泥板上一样不可更改。","why":"a dried tablet cannot be smoothed without destroying the text, which makes it a natural image of a fixed record.","whyCN":"干硬的泥板一磨就会毁掉文字，因此自然成为「固定记录」的形象。"}],"etymology":{"intro":{"en":"Clay tablet joins an Old English word for earth with a Latin word for a writing board. The material is native English; the object name arrived through Latin and French.","cn":"clay tablet 把英语本族的「泥土」词与拉丁语的「书写板」词接在一起。材料名是英语本族词，物件名则经拉丁与法语而来。"},"items":[{"era":"OLD ENGLISH CLAEG","en":"Claeg meant clay, the sticky earth used for bricks and pottery.","cn":"clǣg 指黏土，即制砖与制陶用的黏性泥土。"},{"era":"LATIN TABULA","en":"Tabula named a board or writing tablet, the second half of the phrase.","cn":"tabula 指板或书写板，是短语的后半。"},{"era":"OLD FRENCH TABLETTE","en":"The French form carried the board name into English as tablet.","cn":"法语形式把这个「板」名带入英语作 tablet。"},{"era":"MESOPOTAMIAN PRACTICE","en":"Scribes in Mesopotamia wrote on moist clay with a cut reed stylus, then dried or fired the tablet.","cn":"美索不达米亚的书吏用削好的芦苇尖笔在湿黏土上书写，再晒干或烧制。"},{"era":"MODERN TERM","en":"Archaeologists coined the English phrase clay tablet for these finds, pairing material and object name.","cn":"考古学家为这类出土物立了英语短语 clay tablet，把材料名与物件名配在一起。"},{"era":"SOURCE UNCERTAIN","en":"Source uncertain (first date only): the exact date when the English phrase became standard in archaeology is not settled, though both halves are well documented.","cn":"来源不确定（仅首见年代存疑）：这个英语短语在考古学中成为标准术语的确切年代未定，但两个成分都有清楚记载。"}]},"similar":{"note":{"en":"Group one holds writing surfaces and scripts confused with the clay tablet; group two holds archive and material words.","cn":"第一组是容易与泥板混淆的书写表面与文字；第二组是档案与材料词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"tablet","ipa":"/ˈtæblət/","tag":"the bare object","definition":"The flat writing slab itself; clay tablet adds the material and the Mesopotamian setting.","definitionCN":"扁平书写板本身；clay tablet 增添了材料与美索不达米亚语境。"},{"word":"cuneiform","ipa":"/ˈkjuːnɪfɔːm/","tag":"the script, not the object","definition":"The wedge-shaped writing system; a clay tablet is the surface that usually carries it.","definitionCN":"楔形文字体系；泥板通常是承载它的表面。"},{"word":"stele","ipa":"/ˈstiːliː/","tag":"an upright stone slab","definition":"An upright stone or wooden slab with an inscription; it is stone and often public, not clay and archival.","definitionCN":"带铭文的直立石或木板；多为石头且公开，不是黏土档案。"},{"word":"brick","ipa":"/brɪk/","tag":"a building block","definition":"A fired or dried clay block for construction; a tablet is thin and made for writing.","definitionCN":"建筑用的烧制或晒干黏土块；泥板薄且为书写而制。"}]},{"heading":"NEAR MEANING","entries":[{"word":"papyrus","ipa":"/pəˈpaɪrəs/","tag":"a rival writing surface","definition":"A pressed reed sheet used in Egypt; clay tablets served Mesopotamia in the same everyday role.","definitionCN":"埃及使用的压制芦苇纸；泥板在美索不达米亚承担同样的日常角色。"},{"word":"manuscript","ipa":"/ˈmænjuskrɪpt/","tag":"any handwritten text","definition":"A handwritten document; a clay tablet is a handwritten record in a different material.","definitionCN":"手写文件；泥板是另一种材料上的手写记录。"},{"word":"archive","ipa":"/ˈɑːkɪv/","tag":"a collection of records","definition":"An organized collection of records; a clay tablet may be one item in such a collection.","definitionCN":"有组织的记录收藏；泥板可以是其中一件。"},{"word":"terracotta","ipa":"/ˌterəˈkɒtə/","tag":"fired clay as material","definition":"Baked clay used for art and building; a clay tablet may be terracotta after firing, but the word names the material.","definitionCN":"用于艺术与建筑的烧制黏土；泥板烧后可为陶质，但这个词指材料。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: the Old English earth word, the Latin board word and the real cuneiform practice.","cn":"正常联想：英语本族「土」词、拉丁「板」词与真实的楔形文字实践。"},"normal":[{"en":"clay is Old English claeg, the same earth that makes bricks.","cn":"clay 是古英语 claeg，就是制砖的那种土。"},{"en":"tablet is Latin tabula, a board used for writing.","cn":"tablet 是拉丁 tabula，用于书写的板。"},{"en":"Cuneiform signs were pressed with a reed stylus, not painted.","cn":"楔形符号是用芦苇尖笔压出的，不是画上去的。"},{"en":"Sun-dried tablets crumble in water; fired ones survive.","cn":"晒干的泥板遇水会碎；烧制过的能留存。"},{"en":"School tablets preserve the everyday practice of young scribes.","cn":"学校泥板保存了年轻书吏的日常练习。"}],"abstract":[{"en":"A clay tablet is wet earth that agrees to become a law.","cn":"泥板是愿意变成法律的湿土。"},{"en":"It is a record that hardens as it dries, like a decision.","cn":"它是一份随干燥而变硬的记录，像一项决定。"},{"en":"Fire can preserve it or destroy it, much as memory does.","cn":"火能保存它，也能毁掉它，记忆也是如此。"}]},"examples":[{"en":"The clay tablet was baked hard so that it would survive the fire.","cn":"这块泥板被烧硬，以便在火灾中留存。"},{"en":"Each clay tablet in the archive carries a site number.","cn":"档案中的每块泥板都带有一个遗址编号。"},{"en":"The scribe smoothed the clay tablet before pressing the signs.","cn":"书吏先把泥板抹平，再压上符号。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「clay（黏土）+ tablet（板）」——黏土压成的书写板 → 泥板","word":"clay tablet"},"root":"clay 来自古英语 clǣg「黏土」；tablet 来自拉丁 tabula「板」经古法语；短语指美索不达米亚用湿黏土压制、刻楔形文字后晒干或烧制的书写板。","sensesIntro":{"en":"Eight senses follow one object from wet earth to archive: the slab, its script, its administrative use, its catalogue number, its school use, its firing, its seal and its metaphor.","cn":"八个义项让一件物件从湿土走到档案：板、文字、行政用途、编目号、学校用途、烧制、印章与隐喻。"},"semanticMap":{"core":{"en":"CORE IMAGE: a soft square of earth on a wooden board, marked with wedges and left to harden.","cn":"核心意象：木托上一块柔软的方形泥土，压满楔形痕迹，等着变硬。"},"chain":["WET CLAY","FLAT SLAB","WEDGE SIGNS","DAILY RECORD","ARCHIVE ITEM","FIRED STONE"],"branches":[{"senses":"义项 01、义项 06","en":"EARTH AND FIRE: the wet slab and the fired tablet are one material before and after the kiln.","cn":"土与火：湿泥板与烧制泥板是同一材料在窑前窑后。"},{"senses":"义项 02、义项 05","en":"SCRIPT AND SCHOOL: formal cuneiform and a child's exercise both press signs into the same clay.","cn":"文字与学校：正式楔形文字与儿童练习都把符号压进同样的黏土。"},{"senses":"义项 03、义项 04","en":"RECORD AND COLLECTION: an administrative tablet becomes one numbered item in an archive.","cn":"记录与收藏：行政泥板变成档案中一件编号藏品。"},{"senses":"义项 07","en":"SEALED AUTHORITY: a cylinder seal pressed into clay marks who owns or commands.","cn":"盖印的权威：滚印压进黏土，标出谁拥有或谁下令。"},{"senses":"义项 08","en":"UNCHANGEABLE WORD: a dried tablet becomes the image of a record that cannot be rewritten.","cn":"不可更改的话：干硬的泥板成为无法改写的记录形象。"}]},"affixes":{"intro":{"en":"Clay tablet is a two-word technical phrase, one word native English and one carried through Latin and French.","cn":"clay tablet 是两词技术短语，一个来自英语本族，一个经拉丁与法语传来。"},"latinIntro":{"en":"Latin tabula supplies the board name; English claeg supplies the material, so the phrase has no single Latin ancestor.","cn":"拉丁 tabula 提供「板」名；英语 clǣg 提供材料名，因此短语没有单一拉丁祖先。"},"items":[{"word":"claeg","structure":"claeg (Old English noun)","meaning":"clay, sticky earth","meaningCN":"黏土；黏性泥土","example":"The native word names the material.","exampleCN":"本族词命名材料。"},{"word":"clay","structure":"claeg + Modern English spelling","meaning":"earth used for pottery","meaningCN":"制陶用黏土","example":"The clay was still damp.","exampleCN":"黏土仍然潮湿。"},{"word":"tabula","structure":"tabula, tabulae (f., first declension)","meaning":"board, writing tablet","meaningCN":"板；书写板","example":"Latin names the flat object.","exampleCN":"拉丁语命名扁平物件。"},{"word":"tablet","structure":"tablette (Old French) + English","meaning":"writing slab","meaningCN":"书写平板","example":"The tablet was thin and square.","exampleCN":"泥板薄而方。"},{"word":"cuneiform","structure":"cuneus 'wedge' + -formis 'shaped'","meaning":"wedge-shaped script","meaningCN":"楔形文字","example":"Cuneiform signs filled the surface.","exampleCN":"楔形符号布满表面。"},{"word":"stylus","structure":"stylus, styli (Latin noun, from Greek stulos)","meaning":"a pointed writing tool","meaningCN":"尖笔","example":"A reed stylus pressed the signs.","exampleCN":"芦苇尖笔压出符号。"},{"word":"terracotta","structure":"terra 'earth' + cocta 'baked'","meaning":"baked clay","meaningCN":"烧制黏土；赤陶","example":"Firing turns clay into terracotta.","exampleCN":"烧制把黏土变成陶。"},{"word":"archive","structure":"archivum (Latin, from Greek arkheion)","meaning":"a place of records","meaningCN":"档案；档案馆","example":"The tablet entered the archive.","exampleCN":"泥板进入档案。"}],"latinEntries":[{"word":"tabula","structure":"tabula, tabulae (f., first declension)","meaning":"board, writing tablet","meaningCN":"板；书写板"},{"word":"cuneus","structure":"cuneus, cunei (m., second declension)","meaning":"a wedge","meaningCN":"楔子"}],"derivatives":[{"word":"clay","pos":"n.","zh":"古英语 clǣg → 黏土；泥土"},{"word":"clayey","pos":"adj.","zh":"clay + -ey（形容词后缀）→ 黏土质的"},{"word":"tablet","pos":"n.","zh":"拉丁 tabula「板」经法语 → 书写平板"},{"word":"cuneiform","pos":"adj./n.","zh":"拉丁 cuneus「楔子」+ -form → 楔形的；楔形文字"},{"word":"terracotta","pos":"n.","zh":"意大利 terra「土」+ cotta「烧过的」→ 陶土；赤陶"}]}},{"word":"monument","ipa_uk":"/ˈmɒnjumənt/","ipa_us":"/ˈmɑːnəmənt/","definition_zh":"纪念碑；纪念物；古迹；有永久价值的成就或证据","definition_en":"a structure built to commemorate a person or event; a historic site; a lasting example or achievement","core_image":"广场中央的石柱在夕阳下投出长影，碑座上刻着几行名字","scene":"广场中央的石柱在夕阳下投出长影。The monument honors the engineers who built the first bridge.","sceneCN":"这里 monument 指「为纪念人物或事件而建的纪念性建筑」（第 1 个义项：纪念建筑）；句意为这座纪念碑向建造第一座桥的工程师致敬。","pos":[{"tag":"n.","zh":"纪念碑；纪念物；古迹；典范；不朽成就"}],"collocations":[{"phrase":"national monument","zh":"国家纪念碑；国家保护区"},{"phrase":"historic monument","zh":"历史古迹"},{"phrase":"erect a monument","zh":"建立纪念碑"},{"phrase":"monument to peace","zh":"和平纪念碑"},{"phrase":"ancient monument","zh":"古代遗迹"}],"forms":[{"label":"单数","form":"monument"},{"label":"复数","form":"monuments"},{"label":"相关形容词","form":"monumental"},{"label":"相关名词（纪念性）","form":"monumentality"},{"label":"相关动词（纪念）","form":"monumentalize"}],"derivatives":[{"word":"monumental","pos":"adj.","zh":"monument + -al（形容词后缀）→ 纪念碑的；巨大的"},{"word":"monumentality","pos":"n.","zh":"monumental + -ity（性质后缀）→ 纪念性；宏伟感"},{"word":"monumentally","pos":"adv.","zh":"monumental + -ly（副词后缀）→ 巨大地；极其"},{"word":"monumentalize","pos":"v.","zh":"monumental + -ize（动词后缀）→ 使成为纪念物"},{"word":"monumentalization","pos":"n.","zh":"monumentalize + -ation（名词后缀）→ 纪念化"}],"senses":[{"no":"01","title":"A commemorative structure","titleCN":"纪念性建筑","definition":"a building, statue or stone erected to keep the memory of a person or event","definitionCN":"为保存对某人或某事的记忆而建成的建筑、雕像或石碑","example":"The monument honors the engineers who built the first bridge.","exampleCN":"这座纪念碑向建造第一座桥的工程师致敬。","why":"monumentum came from monere 'to remind'; the structure exists to make people remember.","whyCN":"monumentum 来自 monere「提醒」；这座建筑存在的目的就是让人记住。"},{"no":"02","title":"A historic building or site","titleCN":"历史建筑或遗址","definition":"an old building, ruin or place preserved because of its historical importance","definitionCN":"因历史重要性而被保存的古老建筑、废墟或地点","example":"The abbey is listed as a monument of national importance.","exampleCN":"这座修道院被列为具有国家重要性的历史建筑。","why":"the same word moved from a purpose-built memorial to any old structure that a nation decides to protect.","whyCN":"同一个词从专门建造的纪念物，扩展到国家决定保护的任何古老建筑。"},{"no":"03","title":"A tombstone or grave memorial","titleCN":"墓碑或墓地纪念物","definition":"a stone or structure marking a grave and preserving a name","definitionCN":"标记墓地并保存姓名的石碑或建筑","example":"A simple monument marks the grave of the village teacher.","exampleCN":"一块朴素的墓碑标出乡村教师的墓。","why":"a grave marker is the smallest and oldest kind of memorial, a stone that keeps one name in place.","whyCN":"墓碑是最小、最古老的纪念物，一块石头把一个人的名字留在原处。"},{"no":"04","title":"A lasting evidence or example","titleCN":"持久的证据或典型","definition":"something that stands as clear evidence of a quality, often a bad one","definitionCN":"作为某种品质（常为负面）的明显证据的事物","example":"The empty factory is a monument to poor planning.","exampleCN":"那座空工厂是规划不善的活证据。","why":"the commemorative sense turns ironic: a thing can remind people of a failure as well as a hero.","whyCN":"纪念义可转为反讽：事物既能让人记住英雄，也能让人记住失败。"},{"no":"05","title":"An outstanding achievement or work","titleCN":"杰出成就或作品","definition":"a work or achievement so important that it deserves to be remembered","definitionCN":"重要到值得被记住的作品或成就","example":"The dictionary is a monument of nineteenth-century scholarship.","exampleCN":"这部词典是十九世纪学术的不朽丰碑。","why":"what deserves a monument is what a culture wants to keep, so the word extends from stone to achievement.","whyCN":"值得立碑的东西就是文化想留住的东西，因此词义从石头扩展到成就。"},{"no":"06","title":"An ancient ruin","titleCN":"古代遗迹","definition":"a surviving structure of an earlier civilization, often visited as a heritage site","definitionCN":"早期文明留存下来的建筑，常作为文化遗产参观","example":"Tourists walked among the monuments of the old capital.","exampleCN":"游客在旧都的遗迹间行走。","why":"once a whole city is old enough, its surviving structures become monuments by age rather than by design.","whyCN":"当整座城市足够古老，留存下来的建筑就凭年代而非设计成为遗迹。"},{"no":"07","title":"A statue","titleCN":"雕像","definition":"a sculpted figure set up in public to honor a person","definitionCN":"为纪念某人而置于公共空间的雕塑人像","example":"A bronze monument of the founder stands in the square.","exampleCN":"广场上立着创始人的铜像。","why":"a statue is a monument given a human shape, the memorial impulse turned into a sculpted body.","whyCN":"雕像是一座拥有人形的纪念碑，是纪念冲动变成雕塑身体。"},{"no":"08","title":"A written memorial record","titleCN":"书面的纪念记录","definition":"a written account or record kept to preserve someone's memory","definitionCN":"为保存某人记忆而留下的书面记述或记录","example":"The chronicle is a monument in words rather than in stone.","exampleCN":"这部编年史是用文字而非石头筑成的纪念碑。","why":"a written record performs the same reminding job as a stone, so the word extends to books and chronicles.","whyCN":"书面记录承担与石头相同的提醒功能，因此词义扩展到书籍与编年史。"}],"etymology":{"intro":{"en":"Monument comes from Latin monumentum, 'a memorial, a monument', from monere 'to remind, warn'. The same verb gives monitor and admonish, so the core idea is something that makes you remember.","cn":"monument 来自拉丁 monumentum「纪念物、纪念碑」，源于 monere「提醒、警告」。同一动词还衍生 monitor 与 admonish，核心意思是「让人想起的东西」。"},"items":[{"era":"LATIN MONERE","en":"Monere meant 'to remind, warn, advise', the act behind every monument.","cn":"monere 意为「提醒、警告、劝告」，是每座纪念碑背后的动作。"},{"era":"LATIN MONUMENTUM","en":"Monumentum was 'a thing that reminds', whether a building, a tomb or a written record.","cn":"monumentum 指「使人想起的东西」，可以是建筑、坟墓或书面记录。"},{"era":"ENGLISH 13TH CENTURY","en":"English borrowed the word first for a memorial structure or tomb.","cn":"英语在十三世纪借入这个词，最初指纪念建筑或坟墓。"},{"era":"HERITAGE SENSE","en":"Later it covered preserved old buildings and ruins, especially in heritage law.","cn":"后来它覆盖受保护的古老建筑与废墟，尤其在遗产法规中。"},{"era":"FIGURATIVE SENSE","en":"The word then extended to achievements and to ironic examples, as in a monument to folly.","cn":"再后来扩展到成就与反讽例证，如「愚蠢的纪念碑」。"}]},"similar":{"note":{"en":"Group one holds memorial objects easily confused with a monument; group two holds words for importance and remembrance.","cn":"第一组是容易与 monument 混淆的纪念物；第二组是表示重要与纪念的词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"memorial","ipa":"/məˈmɔːriəl/","tag":"anything that preserves memory","definition":"A object or event that keeps a memory; a monument is one kind, usually built and public.","definitionCN":"保存记忆的物件或活动；monument 是其中一种，通常是建成且公开的。"},{"word":"memento","ipa":"/məˈmentəʊ/","tag":"a small keepsake","definition":"A small object kept as a reminder; it is personal, while a monument is public and large.","definitionCN":"留作提醒的小物件；属私人性质，纪念碑则公开且宏大。"},{"word":"monumental","ipa":"/məˈnjuːməntl/","tag":"the adjective","definition":"The describing word for a monument or for something huge; the noun is the object itself.","definitionCN":"描述纪念碑或巨大事物的形容词；名词指物件本身。"},{"word":"memorandum","ipa":"/məˈrændəm/","tag":"a written note","definition":"A written reminder or note; it shares the reminder root but names a document, not a structure.","definitionCN":"书面提醒或便条；共享「提醒」词根，但指文件而非建筑。"}]},{"heading":"NEAR MEANING","entries":[{"word":"statue","ipa":"/ˈstætʃuː/","tag":"a sculpted figure","definition":"A carved or cast figure of a person or animal; a monument may be a statue, but may also be a wall or arch.","definitionCN":"人或动物的雕刻或铸造形象；纪念碑可以是雕像，也可能是墙或拱门。"},{"word":"shrine","ipa":"/ʃraɪn/","tag":"a sacred memorial place","definition":"A holy place or structure marking a sacred person or event; the emphasis is religious.","definitionCN":"标记神圣人物或事件的圣地或建筑；侧重宗教。"},{"word":"landmark","ipa":"/ˈlændmɑːk/","tag":"a notable feature","definition":"A easily recognized feature of a place; a monument is built to remember, a landmark may simply be noticed.","definitionCN":"一个地方易被认出的特征；纪念碑为记忆而建，地标只是显眼。"},{"word":"tomb","ipa":"/tuːm/","tag":"a burial structure","definition":"A grave or burial chamber; a monument may mark a tomb but need not contain a body.","definitionCN":"坟墓或墓室；纪念碑可标记坟墓，但不一定葬有遗体。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: the Latin reminder verb, the real public object and the ironic extension.","cn":"正常联想：拉丁「提醒」动词、真实的公共物件与反讽引申。"},"normal":[{"en":"monere is 'to remind'; a monument is a reminder made of stone.","cn":"monere 是「提醒」；纪念碑是用石头做成的提醒。"},{"en":"Monitor and admonish come from the same verb.","cn":"monitor 与 admonish 同出这个动词。"},{"en":"Heritage law uses monument for protected old buildings.","cn":"遗产法规用 monument 指受保护的古老建筑。"},{"en":"A monument can be ironic: a monument to bad planning.","cn":"纪念碑可以带反讽：规划不善的纪念碑。"},{"en":"A written chronicle can be called a monument in words.","cn":"一部编年史可称为文字筑成的纪念碑。"}],"abstract":[{"en":"A monument is a stone that keeps saying a name after the mouth is gone.","cn":"纪念碑是一块在嘴消失后仍不断念出名字的石头。"},{"en":"It is memory given a body heavy enough to stay put.","cn":"它是被赋予足够沉重身体、无法轻易移走的记忆。"},{"en":"A bad monument is a culture arguing with its own past.","cn":"糟糕的纪念碑，是一个文化在与自己的过去争吵。"}]},"examples":[{"en":"The city erected a monument to the nurses who died in the epidemic.","cn":"这座城市为死于疫病的护士建立了纪念碑。"},{"en":"The old bridge is a monument of early engineering.","cn":"这座旧桥是早期工程的不朽之作。"},{"en":"The empty tower stands as a monument to failed ambition.","cn":"那座空塔成了野心失败的一座纪念碑。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「monu（提醒）+ ment（物）」——让人记住的东西 → 纪念碑","word":"monument"},"root":"拉丁 monumentum「使人想起的东西」← monere「提醒、警告」+ -mentum（名词后缀）；同源词有 monitor、admonish。英语 monument。","sensesIntro":{"en":"Eight senses follow one reminder: a built memorial, a protected site, a grave, a warning example, an achievement, a ruin, a statue and a written record.","cn":"八个义项沿同一个提醒展开：建成的纪念物、受保护遗址、坟墓、警示例证、成就、废墟、雕像与书面记录。"},"semanticMap":{"core":{"en":"CORE IMAGE: a heavy stone standing in a square, repeating a name to everyone who passes.","cn":"核心意象：广场上一块沉重的石头，向每个经过的人重复一个名字。"},"chain":["REMINDER","BUILT MEMORY","PROTECTED SITE","GRAVE MARK","WARNING EXAMPLE","GREAT WORK"],"branches":[{"senses":"义项 01、义项 03","en":"STONE MEMORY: a public memorial and a grave marker both make a name outlast a life.","cn":"石头记忆：公共纪念碑与墓碑都让名字活得比生命更久。"},{"senses":"义项 02、义项 06","en":"PROTECTED PAST: a listed building and an ancient ruin are the past kept in place.","cn":"受保护的过去：登录建筑与古代废墟都是被留在原地的过去。"},{"senses":"义项 04、义项 05","en":"VALUE JUDGEMENT: an ironic example and a great achievement both measure a culture's memory.","cn":"价值判断：反讽例证与伟大成就都在衡量一个文化的记忆。"},{"senses":"义项 07","en":"HUMAN FIGURE: a statue makes the reminder take a body.","cn":"人形：雕像让提醒拥有身体。"},{"senses":"义项 08","en":"WRITTEN STONE: a chronicle is a monument made of words instead of rock.","cn":"文字之石：编年史是用文字而非岩石筑成的纪念碑。"}]},"affixes":{"intro":{"en":"Monument is a Latin reminder noun, and its family still carries the idea of warning and memory.","cn":"monument 是一个拉丁「提醒」名词，其词族仍带着警告与记忆的意思。"},"latinIntro":{"en":"Latin monere gives monitor, admonish and monumentum; the suffix -mentum turns the act of reminding into a thing.","cn":"拉丁 monere 衍生 monitor、admonish 与 monumentum；后缀 -mentum 把「提醒」的动作变成物件。"},"items":[{"word":"monere","structure":"monere, monui, monitum (Latin verb, second conjugation)","meaning":"to remind, warn","meaningCN":"提醒；警告","example":"The verb is the root of the noun.","exampleCN":"这个动词是名词的词根。"},{"word":"-mentum","structure":"-mentum (Latin noun suffix)","meaning":"means or result of an action","meaningCN":"动作的手段或结果","example":"The suffix turns reminding into a thing.","exampleCN":"这个后缀把「提醒」变成物件。"},{"word":"monumentum","structure":"monumentum, monumenti (n., second declension)","meaning":"a memorial, a reminder","meaningCN":"纪念物；提醒之物","example":"Latin named the memorial object.","exampleCN":"拉丁语命名纪念物件。"},{"word":"monument","structure":"monumentum + French","meaning":"a commemorative structure","meaningCN":"纪念性建筑","example":"The monument stands in the square.","exampleCN":"纪念碑立在广场上。"},{"word":"monitor","structure":"monere + -tor (agent noun)","meaning":"one who reminds or watches","meaningCN":"提醒者；监督者","example":"A monitor checks the exam.","exampleCN":"监考人监督考试。"},{"word":"admonish","structure":"ad- + monere","meaning":"to warn toward","meaningCN":"告诫；警告","example":"She admonished him for lateness.","exampleCN":"她告诫他不要迟到。"},{"word":"monumental","structure":"monument + -alis","meaning":"of a monument; huge","meaningCN":"纪念碑的；巨大的","example":"The gateway is monumental.","exampleCN":"这座门楼极为宏伟。"},{"word":"monumentality","structure":"monumental + -itas","meaning":"the quality of being monumental","meaningCN":"纪念性；宏伟感","example":"The hall has a cold monumentality.","exampleCN":"大厅有一种冷峻的宏伟感。"}],"latinEntries":[{"word":"monere","structure":"monere, monui, monitum (verb, second conjugation)","meaning":"to remind, warn","meaningCN":"提醒；警告"},{"word":"monumentum","structure":"monumentum, monumenti (n., second declension)","meaning":"a memorial, a reminder","meaningCN":"纪念物；提醒之物"},{"word":"monitor","structure":"monitor, monitoris (m., third declension)","meaning":"one who reminds or warns","meaningCN":"提醒者；告诫者"}],"derivatives":[{"word":"monumental","pos":"adj.","zh":"monument + -al（形容词后缀）→ 纪念碑的；巨大的"},{"word":"monumentality","pos":"n.","zh":"monumental + -ity（性质后缀）→ 纪念性；宏伟感"},{"word":"monumentally","pos":"adv.","zh":"monumental + -ly（副词后缀）→ 巨大地；极其"},{"word":"monumentalize","pos":"v.","zh":"monumental + -ize（动词后缀）→ 使成为纪念物"},{"word":"monumentalization","pos":"n.","zh":"monumentalize + -ation（名词后缀）→ 纪念化"}]}},{"word":"monumental","ipa_uk":"/məˈnjuːməntəl/","ipa_us":"/məˈnuːməntəl/","definition_zh":"纪念碑的；纪念性的；巨大的；具有重大而持久意义的；（口语）极大的（错误等）","definition_en":"serving as a monument; very large or imposing; historically important; extreme in degree","core_image":"游客站在巨大的石门前，门框高得让人显得很小，石缝里长着细草","scene":"游客站在巨大的石门前，人显得很小。The monumental gateway dwarfs every visitor who passes through.","sceneCN":"这里 monumental 指「巨大而宏伟的」（第 2 个义项：体量宏大）；句意为这座宏伟的门楼让每个穿过的人都显得渺小。","pos":[{"tag":"adj.","zh":"纪念碑的；纪念性的；巨大的；重大的；极端的"}],"collocations":[{"phrase":"monumental scale","zh":"巨大的规模"},{"phrase":"monumental achievement","zh":"不朽成就"},{"phrase":"monumental error","zh":"极大的错误"},{"phrase":"monumental sculpture","zh":"纪念性雕塑"},{"phrase":"monumental architecture","zh":"纪念性建筑"}],"forms":[{"label":"原级","form":"monumental"},{"label":"比较级","form":"more monumental"},{"label":"最高级","form":"most monumental"},{"label":"副词","form":"monumentally"},{"label":"名词（宏伟感）","form":"monumentality"},{"label":"动词（使纪念化）","form":"monumentalize"}],"derivatives":[{"word":"monumentality","pos":"n.","zh":"monumental + -ity（性质后缀）→ 纪念性；宏伟感"},{"word":"monumentally","pos":"adv.","zh":"monumental + -ly（副词后缀）→ 巨大地；极其"},{"word":"monumentalize","pos":"v.","zh":"monumental + -ize（动词后缀）→ 使成为纪念物"},{"word":"monumentalization","pos":"n.","zh":"monumentalize + -ation（名词后缀）→ 纪念化"},{"word":"monument","pos":"n.","zh":"monumental 去掉 -al → 纪念碑；纪念物"}],"senses":[{"no":"01","title":"Of or serving as a monument","titleCN":"纪念碑的；纪念性的","definition":"belonging to a monument or serving to commemorate someone or something","definitionCN":"属于纪念碑的，或用于纪念某人某事的","example":"The monumental inscription was cut deep enough to survive centuries.","exampleCN":"那篇纪念铭文刻得足够深，得以留存数百年。","why":"the adjective simply adds -al to monument, so its first job is to describe memorial objects.","whyCN":"这个形容词只是给 monument 加 -al，因此首要职能是描述纪念物件。"},{"no":"02","title":"Very large and imposing","titleCN":"巨大而宏伟的","definition":"extremely large, solid or grand in appearance","definitionCN":"在外观上极大、坚固或壮丽","example":"The monumental gateway dwarfs every visitor who passes through.","exampleCN":"这座宏伟的门楼让每个穿过的人都显得渺小。","why":"memorial buildings were built oversized to impress, so size became part of the adjective's meaning.","whyCN":"纪念建筑常被建得超大以震撼人心，因此「巨大」成为形容词义的一部分。"},{"no":"03","title":"Historically important and enduring","titleCN":"具有重大而持久意义的","definition":"of great and lasting importance in history or culture","definitionCN":"在历史或文化上具有重大而持久的重要性","example":"The treaty was a monumental step toward peace.","exampleCN":"这项条约是迈向和平的重大一步。","why":"what deserves a monument is what a society wants to remember, so importance follows from the memorial core.","whyCN":"值得立碑的东西就是社会想记住的东西，因此「重要」由纪念核心引申而来。"},{"no":"04","title":"Of great artistic or intellectual scale","titleCN":"艺术或思想规模宏大的","definition":"large in scope, ambition or intellectual reach, as a work of art or scholarship","definitionCN":"在范围、雄心或思想深度上宏大的，如艺术作品或学术成果","example":"The novel is a monumental study of a single family.","exampleCN":"这部小说是对一个家族的大规模研究。","why":"size moves from stone to thought: a work that covers everything earns the same adjective.","whyCN":"「大」从石头转到思想：包罗万象的作品获得同一个形容词。"},{"no":"05","title":"Extreme, especially a mistake","titleCN":"极端的（尤指错误）","definition":"used informally to mean extremely bad, foolish or costly","definitionCN":"口语中表示极坏、极蠢或代价极高","example":"Leaving the deed unsigned was a monumental blunder.","exampleCN":"没在契约上签字是极大的失误。","why":"a huge mistake looks like a huge stone monument to failure, an ironic use of the size sense.","whyCN":"巨大错误像一座为失败而立的大石碑，是对「巨大」义的反讽用法。"},{"no":"06","title":"Massive in effort or cost","titleCN":"耗费巨大的","definition":"requiring enormous effort, money or time","definitionCN":"需要极大努力、金钱或时间","example":"The restoration was a monumental task for a small team.","exampleCN":"对一个小团队来说，这次修复是一项艰巨无比的任务。","why":"a task that fills the whole horizon looks as large as a memorial building, so effort borrows the size sense.","whyCN":"占满整个视野的任务看起来像纪念建筑一样大，因此「努力」借用了「体量」义。"},{"no":"07","title":"Commemorative in function","titleCN":"功能上用于纪念的","definition":"created or used to preserve public memory rather than for daily use","definitionCN":"为保存公共记忆而非日常使用而创造或使用的","example":"The arch is monumental in function, not a road building.","exampleCN":"这座拱门在功能上是纪念性的，不是交通建筑。","why":"function, not size, decides this sense: the structure exists to be remembered through, not used as a route.","whyCN":"决定这一义的是功能而非大小：这座建筑的存在是为了被记住，而不是当作路线使用。"},{"no":"08","title":"Relating to ancient monuments","titleCN":"与古代纪念物有关的","definition":"connected with the study or preservation of ancient monuments","definitionCN":"与古代纪念物的研究或保护有关的","example":"The survey maps every monumental site in the valley.","exampleCN":"这次调查标出了山谷中每一处古代纪念遗址。","why":"heritage work uses the adjective in its oldest sense, pointing back to the stones themselves.","whyCN":"遗产工作使用这个形容词最古老的义项，指回石头本身。"}],"etymology":{"intro":{"en":"Monumental is monument plus the Latin adjective suffix -alis. The 'very large' sense grew from the oversized scale of memorial buildings, and later spread to achievements and mistakes.","cn":"monumental 是 monument 加拉丁形容词后缀 -alis。『巨大』义起源于纪念建筑的超常体量，后来扩展到成就与错误。"},"items":[{"era":"LATIN MONUMENTUM","en":"Monumentum meant a memorial or reminder, the noun behind the adjective.","cn":"monumentum 指纪念物或提醒之物，是形容词背后的名词。"},{"era":"LATIN -ALIS","en":"The suffix -alis meant 'relating to', the regular way to make an adjective from a noun.","cn":"后缀 -alis 意为「与……有关的」，是由名词构成形容词的常规方式。"},{"era":"ENGLISH 16TH CENTURY","en":"English formed monumental to mean 'of a monument' or 'serving as a memorial'.","cn":"英语构成 monumental，意为「纪念碑的」或「起纪念作用的」。"},{"era":"SCALE SENSE","en":"Because memorial buildings were deliberately oversized, the adjective acquired the sense 'very large'.","cn":"由于纪念建筑刻意造得超大，这个形容词获得了「巨大」的意思。"},{"era":"FIGURATIVE SPREAD","en":"In modern use it also describes great achievements, huge tasks and extreme errors.","cn":"在现代用法中，它也描述伟大成就、艰巨任务与极端错误。"}]},"similar":{"note":{"en":"Group one holds adjectives of size and grandeur easily confused with monumental; group two holds words for importance.","cn":"第一组是容易与 monumental 混淆的表示大小与宏伟的形容词；第二组是表示重要性的词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"monument","ipa":"/ˈmɒnjumənt/","tag":"the noun","definition":"The memorial object itself; monumental is the adjective describing it or something huge.","definitionCN":"纪念物件本身；monumental 是描述它或描述巨大事物的形容词。"},{"word":"momentous","ipa":"/məˈmentəs/","tag":"important in effect","definition":"Of great consequence, often for events; it shares the sound but comes from momentum, not monere.","definitionCN":"后果重大，常用于事件；发音相近，但来自 momentum，而非 monere。"},{"word":"elemental","ipa":"/ˌelɪˈmentl/","tag":"of basic elements","definition":"Relating to the basic elements or to raw natural forces; the ending is similar but the root is different.","definitionCN":"与基本元素或原始自然力有关；词尾相似，词根不同。"},{"word":"fundamental","ipa":"/ˌfʌndəˈmentl/","tag":"at the base","definition":"Serving as a foundation; it shares -mental but comes from fundus, a bottom.","definitionCN":"作为基础的；共享 -mental 词尾，但来自 fundus「底部」。"}]},{"heading":"NEAR MEANING","entries":[{"word":"colossal","ipa":"/kəˈlɒsl/","tag":"huge in size","definition":"Extremely large, often with a sense of excess; monumental adds the memorial or historic dimension.","definitionCN":"极大，常带过度意味；monumental 增添了纪念或历史维度。"},{"word":"grand","ipa":"/ɡrænd/","tag":"impressive in scale","definition":"Large and impressive in appearance or style; it stresses dignity rather than memory.","definitionCN":"外观或风格上宏大而令人印象深刻；强调尊严，而非记忆。"},{"word":"historic","ipa":"/hɪˈstɒrɪk/","tag":"important in history","definition":"Important in history, often for a single event; monumental stresses lasting commemorative weight.","definitionCN":"历史上重要，常指单一事件；monumental 强调持久的纪念分量。"},{"word":"massive","ipa":"/ˈmæsɪv/","tag":"very heavy and solid","definition":"Very large, heavy and solid; it describes physical bulk, not significance.","definitionCN":"极大、极重且坚实；描述物理体量，而非意义。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: the reminder noun, the Latin suffix and the real scale of memorial buildings.","cn":"正常联想：『提醒』名词、拉丁后缀与纪念建筑的真实体量。"},"normal":[{"en":"monument plus -al makes the describing word.","cn":"monument 加 -al 构成描述词。"},{"en":"Memorial buildings were built oversized to impress, which produced the 'huge' sense.","cn":"纪念建筑被造得超大以震撼人心，由此产生「巨大」义。"},{"en":"A monumental achievement is one a culture would put on a plinth.","cn":"不朽成就就是文化愿意放上基座的成就。"},{"en":"A monumental error is a huge stone raised to failure.","cn":"极大错误是为失败竖起的一块大石。"},{"en":"The adverb monumentally often means simply extremely.","cn":"副词 monumentally 常只表示「极其」。"}],"abstract":[{"en":"Monumental is memory measured in tons.","cn":"monumental 是以吨计的记忆。"},{"en":"It is the adjective a building wears when it wants to outlive its city.","cn":"它是建筑想比城市活得更久时穿上的形容词。"},{"en":"A monumental mistake is a monument no one meant to build.","cn":"极大的错误是一座没人打算建的纪念碑。"}]},"examples":[{"en":"The cathedral is a monumental work of medieval engineering.","cn":"这座大教堂是中世纪工程的宏伟作品。"},{"en":"They made a monumental effort to finish before winter.","cn":"他们付出巨大努力，要在冬天前完工。"},{"en":"The report contained a monumental error in its figures.","cn":"报告的数字里有一个极大的错误。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「monument（纪念碑）+ al」——像纪念碑一样大 → 巨大的、不朽的","word":"monumental"},"root":"monument（拉丁 monumentum「纪念物」）+ -al（拉丁形容词后缀 -alis）→ monumental；『巨大』义由纪念建筑的超常体量引申，再扩展到成就与错误。","sensesIntro":{"en":"Eight senses grow from memorial function to physical size, then to historic weight, artistic scope, extreme degree, effort, public memory and ancient sites.","cn":"八个义项从纪念功能长到体量，再到历史分量、艺术规模、极端程度、耗费、公共记忆与古代遗址。"},"semanticMap":{"core":{"en":"CORE IMAGE: a doorway built so large that a person becomes a small mark at its base.","cn":"核心意象：一道造得极大的门，人在门脚变成一个小小的记号。"},"chain":["OF A MONUMENT","OVERSIZED","HISTORIC WEIGHT","GRAND SCOPE","EXTREME DEGREE","ANCIENT SITE"],"branches":[{"senses":"义项 01、义项 07","en":"MEMORIAL FUNCTION: describing a monument and acting as one are the same purpose seen as label and as use.","cn":"纪念功能：描述纪念碑与起纪念碑作用，是同一目的在标签与用途两面。"},{"senses":"义项 02、义项 06","en":"GREAT BULK: an oversized gateway and a massive task both measure size in effort or stone.","cn":"巨大体量：超大城门与艰巨任务都以石头或努力衡量大小。"},{"senses":"义项 03、义项 04","en":"WEIGHT OF ACHIEVEMENT: historic importance and grand intellectual scope both make a work worth remembering.","cn":"成就的分量：历史重要性与宏大的思想规模都让作品值得被记住。"},{"senses":"义项 05","en":"IRONIC EXTREME: a monumental blunder turns size into blame.","cn":"反讽的极端：极大失误把「大」变成责备。"},{"senses":"义项 08","en":"ANCIENT SITES: the adjective returns to old stones in heritage work.","cn":"古代遗址：在遗产工作中，这个形容词又回到古老的石头。"}]},"affixes":{"intro":{"en":"Monumental is a regular Latin-derived adjective from monument, and its endings also build abstract nouns and adverbs.","cn":"monumental 是由 monument 规则地派生出的拉丁式形容词，其词尾还构成抽象名词与副词。"},"latinIntro":{"en":"The suffix -alis becomes English -al; -itas becomes -ity in monumentality, and -iter becomes -ly in the adverb.","cn":"后缀 -alis 变成英语 -al；-itas 在 monumentality 中变成 -ity，-iter 在副词中变成 -ly。"},"items":[{"word":"monument","structure":"monumentum, monumenti (n., second declension)","meaning":"a memorial","meaningCN":"纪念物","example":"The noun supplies the base.","exampleCN":"这个名词提供基础。"},{"word":"-al","structure":"-alis (Latin adjectival suffix)","meaning":"relating to","meaningCN":"与……有关的","example":"The suffix makes the adjective.","exampleCN":"这个后缀构成形容词。"},{"word":"monumental","structure":"monument + -al","meaning":"of a monument; huge","meaningCN":"纪念碑的；巨大的","example":"The gate is monumental.","exampleCN":"这座门极为宏伟。"},{"word":"-ity","structure":"-itas (Latin abstract noun suffix)","meaning":"quality of","meaningCN":"……的性质","example":"Monumentality names the quality.","exampleCN":"monumentality 命名这种性质。"},{"word":"-ly","structure":"-iter / English -ly (adverb suffix)","meaning":"in a ... manner","meaningCN":"以……方式","example":"Monumentally means extremely.","exampleCN":"monumentally 意为极其。"},{"word":"-ize","structure":"-izare (verb suffix via Greek)","meaning":"to make","meaningCN":"使……化","example":"To monumentalize is to make into a monument.","exampleCN":"monumentalize 是使成为纪念物。"},{"word":"-ation","structure":"-atio (action noun suffix)","meaning":"act or process","meaningCN":"动作或过程","example":"Monumentalization is the process.","exampleCN":"monumentalization 是这一过程。"},{"word":"monere","structure":"monere (Latin verb)","meaning":"to remind","meaningCN":"提醒","example":"The deepest root still means remind.","exampleCN":"最深词根仍表示「提醒」。"}],"latinEntries":[{"word":"monumentum","structure":"monumentum, monumenti (n., second declension)","meaning":"a memorial","meaningCN":"纪念物"},{"word":"monere","structure":"monere, monui, monitum (verb, second conjugation)","meaning":"to remind, warn","meaningCN":"提醒；警告"}],"derivatives":[{"word":"monumentality","pos":"n.","zh":"monumental + -ity（性质后缀）→ 纪念性；宏伟感"},{"word":"monumentally","pos":"adv.","zh":"monumental + -ly（副词后缀）→ 巨大地；极其"},{"word":"monumentalize","pos":"v.","zh":"monumental + -ize（动词后缀）→ 使成为纪念物"},{"word":"monumentalization","pos":"n.","zh":"monumentalize + -ation（名词后缀）→ 纪念化"},{"word":"monument","pos":"n.","zh":"monumental 去掉 -al → 纪念碑；纪念物"}]}},{"word":"megalith","ipa_uk":"/ˈmeɡəlɪθ/","ipa_us":"/ˈmeɡəlɪθ/","definition_zh":"巨石；史前建筑中使用的大块粗石；竖石、石棚等巨石建筑的构件","definition_en":"a very large rough stone used in prehistoric structures; a standing stone or a slab of a megalithic monument","core_image":"荒野上立着几块竖石，围成一个半圆，石面被风雨磨得凹凸不平","scene":"荒野上立着几块竖石，围成一个半圆。A single megalith stands at the entrance to the stone circle.","sceneCN":"这里 megalith 指「史前建筑中使用的大块粗石」（第 1 个义项：史前巨石）；句意为一块巨石立在石圈入口处。","pos":[{"tag":"n.","zh":"巨石；史前巨石建筑构件"}],"collocations":[{"phrase":"prehistoric megalith","zh":"史前巨石"},{"phrase":"standing megalith","zh":"竖立的巨石"},{"phrase":"megalith tomb","zh":"巨石墓"},{"phrase":"megalithic circle","zh":"巨石圈"},{"phrase":"a field of megaliths","zh":"一片巨石群"}],"forms":[{"label":"单数","form":"megalith"},{"label":"复数","form":"megaliths"},{"label":"相关形容词","form":"megalithic"},{"label":"相关名词（巨石文化）","form":"megalithism"},{"label":"研究者","form":"megalithist"}],"derivatives":[{"word":"megalithic","pos":"adj.","zh":"megalith + -ic（形容词后缀）→ 巨石的；巨石建筑的"},{"word":"megalithism","pos":"n.","zh":"megalith + -ism（体系后缀）→ 巨石建筑传统"},{"word":"megalithist","pos":"n.","zh":"megalith + -ist（研究者后缀）→ 巨石文化研究者"},{"word":"megalithic","pos":"adj.","zh":"megalith + -ic（再次构词）→ 与巨石遗迹有关的"},{"word":"megalosaurus","pos":"n.","zh":"「大」前缀 + sauros「蜥蜴」→ 斑龙：另一条「大」词根线"}],"senses":[{"no":"01","title":"A very large stone in a prehistoric structure","titleCN":"史前建筑中的大块粗石","definition":"a large, roughly shaped stone used as a building element in prehistoric monuments","definitionCN":"史前纪念建筑中用作构件的大块粗加工石头","example":"A single megalith stands at the entrance to the stone circle.","exampleCN":"一块巨石立在石圈入口处。","why":"megas means 'great' and lithos means 'stone'; the word names the size of the block before its function.","whyCN":"megas 意为「巨大」，lithos 意为「石头」；这个词先命名石块的大小，再指其功能。"},{"no":"02","title":"A standing stone or menhir","titleCN":"竖石或独石","definition":"a single tall stone set upright in the ground, often for ritual or memorial purposes","definitionCN":"单独竖立在地面上的高石，常用于仪式或纪念","example":"The tallest megalith in the field leans slightly to the north.","exampleCN":"田野里最高的巨石略微向北倾斜。","why":"the standing stone is the simplest form of the prehistoric large block, so the general term covers it.","whyCN":"竖石是史前大石块最简单的形态，因此通称也覆盖它。"},{"no":"03","title":"A slab in a chamber tomb","titleCN":"石室墓中的石板","definition":"one of the large slabs forming the walls or roof of a prehistoric chamber tomb","definitionCN":"构成史前石室墓墙壁或顶盖的大石板之一","example":"Each megalith of the tomb weighs more than a small car.","exampleCN":"这座墓的每块巨石都比一辆小汽车重。","why":"a tomb built of big slabs uses the same oversized stone unit, now as wall and roof.","whyCN":"用大石板建成的墓使用同样的超大石块单位，只是用作墙与顶。"},{"no":"04","title":"An element of a stone circle","titleCN":"石圈的构成石","definition":"one of the large stones arranged in a ring or oval at a prehistoric site","definitionCN":"史前遗址中排列成环或椭圆的大石之一","example":"Every megalith in the circle is paired with a gap or a sightline.","exampleCN":"石圈中的每块巨石都与一个缺口或视线方向相配。","why":"a ring arrangement gives the stone a place in a pattern, so the unit sense becomes an element sense.","whyCN":"环形排列给石头一个图案中的位置，因此单位义变成元素义。"},{"no":"05","title":"A class of archaeological monument","titleCN":"一类考古遗迹","definition":"the category of monuments built from such large stones, studied as one archaeological class","definitionCN":"由这类大石建成的纪念建筑类别，作为一个考古类别研究","example":"The survey records every megalith within the valley boundary.","exampleCN":"这次调查记录了谷地边界内的每一处巨石遗迹。","why":"surveying turns single stones into a monument class, which is how the word works as an archaeological category.","whyCN":"调查把单块石头归成遗迹类别，这就是这个词作为考古类别的方式。"},{"no":"06","title":"A rough massive block in ancient construction","titleCN":"古代建筑中的粗大石块","definition":"a large rough block used in ancient walls or foundations, not necessarily prehistoric","definitionCN":"古代墙体或地基中使用的大块粗石，不一定属于史前","example":"The fortification rests on megaliths laid without mortar.","exampleCN":"防御墙建在不用灰浆砌合的巨石上。","why":"ancient walls reuse oversized blocks, so the term can describe construction stone outside a prehistoric monument.","whyCN":"古代城墙重复使用超大石块，因此这个词也能描述史前遗迹之外的建筑石料。"},{"no":"07","title":"An immovable obstacle","titleCN":"难以移动的障碍","definition":"a figurative use for something huge, stubborn and impossible to shift","definitionCN":"比喻极其巨大、顽固、无法移动的事物","example":"The old rule sat in the code like a megalith in a field.","exampleCN":"那条旧规定像田野里的巨石一样杵在法典中。","why":"an immovable stone is the natural image for a rule that cannot be shifted.","whyCN":"挪不动的石头，是形容无法撼动的规定的自然意象。"},{"no":"08","title":"A symbol of prehistoric culture","titleCN":"史前文化的象征","definition":"a shorthand image for the stone-building cultures of the Neolithic and Bronze Age","definitionCN":"对新石器与青铜时代筑石文化的简称式形象","example":"The museum uses a megalith as the symbol of its prehistory gallery.","exampleCN":"博物馆用巨石作为史前展厅的标志。","why":"a single stone can stand for an entire building culture, a part-for-whole symbol.","whyCN":"单块石头可以代表整个筑石文化，是以部分代整体的象征。"}],"etymology":{"intro":{"en":"Megalith is a modern scientific compound from Greek megas 'great' and lithos 'stone'. It was coined by nineteenth-century archaeologists who needed one word for the oversized stones of prehistoric monuments.","cn":"megalith 是近代科学复合词，由希腊 megas「巨大」与 lithos「石头」构成。十九世纪考古学家需要一个词来统称史前纪念建筑中的超大石块，于是造出此词。"},"items":[{"era":"GREEK MEGAS","en":"Megas meant 'great, large', the first half of many scientific compounds.","cn":"megas 意为「巨大、大」，是许多科学复合词的前半。"},{"era":"GREEK LITHOS","en":"Lithos meant 'stone', the root behind lithograph and monolith.","cn":"lithos 意为「石头」，是 lithograph 与 monolith 的词根。"},{"era":"MODERN COINAGE","en":"The compound megalith was formed in English, not inherited whole from Greek.","cn":"复合词 megalith 是在英语中构成的，并非从希腊语整体继承。"},{"era":"ARCHAEOLOGY 19TH CENTURY","en":"Archaeologists adopted it for the large stones of dolmens, menhirs and stone circles.","cn":"考古学家用它指石棚、独石与石圈中的大石。"},{"era":"ENGLISH DIFFUSION","en":"The word spread with the study of prehistoric monuments and produced the adjective megalithic.","cn":"随着史前遗迹研究传播，这个词又产出了形容词 megalithic。"},{"era":"SOURCE UNCERTAIN","en":"Source uncertain (first date only): the exact year of the first English use is given differently in different sources, though the Greek parts are certain.","cn":"来源不确定（仅首见年代存疑）：各资料给出的英语首见年份不一，但希腊成分是确定的。"}]},"similar":{"note":{"en":"Group one holds stone monument types easily confused with a megalith; group two holds words for big stones and large scale.","cn":"第一组是容易与巨石混淆的石构遗迹类型；第二组是表示大石与巨大尺度的词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"menhir","ipa":"/ˈmenhɪə/","tag":"a single standing stone","definition":"A lone upright stone; a megalith may be part of a larger structure.","definitionCN":"单独竖立的石头；megalith 可以是更大结构的构件。"},{"word":"dolmen","ipa":"/ˈdɒlmen/","tag":"a stone table tomb","definition":"A chamber tomb of upright stones capped by a slab; it is built from megaliths.","definitionCN":"由竖石撑起盖石的室墓；它由多块巨石建成。"},{"word":"monolith","ipa":"/ˈmɒnəlɪθ/","tag":"one single stone","definition":"A single large block or a monument cut from one stone; it stresses unity, not prehistoric date.","definitionCN":"单一大块石或由整石凿成的纪念物；强调整体性，而非史前年代。"},{"word":"megalithic","ipa":"/ˌmeɡəˈlɪθɪk/","tag":"the adjective","definition":"Describing a structure or culture that uses megaliths; the noun names one stone.","definitionCN":"描述使用巨石的建筑或文化；名词指一块巨石。"}]},{"heading":"NEAR MEANING","entries":[{"word":"boulder","ipa":"/ˈbəʊldə/","tag":"a large natural rock","definition":"A large rock shaped by nature; a megalith is chosen and placed by people.","definitionCN":"天然形成的大岩石；megalith 是人选并安放的。"},{"word":"slab","ipa":"/slæb/","tag":"a flat thick piece","definition":"A flat thick piece of stone or other material; a megalith may be a slab but is defined by size and use.","definitionCN":"石头或其他材料的厚平板；megalith 可以是石板，但以大小与用途界定。"},{"word":"monument","ipa":"/ˈmɒnjumənt/","tag":"a memorial structure","definition":"A built memorial; a megalith may be one stone within such a structure.","definitionCN":"建成的纪念物；megalith 可以是这类结构中的一块石。"},{"word":"colossus","ipa":"/kəˈlɒsəs/","tag":"a huge statue","definition":"A gigantic figure or thing; it stresses overwhelming size rather than stone construction.","definitionCN":"巨大的雕像或事物；强调压倒性的尺寸，而非石构。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: the two Greek roots, the archaeological class and the real monument types.","cn":"正常联想：两个希腊词根、考古类别与真实的遗迹类型。"},"normal":[{"en":"megas is 'great' and lithos is 'stone': a megalith is literally a great stone.","cn":"megas 是「巨大」，lithos 是「石头」：megalith 字面就是大石。"},{"en":"A menhir is one standing megalith; a dolmen is a tomb built of several.","cn":"独石是一块竖立的巨石；石棚由数块巨石建成。"},{"en":"Stone circles arrange many megaliths in a ring.","cn":"石圈把许多巨石排成一环。"},{"en":"Megalithic is the adjective, megalith the countable noun.","cn":"megalithic 是形容词，megalith 是可数名词。"},{"en":"The word belongs to archaeology, not to geology.","cn":"这个词属于考古学，而非地质学。"}],"abstract":[{"en":"A megalith is a stone that people lifted before they had machines.","cn":"巨石是人们在有机器之前就抬起来的石头。"},{"en":"It is a decision made permanent in rock.","cn":"它是用岩石做成永久的决定。"},{"en":"A field of megaliths is a conversation with people who left no other voice.","cn":"一片巨石群，是与没留下其他声音的人进行的一场对话。"}]},"examples":[{"en":"The megaliths were moved into place without metal tools.","cn":"这些巨石在没有金属工具的情况下被安放到位。"},{"en":"Each megalith in the tomb was cut from local granite.","cn":"墓中的每块巨石都取自当地花岗岩。"},{"en":"The survey maps every megalith along the ridge.","cn":"这次调查标出了山脊沿线的每块巨石。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「mega（大）+ lith（石）」——大石头 → 巨石","word":"megalith"},"root":"希腊 megas「巨大」+ lithos「石头」→ 近代英语复合词 megalith，由十九世纪考古学用于史前建筑的大块粗石；不是希腊语原有整词。","sensesIntro":{"en":"Eight senses keep one oversized stone: a building block, a standing stone, a tomb slab, a circle element, an archaeological class, an ancient wall block, a stubborn obstacle and a cultural symbol.","cn":"八个义项守着同一块超大石头：建筑构件、竖石、墓板、石圈元素、考古类别、古墙石块、顽固障碍与文化象征。"},"semanticMap":{"core":{"en":"CORE IMAGE: a rough block taller than a person, set upright in open ground by hands that had no machines.","cn":"核心意象：一块比人还高的粗石，被没有机器的手竖在空地上。"},"chain":["GREAT STONE","STANDING STONE","TOMB SLAB","STONE CIRCLE","ANCIENT WALL","CULTURAL SYMBOL"],"branches":[{"senses":"义项 01、义项 06","en":"BIG BLOCK: a prehistoric element and an ancient wall stone are the same oversized unit in different buildings.","cn":"大石块：史前构件与古墙石块是不同建筑中的同一超大单位。"},{"senses":"义项 02、义项 03","en":"UPRIGHT AND ROOF: a lone standing stone and a tomb slab are the vertical and horizontal uses of one block.","cn":"竖与横：独石与墓板是同一块石的竖用与横用。"},{"senses":"义项 04、义项 05","en":"ARRANGEMENT AND CLASS: a circle element and an archaeological category place the stone in a pattern and in a science.","cn":"排列与类别：石圈元素与考古类别把石头放进图案与学科。"},{"senses":"义项 07","en":"IMMOVABLE WEIGHT: a stubborn rule borrows the stone's inability to be shifted.","cn":"不可移的重量：顽固规定借用了石头挪不动的特性。"},{"senses":"义项 08","en":"PREHISTORY'S SIGN: the stone becomes a shorthand for an entire stone-building culture.","cn":"史前的符号：石头成为一个整套筑石文化的简称。"}]},"affixes":{"intro":{"en":"Megalith is a scientific compound whose two Greek parts also build several English words.","cn":"megalith 是科学复合词，它的两个希腊成分还构成若干英语词。"},"latinIntro":{"en":"Latin borrowed Greek megas as magnus in meaning, and Greek lithos as lapis in meaning; the compound itself is modern English, so Latin has no direct equivalent.","cn":"拉丁语在意义上以 magnus 对应希腊 megas，以 lapis 对应希腊 lithos；复合词本身是近代英语，因此拉丁语没有直接对应形式。"},"items":[{"word":"megas","structure":"megas (Greek adjective)","meaning":"great, large","meaningCN":"巨大","example":"The first root names size.","exampleCN":"第一个词根命名大小。"},{"word":"lithos","structure":"lithos (Greek noun)","meaning":"stone","meaningCN":"石头","example":"The second root names the material.","exampleCN":"第二个词根命名材料。"},{"word":"megalith","structure":"megas + lithos","meaning":"a great stone","meaningCN":"巨石","example":"The compound names one large block.","exampleCN":"复合词指一块大石。"},{"word":"megalithic","structure":"megalith + -ic","meaning":"of great stones","meaningCN":"巨石的","example":"The adjective describes the monuments.","exampleCN":"形容词描述这类遗迹。"},{"word":"megalithism","structure":"megalith + -ism","meaning":"the tradition of building with megaliths","meaningCN":"巨石建筑传统","example":"Megalithism spread along the Atlantic coast.","exampleCN":"巨石建筑传统沿大西洋海岸传播。"},{"word":"monolith","structure":"monos 'one' + lithos","meaning":"a single stone","meaningCN":"独石","example":"A monolith is one block, not a class of monuments.","exampleCN":"独石是一整块石，不是一类遗迹。"},{"word":"lithograph","structure":"lithos + graphein 'write'","meaning":"a stone-based printing process","meaningCN":"石版印刷","example":"Lithography uses a stone surface.","exampleCN":"石版印刷使用石面。"},{"word":"megalosaurus","structure":"megas + sauros 'lizard'","meaning":"a large fossil reptile","meaningCN":"斑龙","example":"The dinosaur name uses the same size root.","exampleCN":"恐龙名使用同一个「大」词根。"}],"latinEntries":[],"derivatives":[{"word":"megalithic","pos":"adj.","zh":"megalith + -ic（形容词后缀）→ 巨石的"},{"word":"megalithism","pos":"n.","zh":"megalith + -ism（体系后缀）→ 巨石建筑传统"},{"word":"megalithist","pos":"n.","zh":"megalith + -ist（研究者后缀）→ 巨石文化研究者"},{"word":"monolith","pos":"n.","zh":"monos「一」+ lithos「石」→ 独石；整块巨石"},{"word":"megalosaurus","pos":"n.","zh":"megas「大」+ sauros「蜥蜴」→ 斑龙"}]}},{"word":"megalithic","ipa_uk":"/ˌmeɡəˈlɪθɪk/","ipa_us":"/ˌmeɡəˈlɪθɪk/","definition_zh":"巨石的；用巨石建造的；巨石文化时代的；规模巨大而粗犷的","definition_en":"relating to megaliths; built of large stones; belonging to a megalith-using culture; massive in style","core_image":"游客走进由巨石围成的圆形遗迹，头顶的盖石像一块压下来的天花板","scene":"游客走进由巨石围成的圆形遗迹。The megalithic tomb was built from slabs weighing several tons.","sceneCN":"这里 megalithic 指「用巨石建造的」（第 2 个义项：以巨石为建材）；句意为这座巨石墓由数吨重的石板建成。","pos":[{"tag":"adj.","zh":"巨石的；巨石建筑的；巨石文化时代的；粗犷巨大的"}],"collocations":[{"phrase":"megalithic tomb","zh":"巨石墓"},{"phrase":"megalithic monument","zh":"巨石纪念建筑"},{"phrase":"megalithic culture","zh":"巨石文化"},{"phrase":"megalithic structure","zh":"巨石结构"},{"phrase":"megalithic period","zh":"巨石时代"}],"forms":[{"label":"原级","form":"megalithic"},{"label":"比较级","form":"more megalithic"},{"label":"最高级","form":"most megalithic"},{"label":"名词（巨石）","form":"megalith"},{"label":"名词（巨石传统）","form":"megalithism"},{"label":"副词（罕用）","form":"megalithically"}],"derivatives":[{"word":"megalith","pos":"n.","zh":"megalithic 去掉 -ic → 巨石；史前大石块"},{"word":"megalithism","pos":"n.","zh":"megalith + -ism（体系后缀）→ 巨石建筑传统"},{"word":"megalithist","pos":"n.","zh":"megalith + -ist（研究者后缀）→ 巨石文化研究者"},{"word":"megalithically","pos":"adv.","zh":"megalithic + -ally（副词后缀）→ 以巨石方式（罕用）"},{"word":"non-megalithic","pos":"adj.","zh":"否定前缀 + megalithic → 非巨石的"}],"senses":[{"no":"01","title":"Relating to megaliths","titleCN":"与巨石有关的","definition":"connected with the large rough stones used in prehistoric monuments","definitionCN":"与史前纪念建筑中使用的大块粗石有关的","example":"The museum labels each megalithic block by its quarry source.","exampleCN":"博物馆按采石来源给每块巨石标注。","why":"the adjective simply adds -ic to megalith, so its first job is to point back at the stones.","whyCN":"这个形容词只是给 megalith 加 -ic，因此首要职能是回指那些石头。"},{"no":"02","title":"Built of large stones","titleCN":"用巨石建造的","definition":"constructed from massive stone slabs or blocks rather than small masonry","definitionCN":"由巨大石板或石块而非小砖石建成的","example":"The megalithic tomb was built from slabs weighing several tons.","exampleCN":"这座巨石墓由数吨重的石板建成。","why":"construction is the purpose of most megaliths, so the adjective naturally describes the building method.","whyCN":"建造是多数巨石的用途，因此形容词自然描述营造方式。"},{"no":"03","title":"Of a megalith-using culture","titleCN":"属于使用巨石的文化的","definition":"belonging to a society that raised large stone monuments as part of its ritual life","definitionCN":"属于把大型石构纪念物纳入仪式生活的社会","example":"Megalithic communities along the coast shared burial customs.","exampleCN":"沿海的巨石文化社群共享墓葬习俗。","why":"the stones survive while the people do not, so the adjective comes to name the culture through its monuments.","whyCN":"石头留存而人已消失，因此形容词通过遗迹来命名那个文化。"},{"no":"04","title":"Of the Neolithic or Bronze Age","titleCN":"新石器或青铜时代的","definition":"dated to the long period when such monuments were built, roughly the Neolithic and early Bronze Age","definitionCN":"属于建造这类遗迹的漫长时期，约当新石器时代与青铜时代早期","example":"The megalithic layers at the site date to the late Neolithic.","exampleCN":"该遗址的巨石文化层可定到新石器时代晚期。","why":"dating links the adjective to a period, so megalithic also works as a chronological label.","whyCN":"断代把这个形容词与一个时期连起来，因此 megalithic 也作年代标签。"},{"no":"05","title":"Massive and rough in style","titleCN":"风格粗大而粗犷的","definition":"used for art or architecture that is deliberately blocky, heavy and rough","definitionCN":"用于刻意块状、厚重、粗犷的艺术或建筑","example":"The sculptor's megalithic forms look quarried rather than carved.","exampleCN":"这位雕塑家的巨石式造型看起来像采出来的，而非雕出来的。","why":"blocky, quarried-looking forms borrow the stone's heaviness for art.","whyCN":"块状、像采石成果的造型，为艺术借用了石头的沉重感。"},{"no":"06","title":"Enormous in scale","titleCN":"规模巨大的","definition":"figuratively very large, heavy or slow-moving","definitionCN":"比喻极大、沉重或行动缓慢","example":"The reform was a megalithic project that took a generation.","exampleCN":"这项改革是一个耗掉一代人的巨大工程。","why":"a project on the scale of a monument takes the size sense figuratively.","whyCN":"大到像纪念建筑一样的工程，以比喻方式承接了「尺寸」义。"},{"no":"07","title":"Cyclopean in construction","titleCN":"像独眼巨人式砌筑的","definition":"built of huge irregular blocks fitted without mortar, a style once attributed to giants","definitionCN":"用巨大不规则石块不用灰浆砌成，这种风格曾被归为巨人所建","example":"The wall's megalithic masonry needs no mortar to stand.","exampleCN":"这堵墙的巨石砌法不用灰浆也能立住。","why":"huge fitted blocks without mortar describe a distinct masonry technique.","whyCN":"不用灰浆拼合的巨大石块，描述了一种独特的砌筑技术。"},{"no":"08","title":"Relating to megalithic monuments as a class","titleCN":"与作为一类的巨石遗迹有关的","definition":"belonging to the archaeological category of megalithic monuments","definitionCN":"属于巨石纪念建筑这一考古类别","example":"Every megalithic site in the region is protected by law.","exampleCN":"该地区的每一处巨石遗迹都受法律保护。","why":"heritage law turns the adjective into a category of protected monument.","whyCN":"遗产法把这个形容词变成一类受保护的纪念物。"}],"etymology":{"intro":{"en":"Megalithic is megalith plus the adjective suffix -ic. It describes the stones, the buildings made from them, the cultures that raised them and, by extension, anything huge and blocky.","cn":"megalithic 是 megalith 加形容词后缀 -ic，描述巨石、用巨石建成的建筑、建造它们的文化，并引申描述任何巨大而块状的东西。"},"items":[{"era":"GREEK MEGAS","en":"Megas supplied 'great' in the parent noun megalith.","cn":"megas 在母词 megalith 中提供「巨大」。"},{"era":"GREEK LITHOS","en":"Lithos supplied 'stone', the material the monuments are made from.","cn":"lithos 提供「石头」，即遗迹的材料。"},{"era":"ENGLISH MEGALITH","en":"The nineteenth-century compound megalith named one large block.","cn":"十九世纪复合词 megalith 命名一块大石。"},{"era":"ADJECTIVE -IC","en":"The suffix -ic turned the noun into a describing word for monuments and cultures.","cn":"后缀 -ic 把这个名词变成描述遗迹与文化的形容词。"},{"era":"ARCHAEOLOGICAL SPREAD","en":"The adjective now labels a whole period, a building style and a class of protected sites.","cn":"这个形容词如今标出一个时期、一种建筑风格与一类受保护遗址。"}]},"similar":{"note":{"en":"Group one holds adjectives and nouns of stone building easily confused with megalithic; group two holds words for great size.","cn":"第一组是容易与 megalithic 混淆的石构形容词与名词；第二组是表示巨大尺度的词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"megalith","ipa":"/ˈmeɡəlɪθ/","tag":"the noun","definition":"A single large stone; megalithic is the adjective describing it or a structure made from it.","definitionCN":"单块大石；megalithic 是描述它或由其建成结构的形容词。"},{"word":"monolithic","ipa":"/ˌmɒnəˈlɪθɪk/","tag":"cut from one stone","definition":"Made from a single block, or figuratively rigid and uniform; it stresses unity, not prehistoric date.","definitionCN":"由一整块石制成，或比喻僵化统一；强调整体性，而非史前年代。"},{"word":"neolithic","ipa":"/ˌniːəˈlɪθɪk/","tag":"the New Stone Age","definition":"Of the later Stone Age; many megalithic monuments are Neolithic, but the words answer different questions.","definitionCN":"属于新石器时代；许多巨石遗迹是新石器的，但两词回答的问题不同。"},{"word":"palaeolithic","ipa":"/ˌpæliəˈlɪθɪk/","tag":"the Old Stone Age","definition":"Of the earlier Stone Age, before farming and before most megaliths.","definitionCN":"属于旧石器时代，在农业与多数巨石之前。"}]},{"heading":"NEAR MEANING","entries":[{"word":"monumental","ipa":"/məˈnjuːməntl/","tag":"huge or memorial","definition":"Very large or serving as a memorial; megalithic specifically names stone-built prehistoric work.","definitionCN":"巨大或起纪念作用；megalithic 特指史前石构作品。"},{"word":"colossal","ipa":"/kəˈlɒsl/","tag":"extremely large","definition":"Extremely large in size; it lacks the archaeological and stone-building reference.","definitionCN":"尺寸极大；不含考古与石构指向。"},{"word":"cyclopean","ipa":"/ˌsaɪkləˈpiːən/","tag":"giant-block masonry","definition":"Built of huge irregular blocks, a synonym for one kind of megalithic wall.","definitionCN":"用巨大不规则石块建成，是某类巨石墙的同义说法。"},{"word":"primitive","ipa":"/ˈprɪmətɪv/","tag":"early and simple","definition":"Belonging to an early stage; it is a value judgement, while megalithic is a technical description.","definitionCN":"属于早期阶段；含价值判断，而 megalithic 是技术描述。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: the two Greek roots, the archaeological period and the real building style.","cn":"正常联想：两个希腊词根、考古时期与真实建筑风格。"},"normal":[{"en":"megalith plus -ic: the adjective of the great stone.","cn":"megalith 加 -ic：大石的形容词。"},{"en":"Megalithic tombs, circles and walls are the three common monument types.","cn":"巨石墓、石圈与石墙是三类常见遗迹。"},{"en":"Megalithic masonry fits huge blocks without mortar.","cn":"巨石砌法不用灰浆就能拼合大石块。"},{"en":"The adjective can describe a culture, not only a building.","cn":"这个形容词不只描述建筑，也能描述文化。"},{"en":"Cyclopean is the old name for one style of megalithic wall.","cn":"cyclopean 是某类巨石墙的旧称。"}],"abstract":[{"en":"Megalithic is the adjective of a world built by lifting, not carving.","cn":"megalithic 是一个靠抬举而非雕刻建成的世界的形容词。"},{"en":"It is size turned into a style.","cn":"它是把尺寸变成风格。"},{"en":"A megalithic wall is a promise that the ground will not move.","cn":"巨石墙是一句「地面不会移动」的承诺。"}]},"examples":[{"en":"The megalithic circle is older than the nearby Roman road.","cn":"这座巨石圈比附近的罗马大道更古老。"},{"en":"Megalithic builders moved the slabs on rollers and levers.","cn":"巨石建造者用滚木与杠杆搬运石板。"},{"en":"The site is important for the study of megalithic culture.","cn":"该遗址对研究巨石文化很重要。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「mega（大）+ lith（石）+ ic」——像巨石一样 → 巨石的、巨大的","word":"megalithic"},"root":"megalith（希腊 megas「巨大」+ lithos「石头」）加形容词后缀 -ic → megalithic；描述巨石、石构建筑、巨石文化，并引申为「巨大而粗犷」。","sensesIntro":{"en":"Eight senses grow from the stone itself to the building method, the culture, the period, the style, the scale, the masonry and the protected site class.","cn":"八个义项从石头本身长到建造方式、文化、时期、风格、尺度、砌法与受保护遗址类别。"},"semanticMap":{"core":{"en":"CORE IMAGE: enormous rough slabs fitted together into a doorway that has stood for thousands of years.","cn":"核心意象：巨大的粗石板拼成一道已立数千年的门。"},"chain":["OF GREAT STONES","BUILT OF SLABS","STONE-RAISING CULTURE","NEOLITHIC DATE","BLOCKY STYLE","HUGE SCALE"],"branches":[{"senses":"义项 01、义项 08","en":"STONE AND SITE CLASS: one block and a protected category are the same material seen as unit and as heritage.","cn":"石块与遗址类别：单块石与受保护类别是同一材料在单位与遗产两面。"},{"senses":"义项 02、义项 07","en":"BUILDING METHODS: slab-built tombs and mortarless walls are two ways of fitting great stones.","cn":"建造方式：石板墓与无浆石墙是拼合巨石的两种做法。"},{"senses":"义项 03、义项 04","en":"CULTURE AND PERIOD: the people and their age are named through the monuments they left.","cn":"文化与时期：人与时代都通过他们留下的遗迹被命名。"},{"senses":"义项 05","en":"BLOCKY STYLE: art borrows the heaviness of stone for its own forms.","cn":"块状风格：艺术为自己的造型借用石头的沉重感。"},{"senses":"义项 06","en":"GREAT SCALE: a huge project borrows the adjective's sense of size.","cn":"巨大尺度：庞大工程借用了这个形容词的尺寸义。"}]},"affixes":{"intro":{"en":"Megalithic is a Greek-rooted scientific adjective, and its endings also build abstract and adverbial forms.","cn":"megalithic 是希腊词根的科学形容词，其词尾还构成抽象与副词形式。"},"latinIntro":{"en":"The Greek suffix -ikos became Latin -icus and English -ic; the compound itself is modern, not Latin.","cn":"希腊后缀 -ikos 变成拉丁 -icus 与英语 -ic；复合词本身是近代产物，并非拉丁语。"},"items":[{"word":"megas","structure":"megas (Greek adjective)","meaning":"great","meaningCN":"巨大","example":"The first root names size.","exampleCN":"第一个词根命名大小。"},{"word":"lithos","structure":"lithos (Greek noun)","meaning":"stone","meaningCN":"石头","example":"The second root names material.","exampleCN":"第二个词根命名材料。"},{"word":"megalith","structure":"megas + lithos","meaning":"a great stone","meaningCN":"巨石","example":"The noun names one block.","exampleCN":"名词指一块大石。"},{"word":"-ic","structure":"-ikos / -icus (adjectival suffix)","meaning":"relating to","meaningCN":"与……有关的","example":"The suffix makes the adjective.","exampleCN":"这个后缀构成形容词。"},{"word":"megalithic","structure":"megalith + -ic","meaning":"of great stones","meaningCN":"巨石的","example":"The tomb is megalithic.","exampleCN":"这座墓是巨石建的。"},{"word":"megalithism","structure":"megalith + -ism","meaning":"the megalith-building tradition","meaningCN":"巨石建筑传统","example":"Megalithism is studied across regions.","exampleCN":"巨石传统被跨地区研究。"},{"word":"megalithist","structure":"megalith + -ist","meaning":"a student of megaliths","meaningCN":"巨石研究者","example":"The megalithist surveyed the ridge.","exampleCN":"这位巨石研究者勘察了山脊。"},{"word":"monolithic","structure":"monos 'one' + lithos + -ic","meaning":"made of one stone","meaningCN":"整块石的；僵化的","example":"A monolithic column is cut from one block.","exampleCN":"整石柱由一块石凿成。"}],"latinEntries":[],"derivatives":[{"word":"megalith","pos":"n.","zh":"megalithic 去掉 -ic → 巨石"},{"word":"megalithism","pos":"n.","zh":"megalith + -ism（体系后缀）→ 巨石建筑传统"},{"word":"megalithist","pos":"n.","zh":"megalith + -ist（研究者后缀）→ 巨石文化研究者"},{"word":"megalithically","pos":"adv.","zh":"megalithic + -ally（副词后缀）→ 以巨石方式（罕用）"},{"word":"non-megalithic","pos":"adj.","zh":"否定前缀 + megalithic → 非巨石的"}]}},{"word":"burial mound","ipa_uk":"/ˈberiəl maʊnd/","ipa_us":"/ˈberiəl maʊnd/","definition_zh":"坟丘；封土堆；古墓冢；史前墓葬的土丘","definition_en":"a mound of earth raised over a grave; a barrow or tumulus, especially a prehistoric one","core_image":"草坡上鼓起一个圆丘，顶上长着一棵孤树，四周的草色比别处深","scene":"草坡上鼓起一个圆丘，顶上长着一棵孤树。A low burial mound marks the grave of a tribal leader.","sceneCN":"这里 burial mound 指「覆盖墓葬而堆起的土丘」（第 1 个义项：坟丘）；句意为一座低矮的坟丘标出部落首领的墓。","pos":[{"tag":"n.","zh":"坟丘；封土堆；古墓冢"}],"collocations":[{"phrase":"prehistoric burial mound","zh":"史前坟丘"},{"phrase":"burial mound site","zh":"坟丘遗址"},{"phrase":"low burial mound","zh":"低矮坟丘"},{"phrase":"burial mound cemetery","zh":"坟丘墓地"},{"phrase":"raise a burial mound","zh":"堆起坟丘"}],"forms":[{"label":"单数","form":"burial mound"},{"label":"复数","form":"burial mounds"},{"label":"同义名词（英式）","form":"barrow"},{"label":"同义名词（拉丁式）","form":"tumulus"},{"label":"复数（拉丁式）","form":"tumuli"},{"label":"限定成分","form":"burial"}],"derivatives":[{"word":"burial","pos":"n.","zh":"古英语 byrgels「埋葬」→ 埋葬；葬礼"},{"word":"bury","pos":"v.","zh":"古英语 byrgan「埋」→ 埋葬；掩埋"},{"word":"mound","pos":"n.","zh":"古英语 mund「保护、手」→ 土丘；堆"},{"word":"barrow","pos":"n.","zh":"古英语 beorg「山丘」→ 坟丘（英式）"},{"word":"tumulus","pos":"n.","zh":"拉丁 tumulus「土堆」→ 古墓冢（学术语）"}],"senses":[{"no":"01","title":"A mound of earth over a grave","titleCN":"覆盖墓葬的土丘","definition":"a heap of earth raised over a grave, often marking the burial place","definitionCN":"在墓上堆起的土，常用来标示埋葬地点","example":"A low burial mound marks the grave of a tribal leader.","exampleCN":"一座低矮的坟丘标出部落首领的墓。","why":"burial names the purpose and mound names the shape, so the phrase is a direct description.","whyCN":"burial 指用途，mound 指形状，因此短语是直接描述。"},{"no":"02","title":"A barrow or tumulus","titleCN":"坟丘（barrow 或 tumulus）","definition":"the same structure under older English or Latin names used in archaeology","definitionCN":"同一结构在考古学中使用的英语旧称或拉丁名称","example":"The barrow on the ridge is the largest burial mound in the county.","exampleCN":"山脊上的坟丘是本郡最大的墓葬土丘。","why":"English and Latin synonyms name the same structure, which is why the phrase has several equivalents.","whyCN":"英语与拉丁同义词命名同一结构，因此这个短语有几个对应说法。"},{"no":"03","title":"A visible grave marker in the landscape","titleCN":"地貌中可见的墓葬标志","definition":"a raised shape in the landscape that shows where someone was buried","definitionCN":"地貌中隆起的形状，显示某人被葬于何处","example":"From the air the burial mound looks like a dark circle in the field.","exampleCN":"从空中看，坟丘像田野里的一个深色圆圈。","why":"a raised shape is visible from a distance, so the mound works as a landscape marker.","whyCN":"隆起的形状从远处可见，因此坟丘充当景观标记。"},{"no":"04","title":"An archaeological site","titleCN":"考古遗址","definition":"a mound investigated by archaeologists for its graves and grave goods","definitionCN":"考古学家为研究墓葬与随葬品而发掘的土丘","example":"The burial mound was excavated in layers over three seasons.","exampleCN":"这座坟丘分三层、历经三个季度被发掘。","why":"excavation turns the mound from a landscape feature into a site with layers and records.","whyCN":"发掘把坟丘从景观特征变成有地层与记录的地点。"},{"no":"05","title":"A communal burial place","titleCN":"集体墓葬","definition":"a mound covering several burials rather than a single grave","definitionCN":"覆盖多座墓葬而非单一墓穴的土丘","example":"The burial mound held forty individuals from one community.","exampleCN":"这座坟丘葬有同一社群的四十个人。","why":"a shared grave makes the mound a collective rather than individual memorial.","whyCN":"集体墓让土丘成为群体而非个人的纪念物。"},{"no":"06","title":"A mound containing grave goods","titleCN":"含随葬品的坟丘","definition":"a mound whose burials include pottery, tools, weapons or ornaments","definitionCN":"墓葬中含有陶器、工具、武器或饰品的土丘","example":"The burial mound yielded a bronze dagger and two pots.","exampleCN":"这座坟丘出土了一把青铜匕首和两件陶罐。","why":"grave goods are the objects that make a mound archaeologically valuable.","whyCN":"随葬品正是让坟丘具有考古价值的物件。"},{"no":"07","title":"A prehistoric cemetery feature","titleCN":"史前墓地特征","definition":"a mound built as part of a prehistoric funerary landscape","definitionCN":"作为史前墓葬景观一部分而建起的土丘","example":"The burial mound belongs to a wider prehistoric cemetery.","exampleCN":"这座坟丘属于一片更大的史前墓地。","why":"a single mound sits inside a funerary landscape, giving the phrase its prehistoric setting.","whyCN":"单座土丘位于一片墓葬景观之中，赋予短语史前语境。"},{"no":"08","title":"A metaphor for a buried past","titleCN":"被掩埋过去的隐喻","definition":"an image for something important that has been covered over and half forgotten","definitionCN":"比喻被覆盖、半被遗忘却仍重要的事物","example":"The old scandal lay under the town like a burial mound.","exampleCN":"那桩旧丑闻像坟丘一样压在镇子底下。","why":"a covered scandal borrows the image of something buried but still present.","whyCN":"被掩盖的丑闻借用了「被埋却仍在」的形象。"}],"etymology":{"intro":{"en":"Burial mound joins two native English words. Burial comes from Old English byrgels, and mound goes back to Old English mund, whose sense shifted from protection to a heap or raised earth.","cn":"burial mound 由两个英语本族词组成。burial 来自古英语 byrgels，mound 上溯古英语 mund，其词义从「保护」转为「堆、隆起的土」。"},"items":[{"era":"OLD ENGLISH BYRGAN","en":"Byrgan meant 'to bury', the verb behind burial.","cn":"byrgan 意为「埋葬」，是 burial 背后的动词。"},{"era":"OLD ENGLISH BYRGELS","en":"Byrgels meant a burial or a tomb, the direct ancestor of burial.","cn":"byrgels 意为「埋葬、坟墓」，是 burial 的直接祖先。"},{"era":"OLD ENGLISH MUND","en":"Mund meant 'hand, protection, guardian'; the modern 'heap' sense developed later and its exact path is uncertain.","cn":"mund 意为「手、保护、守护」；现代「堆」义出现较晚，其确切演变路径不确定。"},{"era":"MIDDLE ENGLISH MOUND","en":"By the sixteenth century mound commonly meant a heap or a small hill, including earth raised over a grave.","cn":"到十六世纪，mound 通常指堆或小丘，包括墓上隆起的土。"},{"era":"ARCHAEOLOGICAL PHRASE","en":"Archaeologists paired burial with mound to name barrows and tumuli in a neutral technical way.","cn":"考古学家把 burial 与 mound 配在一起，以中性的技术方式命名坟丘与古墓冢。"},{"era":"SOURCE UNCERTAIN","en":"Source uncertain (the 'heap' sense only): the route from 'protection' to 'raised earth' in mound is not fully documented, though both halves of the phrase are old words.","cn":"来源不确定（仅「堆」义）：mound 从「保护」到「隆起土堆」的演变路径没有完整记录，但短语两半都是古词。"}]},"similar":{"note":{"en":"Group one holds burial structures easily confused with a mound; group two holds words for heaps and graves.","cn":"第一组是容易与坟丘混淆的墓葬结构；第二组是表示土堆与坟墓的词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"barrow","ipa":"/ˈbærəʊ/","tag":"an English mound tomb","definition":"An Old English word for a burial mound, especially in Britain; it is the native synonym.","definitionCN":"英语本族的坟丘词，尤用于英国；是本族同义词。"},{"word":"tumulus","ipa":"/ˈtjuːmjələs/","tag":"a Latin mound tomb","definition":"The Latin-based term for a burial mound, common in archaeology and art history.","definitionCN":"源自拉丁的坟丘术语，常用于考古学与艺术史。"},{"word":"cairn","ipa":"/keən/","tag":"a stone heap","definition":"A heap of stones raised as a marker or memorial, often over a grave; it is stone, not earth.","definitionCN":"作为标记或纪念而堆起的石堆，常覆于墓上；材料是石而非土。"},{"word":"grave","ipa":"/ɡreɪv/","tag":"the burial place itself","definition":"The pit or place where a body is buried; a burial mound is the raised earth above it.","definitionCN":"埋葬遗体的坑或地点；坟丘是其上隆起的土。"}]},{"heading":"NEAR MEANING","entries":[{"word":"tomb","ipa":"/tuːm/","tag":"a burial structure","definition":"A grave chamber or monument for the dead; a mound may cover a tomb.","definitionCN":"死者的墓室或纪念建筑；坟丘可覆盖墓室。"},{"word":"cemetery","ipa":"/ˈsemətri/","tag":"a burial ground","definition":"A place set aside for graves; a burial mound may be one feature within it.","definitionCN":"专用于墓葬的场地；坟丘可以是其中一处特征。"},{"word":"mound","ipa":"/maʊnd/","tag":"any raised heap","definition":"Any heap of earth or stones; burial mound adds the funerary purpose.","definitionCN":"任何土石堆；burial mound 增添了丧葬用途。"},{"word":"hill","ipa":"/hɪl/","tag":"a natural rise","definition":"A natural raised landform; a burial mound is built by people, even when it looks like a small hill.","definitionCN":"天然隆起的地形；坟丘由人建造，即便看起来像小丘。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: the two Old English words, the archaeological synonyms and the real grave goods.","cn":"正常联想：两个古英语词、考古同义词与真实的随葬品。"},"normal":[{"en":"burial is Old English byrgels, a tomb or burying.","cn":"burial 是古英语 byrgels，指坟墓或埋葬。"},{"en":"mound is Old English mund, whose sense shifted toward a heap.","cn":"mound 是古英语 mund，词义转向「堆」。"},{"en":"Barrow and tumulus are the English and Latin synonyms.","cn":"barrow 与 tumulus 是英语与拉丁语的同义词。"},{"en":"A cairn is the stone version of a burial mound.","cn":"cairn 是坟丘的石制版本。"},{"en":"Grave goods turn a mound into an archaeological site.","cn":"随葬品把坟丘变成考古遗址。"}],"abstract":[{"en":"A burial mound is a hill made by memory.","cn":"坟丘是一座由记忆堆成的小山。"},{"en":"It is the landscape keeping a name that the wind is eroding.","cn":"它是大地在守住一个正被风磨掉的名字。"},{"en":"Every mound is a sentence the dead left in earth.","cn":"每座坟丘都是死者留在泥土里的一句话。"}]},"examples":[{"en":"The burial mound was surrounded by a shallow ditch.","cn":"这座坟丘周围有一圈浅沟。"},{"en":"Excavators found a burial mound beneath the car park.","cn":"发掘者在停车场下面发现了一座坟丘。"},{"en":"The burial mound is older than the village church.","cn":"这座坟丘比村里的教堂更古老。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「burial（埋葬）+ mound（土堆）」——埋在土下、上面堆起 → 坟丘","word":"burial mound"},"root":"burial 来自古英语 byrgels「坟墓、埋葬」，mound 来自古英语 mund「保护、手」，后转指「堆、土丘」；短语为考古学用语，指覆盖墓葬的土丘。","sensesIntro":{"en":"Eight senses follow one heap of earth: a grave cover, its older names, a landscape mark, a dig site, a shared grave, a holder of grave goods, a prehistoric feature and a buried memory.","cn":"八个义项沿一堆土展开：墓上覆土、旧称、地貌标志、发掘遗址、集体墓、随葬品容器、史前特征与被掩埋的记忆。"},"semanticMap":{"core":{"en":"CORE IMAGE: a low grass-covered rise in a field, holding bodies and objects under its surface.","cn":"核心意象：田野里一个低矮的草丘，地表下藏着遗体与器物。"},"chain":["HEAP OF EARTH","GRAVE COVER","LANDSCAPE MARK","DIG SITE","COMMUNAL GRAVE","BURIED PAST"],"branches":[{"senses":"义项 01、义项 02","en":"EARTH AND NAME: the descriptive phrase and its older synonyms name the same heap in different vocabularies.","cn":"土与名：描述性短语与旧同义词用不同词汇命名同一土堆。"},{"senses":"义项 03、义项 07","en":"LANDSCAPE FEATURE: a visible rise and a prehistoric cemetery element place the mound in a wider setting.","cn":"地貌特征：可见隆起与史前墓地要素把坟丘放进更大的环境。"},{"senses":"义项 04、义项 06","en":"ARCHAEOLOGY: a dig site and a source of grave goods are the mound as evidence and as container.","cn":"考古：发掘遗址与随葬品来源是坟丘的证据面与容器面。"},{"senses":"义项 05","en":"SHARED GRAVE: a communal burial turns one mound into a group memory.","cn":"集体墓：集体埋葬把一座土丘变成群体记忆。"},{"senses":"义项 08","en":"BURIED PAST: a hidden scandal borrows the mound's image of something covered but still there.","cn":"被掩埋的过去：隐秘丑闻借用了坟丘「被盖住却仍在」的形象。"}]},"affixes":{"intro":{"en":"Burial mound is a two-word English phrase, both halves native, with Latin and Greek synonyms used in scholarship.","cn":"burial mound 是两词英语短语，两半都是本族词，学术界另有拉丁与希腊同义词。"},"latinIntro":{"en":"Latin tumulus supplies the scholarly synonym for a mound; the English phrase itself has no Latin ancestor.","cn":"拉丁 tumulus 提供「土丘」的学术同义词；英语短语本身没有拉丁祖先。"},"items":[{"word":"byrgan","structure":"byrgan (Old English verb)","meaning":"to bury","meaningCN":"埋葬","example":"The verb underlies burial.","exampleCN":"这个动词是 burial 的基础。"},{"word":"byrgels","structure":"byrgels (Old English noun)","meaning":"burial, tomb","meaningCN":"埋葬；坟墓","example":"The noun became burial.","exampleCN":"这个名词变成 burial。"},{"word":"mund","structure":"mund (Old English noun)","meaning":"hand, protection","meaningCN":"手；保护","example":"The old sense shifted toward a heap.","exampleCN":"旧义转向「堆」。"},{"word":"mound","structure":"mound (Modern English noun)","meaning":"a heap or small hill","meaningCN":"堆；小丘","example":"The mound rose above the field.","exampleCN":"土丘高过田野。"},{"word":"burial","structure":"byrgels + -al (noun suffix)","meaning":"the act or place of burying","meaningCN":"埋葬；墓地","example":"The burial took place at dawn.","exampleCN":"葬礼在黎明举行。"},{"word":"burial mound","structure":"burial + mound","meaning":"a grave heap","meaningCN":"坟丘","example":"The burial mound is protected.","exampleCN":"这座坟丘受保护。"},{"word":"barrow","structure":"beorg (Old English 'hill')","meaning":"a mound tomb","meaningCN":"坟丘","example":"A barrow stands on the ridge.","exampleCN":"山脊上有一座坟丘。"},{"word":"tumulus","structure":"tumulus, tumuli (Latin noun)","meaning":"a mound, a burial hill","meaningCN":"土丘；坟冢","example":"The tumulus dates to the Bronze Age.","exampleCN":"这座坟冢属青铜时代。"}],"latinEntries":[],"derivatives":[{"word":"burial","pos":"n.","zh":"古英语 byrgels「坟墓」+ -al（名词后缀）→ 埋葬；葬礼"},{"word":"bury","pos":"v.","zh":"古英语 byrgan「埋」→ 埋葬；掩埋"},{"word":"mound","pos":"n.","zh":"古英语 mund「保护」→ 土丘；堆"},{"word":"barrow","pos":"n.","zh":"古英语 beorg「山丘」→ 坟丘"},{"word":"tumulus","pos":"n.","zh":"拉丁 tumulus「土堆」→ 古墓冢"}]}},{"word":"excavation trench","ipa_uk":"/ˌekskəˈveɪʃn trentʃ/","ipa_us":"/ˌekskəˈveɪʃn trentʃ/","definition_zh":"探沟；考古发掘沟；为暴露地层而挖出的窄长沟槽","definition_en":"a long narrow cut dug to expose layers of soil or deposits, especially in archaeological work","core_image":"探方里挖出一条窄长的沟，沟壁平整，露出深浅不一的土层与碎石","scene":"探方里挖出一条窄长的沟，沟壁平整。The excavation trench exposed three layers of occupation debris.","sceneCN":"这里 excavation trench 指「考古发掘中挖出的窄长探沟」（第 2 个义项：考古发掘单元）；句意为这条探沟露出了三层人类活动堆积。","pos":[{"tag":"n.","zh":"探沟；考古发掘沟；开挖沟槽"}],"collocations":[{"phrase":"archaeological excavation trench","zh":"考古探沟"},{"phrase":"trial excavation trench","zh":"试掘探沟"},{"phrase":"deep excavation trench","zh":"深探沟"},{"phrase":"trench section","zh":"探沟剖面"},{"phrase":"dig an excavation trench","zh":"挖一条探沟"}],"forms":[{"label":"单数","form":"excavation trench"},{"label":"复数","form":"excavation trenches"},{"label":"限定成分","form":"excavation"},{"label":"核心名词","form":"trench"},{"label":"同义（试掘）","form":"test pit"},{"label":"相关（探方）","form":"excavation square"}],"derivatives":[{"word":"excavate","pos":"v.","zh":"拉丁 excavare「挖空」→ 发掘；挖出"},{"word":"excavation","pos":"n.","zh":"excavate + -ion（名词后缀）→ 发掘；挖掘"},{"word":"excavator","pos":"n.","zh":"excavate + -or（施事后缀）→ 发掘者；挖掘机"},{"word":"trench","pos":"n.","zh":"古法语 trenche「切出的沟」→ 沟；战壕"},{"word":"trencher","pos":"n.","zh":"trench + -er（施事后缀）→ 挖沟者；木餐盘（旧义）"}],"senses":[{"no":"01","title":"A long narrow cut to expose soil layers","titleCN":"为暴露土层而挖的窄长沟","definition":"a long narrow hole dug down through soil so that its layers can be seen","definitionCN":"向下挖穿土壤的长窄坑，以便观察各层","example":"The excavation trench exposed three layers of occupation debris.","exampleCN":"这条探沟露出了三层人类活动堆积。","why":"excavation names the digging out and trench names the long cut, so the phrase describes both the act and the shape.","whyCN":"excavation 指挖出，trench 指长形切口，因此短语同时描述动作与形状。"},{"no":"02","title":"An archaeological digging unit","titleCN":"考古发掘单元","definition":"a controlled unit of archaeological digging used to record stratigraphy","definitionCN":"用于记录地层关系的受控考古挖掘单位","example":"Each excavation trench is photographed before any soil is removed.","exampleCN":"每条探沟在取土前都要拍照。","why":"a controlled unit is what separates research digging from mere hole-making.","whyCN":"受控单位正是把研究性发掘与单纯挖坑区分开的东西。"},{"no":"03","title":"A test pit or trial trench","titleCN":"试掘探沟","definition":"a small trench dug first to test whether a site is worth full excavation","definitionCN":"为判断遗址是否值得全面发掘而先挖的小沟","example":"A trial excavation trench showed that the wall continued westward.","exampleCN":"一条试掘探沟显示这堵墙继续向西延伸。","why":"a trial cut is the smallest version of the method, used before committing to full excavation.","whyCN":"试掘沟是这套方法的最小版本，用于在全面发掘前试探。"},{"no":"04","title":"A section for stratigraphic recording","titleCN":"用于地层记录的剖面","definition":"the exposed vertical face of a trench, drawn and photographed as a stratigraphic section","definitionCN":"探沟露出的垂直面，作为地层剖面绘制并拍照","example":"The east face of the excavation trench shows a buried plough soil.","exampleCN":"探沟东壁显示出一层被埋的耕作土。","why":"the exposed face is what gets drawn and photographed, turning the cut into a record.","whyCN":"露出的壁面会被绘制与拍照，把切口变成记录。"},{"no":"05","title":"A drainage or foundation trench","titleCN":"排水或基础沟槽","definition":"a long cut dug for pipes, foundations or drainage rather than for research","definitionCN":"为管道、地基或排水而非研究挖出的长沟","example":"Workers dug an excavation trench for the new water main.","exampleCN":"工人为新供水主管挖了一条沟槽。","why":"the same shape serves engineering, so the phrase is not limited to archaeology.","whyCN":"同一形状也服务于工程，因此短语并不限于考古。"},{"no":"06","title":"A defensive trench","titleCN":"防御战壕","definition":"a long cut used as a barrier or protected position, as in military earthworks","definitionCN":"作为屏障或防护阵地的长沟，如军事土工作业","example":"The old excavation trench was later reused as a drainage channel.","exampleCN":"那条旧战壕后来被改作排水沟。","why":"a defensive ditch is another practical use of a long cut.","whyCN":"防御沟是长形切口的另一种实用。"},{"no":"07","title":"The open cut itself","titleCN":"挖开的沟体","definition":"the open void left by digging, including its sides and floor","definitionCN":"挖掘后留下的敞开的沟体，包括两侧与底面","example":"Rainwater collected at the bottom of the excavation trench.","exampleCN":"雨水积在探沟底部。","why":"the open void is the physical result of digging, distinct from its research purpose.","whyCN":"敞开的沟体是挖掘的物理结果，区别于其研究目的。"},{"no":"08","title":"A method of systematic excavation","titleCN":"系统性发掘方法","definition":"the technique of using narrow trenches to sample a large area efficiently","definitionCN":"用窄沟高效取样大面积的发掘技术","example":"The team used an excavation trench grid to map the whole field.","exampleCN":"团队用探沟网格测绘整片田野。","why":"a grid of narrow cuts samples a large area, which is the method sense.","whyCN":"用窄沟组成的网格对大区域取样，这就是「方法」义。"}],"etymology":{"intro":{"en":"Excavation trench joins a Latin verb meaning 'hollow out' to an Old French noun meaning 'a cut'. Excavare is ex- 'out' plus cavus 'hollow'; trenchier meant 'to cut', and its own deeper origin is uncertain.","cn":"excavation trench 把意为「挖空」的拉丁动词与意为「切出的沟」的古法语名词接在一起。excavare 是 ex-「向外」加 cavus「空腔」；trenchier 意为「切」，其更深来源不确定。"},"items":[{"era":"LATIN CAVUS","en":"Cavus meant 'hollow, a cavity', the image behind excavation.","cn":"cavus 意为「空的、空腔」，是 excavation 背后的意象。"},{"era":"LATIN EXCAVARE","en":"Ex- 'out' plus cavare 'to make hollow' produced excavare, 'to hollow out, dig out'.","cn":"ex-「向外」加 cavare「使空」构成 excavare，意为「挖空、挖出」。"},{"era":"OLD FRENCH TRENCHIER","en":"Trenchier meant 'to cut', and its noun trenche named a cut or a ditch; the deeper origin of the verb is uncertain.","cn":"trenchier 意为「切」，其名词 trenche 指切口或沟；这个动词的更早来源不确定。"},{"era":"ENGLISH TRENCH","en":"English trench first named a ditch or a cut in the ground, later a military defensive ditch.","cn":"英语 trench 最初指地上的沟或切口，后来指军事防御沟。"},{"era":"ARCHAEOLOGY 19TH CENTURY","en":"Excavation became the standard term for controlled digging, and the phrase excavation trench named its basic unit.","cn":"excavation 成为受控挖掘的标准术语，短语 excavation trench 命名其基本单位。"},{"era":"SOURCE UNCERTAIN","en":"Source uncertain (trench only): the pre-French origin of trenchier is not settled, and suggestions linking it to Latin truncare remain hypotheses.","cn":"来源不确定（仅 trench）：trenchier 在法语之前的来源未定，把它与拉丁 truncare 联系起来的说法仍属假说。"}]},"similar":{"note":{"en":"Group one holds digging units easily confused with an excavation trench; group two holds words for holes and cuts in the ground.","cn":"第一组是容易与探沟混淆的发掘单位；第二组是表示地面孔洞与切口的词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"test pit","ipa":"/ˈtest pɪt/","tag":"a small trial hole","definition":"A small pit dug to sample a site; a trench is long and narrow, a pit is compact.","definitionCN":"为取样遗址挖的小坑；trench 长而窄，pit 紧凑。"},{"word":"sondage","ipa":"/ˈsɒndɑːʒ/","tag":"a French trial cut","definition":"A small exploratory excavation in French archaeology; it is a kind of test trench.","definitionCN":"法国考古学中的小型试掘；是试掘探沟的一种。"},{"word":"excavation square","ipa":"/ˌekskəˈveɪʃn skweə/","tag":"a grid unit","definition":"A square unit of controlled digging; a trench is long rather than square.","definitionCN":"受控发掘的方形单位；trench 是长形而非方形。"},{"word":"shaft","ipa":"/ʃɑːft/","tag":"a vertical hole","definition":"A deep vertical cut or well-like hole; a trench is horizontal in extent.","definitionCN":"深的垂直切口或井状孔；trench 在延伸上是水平的。"}]},{"heading":"NEAR MEANING","entries":[{"word":"ditch","ipa":"/dɪtʃ/","tag":"a long cut in the ground","definition":"A long narrow channel, often for drainage or defence; an excavation trench is defined by its research purpose.","definitionCN":"长窄沟渠，常用于排水或防御；探沟以研究目的界定。"},{"word":"cutting","ipa":"/ˈkʌtɪŋ/","tag":"an open excavation","definition":"A open cut made for a road or railway; it is engineering, not archaeology.","definitionCN":"为道路或铁路挖开的切口；属工程，不是考古。"},{"word":"pit","ipa":"/pɪt/","tag":"a hole dug in the ground","definition":"A hole dug for burial, storage or testing; it is not long and narrow.","definitionCN":"为埋葬、储藏或测试挖的坑；不呈长窄形。"},{"word":"channel","ipa":"/ˈtʃænl/","tag":"a passage for water","definition":"A long passage cut or built for water; it stresses flow rather than exposure.","definitionCN":"为水挖成或建成的长通道；强调水流，而非暴露地层。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: the Latin hollow and the French cut, plus the real field method.","cn":"正常联想：拉丁「空腔」与法语「切」，以及真实的田野方法。"},"normal":[{"en":"excavare is ex- 'out' plus cavus 'hollow': to hollow out.","cn":"excavare 是 ex-「向外」加 cavus「空腔」：挖空。"},{"en":"trench comes from French trenchier, to cut.","cn":"trench 来自法语 trenchier「切」。"},{"en":"A trench is long and narrow; a pit is compact.","cn":"探沟长而窄；坑则紧凑。"},{"en":"The vertical face of a trench is drawn as a section.","cn":"探沟的垂直面被绘成剖面。"},{"en":"Trial trenches test a site before full excavation.","cn":"试掘探沟在全面发掘前测试遗址。"}],"abstract":[{"en":"An excavation trench is a thin cut that lets the ground speak in layers.","cn":"探沟是一道细切口，让大地按层说话。"},{"en":"It is a window made by removing the wall.","cn":"它是一扇靠拆掉墙才做成的窗。"},{"en":"The trench is temporary, but the section it records lasts in the archive.","cn":"探沟是临时的，但它记录的剖面在档案里长存。"}]},"examples":[{"en":"The excavation trench was backfilled at the end of the season.","cn":"探沟在季度结束时被回填。"},{"en":"A narrow excavation trench ran across the whole courtyard.","cn":"一条窄探沟横穿整个庭院。"},{"en":"The excavation trench revealed a floor of beaten earth.","cn":"这条探沟露出了一层夯土地面。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「excavation（发掘）+ trench（沟）」——考古挖出的长沟 → 探沟","word":"excavation trench"},"root":"excavation 来自拉丁 excavare「挖空」= ex-「向外」+ cavus「空腔」；trench 来自古法语 trenche「切出的沟」，动词 trenchier 更深来源不确定。短语指考古发掘的窄长探沟。","sensesIntro":{"en":"Eight senses follow one cut: exposed layers, an archaeological unit, a trial hole, a recorded section, a service ditch, a defensive ditch, the open void and a sampling method.","cn":"八个义项沿一道切口展开：露出的土层、考古单位、试掘孔、记录剖面、管线沟、防御沟、敞开的沟体与取样方法。"},"semanticMap":{"core":{"en":"CORE IMAGE: a narrow vertical slice through the ground, its wall showing stripes of old floors and ash.","cn":"核心意象：在地面上切出的一道窄而深的切口，壁面露出旧地面与灰烬的条纹。"},"chain":["NARROW CUT","LAYERS EXPOSED","ARCHAEOLOGICAL UNIT","RECORDED SECTION","SERVICE DITCH","SAMPLING METHOD"],"branches":[{"senses":"义项 01、义项 07","en":"CUT AND VOID: the act of exposing layers and the open hole it leaves are the same cut in process and result.","cn":"切与空：暴露土层的动作与留下的敞开沟体，是同一道切口的动作面与结果面。"},{"senses":"义项 02、义项 03","en":"RESEARCH UNITS: a controlled digging unit and a small trial cut are the same method at full and at test scale.","cn":"研究单位：受控发掘单位与小试掘沟，是同一方法在全面与试验尺度上。"},{"senses":"义项 04","en":"RECORDED FACE: the section turns a hole into a document.","cn":"被记录的壁面：剖面把坑洞变成文件。"},{"senses":"义项 05、义项 06","en":"OTHER CUTS: service and defensive ditches borrow the shape for practical ends.","cn":"其他沟：管线沟与防御沟为实用目的借用同一形状。"},{"senses":"义项 08","en":"METHOD: a grid of trenches samples a whole landscape.","cn":"方法：探沟网格对整个地貌取样。"}]},"affixes":{"intro":{"en":"Excavation trench is a two-word technical phrase, one Latin-derived and one French-derived, and each half has its own family.","cn":"excavation trench 是两词技术短语，一个源自拉丁，一个源自法语，每一半都有自己的词族。"},"latinIntro":{"en":"Latin cavus and excavare supply excavation; Old French trenche supplies trench, so the phrase has two separate ancestries.","cn":"拉丁 cavus 与 excavare 提供 excavation；古法语 trenche 提供 trench，因此短语有两条独立来源。"},"items":[{"word":"cavus","structure":"cavus (Latin adjective)","meaning":"hollow","meaningCN":"空的；空腔的","example":"The root supplies the hollow image.","exampleCN":"这个词根提供「空腔」意象。"},{"word":"ex-","structure":"ex- (Latin prefix)","meaning":"out","meaningCN":"向外","example":"The prefix adds the direction out.","exampleCN":"这个前缀增添「向外」方向。"},{"word":"excavare","structure":"excavare, excavavi, excavatum (Latin verb, first conjugation)","meaning":"to hollow out, dig out","meaningCN":"挖空；挖出","example":"Latin named the digging act.","exampleCN":"拉丁语命名挖掘动作。"},{"word":"excavation","structure":"excavare + -tio (action noun)","meaning":"the act of digging out","meaningCN":"发掘；挖掘","example":"Excavation began in spring.","exampleCN":"发掘在春季开始。"},{"word":"trenchier","structure":"trenchier (Old French verb)","meaning":"to cut","meaningCN":"切；割","example":"French named the cutting.","exampleCN":"法语命名切割。"},{"word":"trench","structure":"trenche (Old French noun) + English","meaning":"a cut, a ditch","meaningCN":"沟；切口","example":"The trench was narrow.","exampleCN":"这条沟很窄。"},{"word":"trencher","structure":"trench + -er (agent suffix)","meaning":"one who digs; a wooden plate","meaningCN":"挖沟者；木餐盘","example":"The old word also named a plate.","exampleCN":"这个旧词也指木盘。"},{"word":"section","structure":"secare 'to cut' + -tio","meaning":"a cut face for drawing","meaningCN":"剖面；截面","example":"The section was drawn to scale.","exampleCN":"剖面按比例绘制。"}],"latinEntries":[{"word":"cavus","structure":"cavus, -a, -um (Latin adjective)","meaning":"hollow","meaningCN":"空的；空腔的"},{"word":"excavare","structure":"excavare, excavavi, excavatum (verb, first conjugation)","meaning":"to hollow out","meaningCN":"挖空；挖出"},{"word":"excavatio","structure":"excavatio, excavationis (f., third declension)","meaning":"a hollowing out","meaningCN":"挖掘；挖空"}],"derivatives":[{"word":"excavate","pos":"v.","zh":"拉丁 excavare「挖空」→ 发掘；挖出"},{"word":"excavation","pos":"n.","zh":"excavate + -ion（名词后缀）→ 发掘；挖掘"},{"word":"excavator","pos":"n.","zh":"excavate + -or（施事后缀）→ 发掘者；挖掘机"},{"word":"trench","pos":"n.","zh":"古法语 trenche「切出的沟」→ 沟；战壕"},{"word":"trencher","pos":"n.","zh":"trench + -er（施事后缀）→ 挖沟者；木餐盘（旧义）"}]}},{"word":"provenance","ipa_uk":"/ˈprɒvənəns/","ipa_us":"/ˈprɑːvənəns/","definition_zh":"来源；出处；文物或艺术品的流传经历；动植物的原产地","definition_en":"the origin or source of an object; the documented history of ownership of an artwork or artifact","core_image":"策展人摊开一叠旧拍卖目录与收据，把画作的每次转手按年份串起来","scene":"策展人翻看一叠旧拍卖目录，追查画作的流转。The painting's provenance can be traced to a Florentine collection.","sceneCN":"这里 provenance 指「艺术品历次转手与收藏的来源记录」（第 2 个义项：收藏流传史）；句意为这幅画的流传经历可追溯到一批佛罗伦萨旧藏。","pos":[{"tag":"n.","zh":"来源；出处；流传经历；原产地"}],"collocations":[{"phrase":"provenance research","zh":"来源研究"},{"phrase":"provenance record","zh":"来源记录"},{"phrase":"clear provenance","zh":"清晰的流传来源"},{"phrase":"provenance of an artifact","zh":"文物的出处"},{"phrase":"establish provenance","zh":"确定来源"}],"forms":[{"label":"单数","form":"provenance"},{"label":"复数","form":"provenances"},{"label":"相关形容词","form":"provenanced"},{"label":"变体拼写（出土地点）","form":"provenience"},{"label":"同义（来源）","form":"origin"},{"label":"同义（流传史）","form":"chain of custody"}],"derivatives":[{"word":"provenanced","pos":"adj.","zh":"provenance + -ed（形容词后缀）→ 有明确来源的"},{"word":"provenience","pos":"n.","zh":"provenance 的变体 → 出处（考古学常用）"},{"word":"provenir","pos":"v.","zh":"法语 provenir「来自」→ 源自（法语词）"},{"word":"provenire","pos":"v.","zh":"拉丁 provenire「出来、起源」→ 出现；源自"}],"senses":[{"no":"01","title":"The origin or source of an object","titleCN":"物体的来源或出处","definition":"the place, person or process from which an object came","definitionCN":"物体来自的地点、人或过程","example":"The provenance of the stone is a quarry in the north.","exampleCN":"这块石头的来源是北方的一处采石场。","why":"provenir means 'to come forth', so provenance literally names where something came from.","whyCN":"provenir 意为「出来、源自」，因此 provenance 字面就指某物来自何处。"},{"no":"02","title":"The ownership history of an artwork","titleCN":"艺术品的收藏流传史","definition":"the documented sequence of owners and sales through which a work has passed","definitionCN":"一件作品经历的所有者与交易的有记录序列","example":"The painting's provenance can be traced to a Florentine collection.","exampleCN":"这幅画的流传经历可追溯到一批佛罗伦萨旧藏。","why":"owners and sales form a recorded sequence, so origin becomes ownership history.","whyCN":"所有者与交易构成有记录的序列，因此「来源」变成「收藏史」。"},{"no":"03","title":"The native place of a plant or animal","titleCN":"动植物的原产地","definition":"the region where a species or variety naturally originated","definitionCN":"某物种或品种自然起源的地区","example":"Botanists recorded the provenance of each seed lot.","exampleCN":"植物学家记录了每批种子的原产地。","why":"plants also come from somewhere, so the origin question applies to species.","whyCN":"植物也来自某处，因此「来源」问题同样适用于物种。"},{"no":"04","title":"A documented chain of custody","titleCN":"有记录的保管链","definition":"the paper trail of receipts, catalogues and museum records that proves continuous possession","definitionCN":"由收据、目录与博物馆记录构成的书面链条，证明连续持有","example":"Without a chain of custody, the provenance of the mask is incomplete.","exampleCN":"没有保管链，这件面具的来源记录就不完整。","why":"receipts and records prove continuous possession, which is the custody sense.","whyCN":"收据与记录证明连续持有，这就是「保管链」义。"},{"no":"05","title":"The find site of an artifact","titleCN":"文物的出土地点","definition":"the archaeological place where an object was recovered, recorded in site records","definitionCN":"物件被发现的考古地点，记录在遗址档案中","example":"The provenance of the pot is a burial cave in the hills.","exampleCN":"这件陶罐的出土地点是山中的一处墓葬洞穴。","why":"archaeology fixes origin to a recorded find spot.","whyCN":"考古学把「来源」固定在一个有记录的出土地点。"},{"no":"06","title":"Evidence of authenticity","titleCN":"真实性的证据","definition":"the provenance record used to argue that an object is genuine rather than forged","definitionCN":"用来论证物件为真而非赝品的来源记录","example":"The auction house questioned the provenance before accepting the drawing.","exampleCN":"拍卖行在接受这幅素描前质疑了它的来源证据。","why":"a documented trail is used as evidence that the object is not a forgery.","whyCN":"有记录的链条被用作物件并非赝品的证据。"},{"no":"07","title":"The geographic source of a product","titleCN":"产品的地理来源","definition":"the region or country that a food, wine or material is said to come from","definitionCN":"食品、葡萄酒或材料被宣称来自的地区或国家","example":"The label protects the provenance of the cheese.","exampleCN":"这个标签保护这种奶酪的原产地。","why":"food and wine law uses origin as a protected geographic claim.","whyCN":"食品与葡萄酒法规把「来源」用作受保护的地理主张。"},{"no":"08","title":"The origin of a book copy","titleCN":"藏书来源","definition":"the earlier owners and collections of a particular printed copy","definitionCN":"某一特定印本的早期所有者与收藏","example":"The library notes the provenance of each rare book on its catalogue card.","exampleCN":"图书馆在目录卡上注明每本善本的藏书来源。","why":"library catalogues record earlier owners, a narrow book-history use.","whyCN":"图书馆目录记录早期所有者，是「书籍史」的窄用。"}],"etymology":{"intro":{"en":"Provenance comes from French provenance, from provenir 'to come forth', from Latin provenire, built on pro- 'forth' and venire 'to come'. The word names the coming-forth of an object rather than the object itself.","cn":"provenance 来自法语 provenance，源于 provenir「出来、源自」，再上溯拉丁 provenire，由 pro-「向前」与 venire「来」构成。这个词命名物件的「出来之处」，而非物件本身。"},"items":[{"era":"LATIN VENIRE","en":"Venire meant 'to come', the base of many English words from invent to convene.","cn":"venire 意为「来」，是 invent 到 convene 等许多英语词的基础。"},{"era":"LATIN PROVENIRE","en":"Pro- 'forth' plus venire gave provenire, 'to come forth, to originate'.","cn":"pro-「向前」加 venire 构成 provenire，意为「出来、起源」。"},{"era":"FRENCH PROVENIR","en":"French provenir kept the sense of coming from a source.","cn":"法语 provenir 保留「来自某处」的意思。"},{"era":"FRENCH PROVENANCE","en":"The noun provenance named the fact or place of origin, and English borrowed it in the seventeenth century.","cn":"名词 provenance 指来源这一事实或地点，英语在十七世纪借入。"},{"era":"ART MARKET","en":"Collectors and dealers narrowed the word to the documented ownership history of valuable objects.","cn":"收藏家与经销商把这个词收窄为贵重物件的书面收藏史。"},{"era":"SOURCE UNCERTAIN","en":"Source uncertain (first date only): the earliest English use is dated differently across dictionaries, though the French and Latin chain is clear.","cn":"来源不确定（仅首见年代存疑）：各词典给出的英语首见年代不一，但法语与拉丁链条清楚。"}]},"similar":{"note":{"en":"Group one holds origin words easily confused with provenance; group two holds words for where a thing comes from.","cn":"第一组是容易与 provenance 混淆的来源词；第二组是表示事物来处的词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"provenience","ipa":"/prəˈviːniəns/","tag":"an archaeological variant","definition":"A variant spelling used in archaeology for the find site of an object; provenance is the standard art-market word.","definitionCN":"考古学中用于出土地点的变体拼写；provenance 是艺术市场标准词。"},{"word":"provenance","ipa":"/ˈprɒvənəns/","tag":"the standard form","definition":"The usual spelling for origin and ownership history; the variant form above is narrower and rarer.","definitionCN":"表示来源与收藏史的常用拼写；上方的变体更窄也更罕见。"},{"word":"provenient","ipa":"/prəˈviːniənt/","tag":"coming from","definition":"An rare adjective meaning 'originating from'; it describes a source rather than records one.","definitionCN":"罕见形容词，意为「源自」；它描述来源，而非记录来源。"},{"word":"provisory","ipa":"/prəˈvaɪzəri/","tag":"temporary","definition":"Provisional or conditional; it sounds similar but belongs to a different root.","definitionCN":"临时的或有条件的；发音相近，但属于不同词根。"}]},{"heading":"NEAR MEANING","entries":[{"word":"origin","ipa":"/ˈɒrɪdʒɪn/","tag":"the starting point","definition":"The point where something begins; provenance adds documentation and ownership history.","definitionCN":"事物开始之处；provenance 增添了文献记录与收藏史。"},{"word":"source","ipa":"/sɔːs/","tag":"where something comes from","definition":"The place or thing something comes from; it is broader and needs no paper trail.","definitionCN":"事物来自的地点或东西；范围更广，不要求书面链条。"},{"word":"pedigree","ipa":"/ˈpedɪɡriː/","tag":"a recorded ancestry","definition":"A recorded line of descent, used of animals, people or objects; provenance is the object's version.","definitionCN":"有记录的世系，用于动物、人或物件；provenance 是物件版。"},{"word":"history","ipa":"/ˈhɪstəri/","tag":"the past record","definition":"The whole past of a thing; provenance is the specific record of where and through whose hands it came.","definitionCN":"事物的全部过去；provenance 是它来自何处、经过谁手的特定记录。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: the Latin coming verb, the French noun and the real auction paper trail.","cn":"正常联想：拉丁「来」动词、法语名词与真实的拍卖文书链。"},"normal":[{"en":"pro- 'forth' plus venire 'come' gives 'come forth'.","cn":"pro-「向前」加 venire「来」构成「出来」。"},{"en":"The same venire runs through invent, convene and advent.","cn":"同一个 venire 贯穿 invent、convene 与 advent。"},{"en":"Provenance is proved by receipts, catalogues and museum records.","cn":"来源由收据、目录与博物馆记录证明。"},{"en":"A clear provenance raises both value and authenticity.","cn":"清晰的来源同时提升价值与真实性。"},{"en":"Provenience is the archaeologist's variant for find site.","cn":"provenience 是考古学家指出土地点的变体。"}],"abstract":[{"en":"Provenance is the paper shadow that follows an object through time.","cn":"来源是跟着物件穿越时间的纸质影子。"},{"en":"It is a chain of hands, written down.","cn":"它是一条被写下来的手手相传之链。"},{"en":"An object without provenance is a voice without a name.","cn":"没有来源的物件，是一个没有名字的声音。"}]},"examples":[{"en":"The museum published the provenance of every object in the show.","cn":"博物馆公布了展览中每件物品的来源。"},{"en":"The manuscript's provenance includes a monastery library.","cn":"这份手稿的流传经历包括一座修道院图书馆。"},{"en":"Scientists tested the provenance of the marble with isotope analysis.","cn":"科学家用同位素分析检测大理石的原产地。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「pro（向前）+ ven（来）」——从某处出来的 → 来源、出处","word":"provenance"},"root":"法语 provenance ← provenir「出来、源自」← 拉丁 provenire「出来、起源」= pro-「向前」+ venire「来」。英语十七世纪借入，后收窄为艺术品与文物的流传来源记录。","sensesIntro":{"en":"Eight senses follow a coming-forth: an object's source, an art work's owners, a plant's native range, a custody trail, a find site, proof of authenticity, a product's region and a book's earlier owners.","cn":"八个义项沿「出来之处」展开：物件来源、艺术品藏家、植物原产地、保管链、出土地点、真实性证明、产品产区与藏书旧主。"},"semanticMap":{"core":{"en":"CORE IMAGE: a stack of old receipts and catalogues tracing one object hand by hand back to its first home.","cn":"核心意象：一叠旧收据与目录，把一件物件一手接一手地追溯回最初的家。"},"chain":["COME FORTH","OBJECT SOURCE","OWNERSHIP TRAIL","FIND SITE","AUTHENTICITY","BOOK HISTORY"],"branches":[{"senses":"义项 01、义项 03","en":"WHERE IT CAME FROM: an object's source and a plant's native range are the same origin question for different things.","cn":"来自何处：物件来源与植物原产地是不同事物的同一来源问题。"},{"senses":"义项 02、义项 04","en":"DOCUMENTED HANDS: ownership history and chain of custody are the same paper trail at narrative and evidential levels.","cn":"有记录的手：收藏史与保管链是同一纸质链条的叙述面与证据面。"},{"senses":"义项 05","en":"FIND SITE: archaeology fixes the coming-forth to a place in the ground.","cn":"出土地点：考古学把「出来之处」固定在土地中的某一点。"},{"senses":"义项 06","en":"PROOF: a clean trail becomes evidence that the object is genuine.","cn":"证明：干净的链条成为物件为真的证据。"},{"senses":"义项 07、义项 08","en":"PLACE AND BOOK: a product's region and a copy's earlier owners are two narrower uses of the same origin record.","cn":"产地与藏书：产品产区与印本旧主是同一来源记录的两种窄用。"}]},"affixes":{"intro":{"en":"Provenance is a French noun on a Latin verb, and its root also builds a large family of coming words.","cn":"provenance 是建立在拉丁动词之上的法语名词，其词根还构成一大串表示「来」的词。"},"latinIntro":{"en":"Latin venire gives invent, convene, advent and event; pro- adds the direction 'forth'.","cn":"拉丁 venire 衍生 invent、convene、advent 与 event；pro- 增添「向前」方向。"},"items":[{"word":"venire","structure":"venire, veni, ventum (Latin verb, fourth conjugation)","meaning":"to come","meaningCN":"来","example":"The root names coming.","exampleCN":"这个词根命名「来」。"},{"word":"pro-","structure":"pro- (Latin prefix)","meaning":"forth, forward","meaningCN":"向前；向外","example":"The prefix adds direction out.","exampleCN":"这个前缀增添向外方向。"},{"word":"provenire","structure":"provenire, proveni, proventum (Latin verb, fourth conjugation)","meaning":"to come forth, originate","meaningCN":"出来；起源","example":"Latin named the coming forth.","exampleCN":"拉丁语命名「出来」。"},{"word":"provenir","structure":"provenir (French verb, from Latin)","meaning":"to come from","meaningCN":"来自","example":"French kept the source sense.","exampleCN":"法语保留来源义。"},{"word":"provenance","structure":"provenance (French noun) + English","meaning":"origin, source","meaningCN":"来源；出处","example":"English borrowed the noun.","exampleCN":"英语借入这个名词。"},{"word":"provenience","structure":"provenance + English variant","meaning":"find site in archaeology","meaningCN":"考古出土地点","example":"Provenience is the dig-side term.","exampleCN":"provenience 是发掘现场用语。"},{"word":"invent","structure":"in- + venire","meaning":"to come upon","meaningCN":"遇到；发明","example":"Invent shares the coming root.","exampleCN":"invent 共享「来」词根。"},{"word":"convene","structure":"con- + venire","meaning":"to come together","meaningCN":"召集；集合","example":"Convene brings people together.","exampleCN":"convene 把人聚到一起。"}],"latinEntries":[{"word":"venire","structure":"venire, veni, ventum (verb, fourth conjugation)","meaning":"to come","meaningCN":"来"},{"word":"provenire","structure":"provenire, proveni, proventum (verb, fourth conjugation)","meaning":"to come forth","meaningCN":"出来；起源"}],"derivatives":[{"word":"provenanced","pos":"adj.","zh":"provenance + -ed（形容词后缀）→ 有明确来源的"},{"word":"provenience","pos":"n.","zh":"provenance 的变体 → 出土地点（考古学）"},{"word":"provenir","pos":"v.","zh":"法语 provenir「来自」→ 源自（法语词）"},{"word":"provenire","pos":"v.","zh":"拉丁 provenire「出来、起源」→ 出现；源自"}]}}]);
